CREATE OR REPLACE FUNCTION "public"."_gen_unique_agent_code"("len" integer DEFAULT 8) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare
  candidate text;
  tries int := 0;
begin
  loop
    -- stringa breve e leggibile: es. AG-1a2b3c4d
    candidate := 'AG-' || substr(encode(digest(gen_random_uuid()::text, 'sha256'), 'hex'), 1, len);
    exit when not exists (select 1 from public.profiles p where p.agent_code = candidate);
    tries := tries + 1;
    if tries > 20 then
      raise exception 'Impossibile generare agent_code unico dopo % tentativi', tries;
    end if;
  end loop;
  return candidate;
end;
$$;


ALTER FUNCTION "public"."_gen_unique_agent_code"("len" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_set_buzz_week"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.created_at IS NULL THEN NEW.created_at := now(); END IF;
  NEW.week := EXTRACT(WEEK FROM (NEW.created_at AT TIME ZONE 'utc'))::int;
  RETURN NEW;
END;
$$;


