CREATE OR REPLACE FUNCTION "public"."_upsert_premium_feed_source"("p_id" "text", "p_locale" "text", "p_kind" "text", "p_url" "text", "p_tags" "text"[], "p_keywords" "text"[], "p_weight" integer, "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin
  insert into public.external_feed_sources (id, locale, kind, url, tags, keywords, weight, enabled)
  values (p_id, p_locale, p_kind, p_url, p_tags, p_keywords, p_weight, p_enabled)
  on conflict (id) do update
  set locale = excluded.locale,
      kind   = excluded.kind,
      url    = excluded.url,
      tags   = excluded.tags,
      keywords = excluded.keywords,
      weight  = excluded.weight,
      enabled = excluded.enabled,
      updated_at = now();
end $$;


