CREATE OR REPLACE FUNCTION "public"."admin_credit_m1u"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_balance INTEGER;
  v_new_balance INTEGER;
BEGIN
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
  END IF;
  
  SELECT m1_units INTO v_old_balance FROM public.profiles WHERE id = p_user_id;
  
  IF v_old_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'user_not_found');
  END IF;
  
  v_new_balance := v_old_balance + p_amount;
  
  UPDATE public.profiles
  SET m1_units = v_new_balance, updated_at = NOW()
  WHERE id = p_user_id;
  
  BEGIN
    INSERT INTO public.user_m1_units_events (user_id, delta, reason, metadata)
    VALUES (p_user_id, p_amount, p_reason,
      jsonb_build_object('old_balance', v_old_balance, 'new_balance', v_new_balance, 'credited_by', 'admin_credit_m1u', 'timestamp', NOW())
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  
  RETURN jsonb_build_object('success', true, 'old_balance', v_old_balance, 'new_balance', v_new_balance);
END;
$$;


ALTER FUNCTION "public"."admin_credit_m1u"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_credit_pulse_energy"("p_user_id" "uuid", "p_amount" numeric, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_balance NUMERIC;
  v_new_balance NUMERIC;
BEGIN
  -- Only service_role can call this
  IF session_user != 'service_role' AND session_user != 'postgres' THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;
  
  -- Validate amount
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
  END IF;
  
  -- Get current balance
  SELECT pulse_energy INTO v_old_balance FROM public.profiles WHERE id = p_user_id;
  
  IF v_old_balance IS NULL THEN
    v_old_balance := 0;
  END IF;
  
  -- Update balance
  v_new_balance := v_old_balance + p_amount;
  
  UPDATE public.profiles
  SET pulse_energy = v_new_balance, updated_at = NOW()
  WHERE id = p_user_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'old_balance', v_old_balance,
    'new_balance', v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."admin_credit_pulse_energy"("p_user_id" "uuid", "p_amount" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_marker"("p_marker_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_role TEXT;
BEGIN
  -- Verifica admin
  SELECT role INTO v_user_role FROM profiles WHERE id = auth.uid();
  
  IF v_user_role IS NULL OR lower(v_user_role) NOT IN ('admin', 'owner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;
  
  -- Elimina in cascata
  DELETE FROM marker_rewards WHERE marker_id = p_marker_id;
  DELETE FROM marker_claims WHERE marker_id = p_marker_id;
  DELETE FROM markers WHERE id = p_marker_id;
  
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."admin_delete_marker"("p_marker_id" "uuid") OWNER TO "postgres";


