    BEGIN DELETE FROM public.push_subscriptions WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.auto_push_log WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.smart_push_log WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.admin_logs WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.cashback_vault WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.cashback_claims WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.user_buzz_weekly WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
