    BEGIN DELETE FROM public.streak_badges WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.achievement_badges WHERE user_id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN DELETE FROM public.profiles WHERE id = user_uuid; EXCEPTION WHEN OTHERS THEN NULL; END;
    
    RETURN 'Utente ' || user_uuid || ' pronto per cancellazione da dashboard';
END;
$$;


