CREATE OR REPLACE FUNCTION "public"."admin_get_lottery_analytics"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
BEGIN
  -- Verifica admin
  v_user_id := auth.uid();
  
  SELECT role INTO v_user_role
  FROM public.profiles
  WHERE id = v_user_id;
  
  IF v_user_role NOT IN ('admin', 'owner') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'UNAUTHORIZED',
      'message', 'Solo gli admin possono vedere le analytics'
    );
  END IF;
  
  RETURN jsonb_build_object(
    'status', 'success',
    
    -- Cicli totali
    'cycles', (
      SELECT jsonb_build_object(
        'total', COUNT(*),
        'active', COUNT(*) FILTER (WHERE status = 'active'),
        'completed', COUNT(*) FILTER (WHERE status = 'completed'),
        'cancelled', COUNT(*) FILTER (WHERE status = 'cancelled')
      )
      FROM public.mission_cycles
    ),
    
    -- Vendite totali
    'sales', (
      SELECT jsonb_build_object(
        'total_purchases', COUNT(*),
        'total_tickets', SUM(tickets_count),
        'total_m1u', SUM(total_m1u),
        'unique_users', COUNT(DISTINCT user_id)
      )
      FROM public.lottery_purchases
      WHERE status = 'completed'
    ),
    
    -- Premi distribuiti
    'prizes', (
      SELECT jsonb_build_object(
        'total_winners', COUNT(*),
        'total_m1u_awarded', SUM(prize_amount),
        'avg_prize', ROUND(AVG(prize_amount), 2)
      )
      FROM public.lottery_tickets
      WHERE status = 'winner' AND prize_amount > 0
    ),
    
    -- Ultimi 10 cicli
    'recent_cycles', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', mc.id,
        'status', mc.status,
        'starts_at', mc.starts_at,
        'ends_at', mc.ends_at,
        'total_tickets', mc.total_tickets,
        'total_participants', mc.total_participants,
        'prize_pool_total', mc.prize_pool_total,
        'prize_multiplier', mc.prize_multiplier
      ) ORDER BY mc.created_at DESC)
      FROM public.mission_cycles mc
      LIMIT 10
    ),
    
    -- Ultimi 20 acquisti
    'recent_purchases', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', lp.id,
        'user_id', lp.user_id,
        'tickets_count', lp.tickets_count,
        'total_m1u', lp.total_m1u,
        'created_at', lp.created_at
      ) ORDER BY lp.created_at DESC)
      FROM public.lottery_purchases lp
      WHERE lp.status = 'completed'
      LIMIT 20
    )
  );
END;
$$;


ALTER FUNCTION "public"."admin_get_lottery_analytics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_lottery_analytics"() IS 'M1SSION™ Lottery - Analytics complete per admin.';



CREATE OR REPLACE FUNCTION "public"."admin_reset_scratch_purchases"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted INT;
BEGIN
  -- Rimuovi il trigger temporaneamente per questa sessione
  SET session_replication_role = 'replica';
  
  DELETE FROM public.user_scratch_purchases 
  WHERE user_id = p_user_id
  AND created_at > CURRENT_DATE;
  
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  
  -- Ripristina
  SET session_replication_role = 'origin';
  
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."admin_reset_scratch_purchases"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_rag_search"("query_embedding" "public"."vector", "match_threshold" double precision DEFAULT 0.7, "match_count" integer DEFAULT 6) RETURNS TABLE("doc_id" "uuid", "title" "text", "chunk_text" "text", "similarity" double precision)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    e.doc_id,
    d.title,
    e.chunk_text,
    1 - (e.embedding <=> query_embedding) as similarity
  FROM public.ai_docs_embeddings e
  JOIN public.ai_docs d ON d.id = e.doc_id
  WHERE 1 - (e.embedding <=> query_embedding) > match_threshold
  ORDER BY e.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."ai_rag_search"("query_embedding" "public"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_rag_search_vec"("query_embedding" double precision[], "match_count" integer DEFAULT 3, "in_locale" "text" DEFAULT 'it'::"text") RETURNS TABLE("doc_id" "uuid", "title" "text", "category" "text", "locale" "text", "chunk_idx" integer, "chunk_text" "text", "distance" real)
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  return query
  select
    d.id as doc_id,
    d.title,
    d.category,
    d.locale,
    e.chunk_idx,
    e.chunk_text,
    (e.embedding <=> (query_embedding)::vector(768))::real as distance
  from public.ai_docs_embeddings e
  join public.ai_docs d on d.id = e.doc_id
  where d.locale = in_locale
  order by e.embedding <=> (query_embedding)::vector(768)
  limit match_count;
end;
$$;


ALTER FUNCTION "public"."ai_rag_search_vec"("query_embedding" double precision[], "match_count" integer, "in_locale" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_rag_search_vec_json"("payload" "jsonb") RETURNS TABLE("doc_id" "uuid", "title" "text", "category" "text", "locale" "text", "chunk_idx" integer, "chunk_text" "text", "distance" real)
    LANGUAGE "sql" STABLE
    AS $$    with args as (      select        (payload->'query_embedding')::jsonb        as emb_json,        coalesce((payload->>'match_count')::int,3) as match_count,        coalesce(payload->>'in_locale','it')       as in_locale    )    select      d.id, d.title, d.category, d.locale,      e.chunk_idx, e.chunk_text,      e.embedding <=> ((select array_agg((v->>0)::float8) from jsonb_array_elements((select emb_json from args)) as v))::vector as distance    from public.ai_docs_embeddings e    join public.ai_docs d on d.id = e.doc_id    where d.locale = (select in_locale from args)    order by distance    limit (select match_count from args)  $$;


ALTER FUNCTION "public"."ai_rag_search_vec_json"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_rag_search_vec_json"("qvec" "public"."vector", "k" integer, "minscore" double precision) RETURNS "json"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(JSON_AGG(x), '[]'::JSON) FROM (
    SELECT 
      d.id,
      d.title,
      e.chunk_text AS chunk,
      (1 - (e.embedding <=> qvec))::FLOAT AS score
    FROM public.ai_docs_embeddings e
    JOIN public.ai_docs d ON d.id = e.doc_id
    WHERE (1 - (e.embedding <=> qvec)) >= minscore
    ORDER BY e.embedding <=> qvec ASC 
    LIMIT k
  ) x
$$;


