CREATE OR REPLACE FUNCTION "public"."apply_referral_code"("p_referred_user_id" "uuid", "p_referral_code" character varying) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_referrer_id UUID; v_already_referred BOOLEAN;
  v_referrer_reward INTEGER := 50; v_referred_reward INTEGER := 50;
BEGIN
  SELECT referred_by IS NOT NULL INTO v_already_referred FROM profiles WHERE id = p_referred_user_id;
  IF v_already_referred THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_referred', 'message', 'Hai già usato un codice');
  END IF;
  
  SELECT id INTO v_referrer_id FROM profiles WHERE referral_code = UPPER(p_referral_code);
  IF v_referrer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_code', 'message', 'Codice non valido');
  END IF;
  
  IF v_referrer_id = p_referred_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'self_referral', 'message', 'Non puoi usare il tuo codice');
  END IF;
  
  UPDATE profiles SET referred_by = v_referrer_id WHERE id = p_referred_user_id;
  
  INSERT INTO referral_rewards (referrer_id, referred_id, referrer_reward, referred_reward, status, completed_at)
  VALUES (v_referrer_id, p_referred_user_id, v_referrer_reward, v_referred_reward, 'completed', NOW());
  
  PERFORM admin_credit_m1u(v_referrer_id, v_referrer_reward, 'referral_bonus_referrer');
  PERFORM admin_credit_m1u(p_referred_user_id, v_referred_reward, 'referral_bonus_referred');
  
  RETURN jsonb_build_object('success', true, 'referrer_reward', v_referrer_reward, 
    'referred_reward', v_referred_reward, 'message', 'Bonus applicato! +50 M1U!');
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


