CREATE OR REPLACE FUNCTION "public"."audit_battle"("p_battle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_battle           public.battles%ROWTYPE;
  v_audit_count      INTEGER;
  v_rng_count        INTEGER;
  v_resolved_audits  INTEGER;
  v_transfer_count   INTEGER;
  v_flags            TEXT[] := ARRAY[]::TEXT[];
  v_is_clean         BOOLEAN;
BEGIN
  -- Basic battle existence
  SELECT * INTO v_battle
  FROM public.battles
  WHERE id = p_battle_id;

  IF NOT FOUND THEN
    v_flags := array_append(v_flags, 'BATTLE_NOT_FOUND');
    RETURN jsonb_build_object(
      'battle_id',     p_battle_id,
      'status',        NULL,
      'rng_check',     'missing',
      'ledger_check',  'incomplete',
      'tamper_flags',  v_flags,
      'audit_summary', jsonb_build_object('is_clean', false)
    );
  END IF;

  -- Audit stats
  SELECT
    COUNT(*)                             AS audit_count,
    COUNT(rng_seed)                      AS rng_count,
    COUNT(*) FILTER (WHERE event_type = 'resolved') AS resolved_audits
  INTO
    v_audit_count,
    v_rng_count,
    v_resolved_audits
  FROM public.battle_audit
  WHERE battle_id = p_battle_id;

  IF v_audit_count = 0 THEN
    v_flags := array_append(v_flags, 'AUDIT_LOG_EMPTY');
  END IF;

  IF v_rng_count < v_audit_count THEN
    v_flags := array_append(v_flags, 'RNG_SEED_MISSING');
  END IF;

  IF v_resolved_audits > 1 THEN
    v_flags := array_append(v_flags, 'DUPLICATE_RESOLVED_BATTLE');
  END IF;

  -- Transfers
  SELECT COUNT(*)
  INTO v_transfer_count
  FROM public.battle_transfers t
  WHERE t.battle_id = p_battle_id;

  IF v_battle.status = 'resolved' AND v_transfer_count = 0 THEN
    v_flags := array_append(v_flags, 'NO_STAKE_TRANSFER');
  END IF;

  IF v_battle.status = 'resolved' AND v_battle.winner_id IS NULL THEN
    v_flags := array_append(v_flags, 'RESOLVED_NO_WINNER');
  END IF;

  v_is_clean := (array_length(v_flags, 1) IS NULL);

  RETURN jsonb_build_object(
    'battle_id',    p_battle_id,
    'status',       v_battle.status,
    'rng_check',    CASE WHEN v_rng_count < v_audit_count THEN 'missing' ELSE 'ok' END,
    'ledger_check', CASE WHEN v_battle.status = 'resolved' AND v_transfer_count = 0 THEN 'incomplete' ELSE 'ok' END,
    'tamper_flags', COALESCE(v_flags, ARRAY[]::TEXT[]),
    'audit_summary', jsonb_build_object('is_clean', v_is_clean)
  );
END;
$$;


ALTER FUNCTION "public"."audit_battle"("p_battle_id" "uuid") OWNER TO "postgres";


