CREATE OR REPLACE FUNCTION "public"."award_badge"("p_user_id" "uuid", "p_badge_name" "text", "p_source" "text" DEFAULT 'system'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_badge RECORD;
  v_already_has BOOLEAN;
BEGIN
  SELECT badge_id, name, icon, xp_reward, rarity INTO v_badge
  FROM public.badges WHERE name = p_badge_name;
  
  IF v_badge.badge_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Badge not found');
  END IF;
  
  SELECT EXISTS(SELECT 1 FROM public.user_badges WHERE user_id = p_user_id AND badge_id = v_badge.badge_id) INTO v_already_has;
  
  IF v_already_has THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already unlocked');
  END IF;
  
  INSERT INTO public.user_badges (user_id, badge_id, source) VALUES (p_user_id, v_badge.badge_id, p_source);
  
  UPDATE public.profiles SET pulse_energy = COALESCE(pulse_energy, 0) + v_badge.xp_reward WHERE id = p_user_id;
  
  RETURN jsonb_build_object('success', true, 'badge_name', v_badge.name, 'badge_icon', v_badge.icon, 'xp_awarded', v_badge.xp_reward, 'rarity', v_badge.rarity);
END;
$$;


ALTER FUNCTION "public"."award_badge"("p_user_id" "uuid", "p_badge_name" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_pulse_energy"("p_user_id" "uuid", "p_delta_pe" integer, "p_reason" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_pe INT;
  v_new_pe INT;
  v_old_rank_id INT;
  v_new_rank_id INT;
  v_rank_changed BOOLEAN := FALSE;
BEGIN
  -- Lock profile row for update
  SELECT pulse_energy, rank_id INTO v_old_pe, v_old_rank_id
  FROM profiles
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User % not found in profiles', p_user_id;
  END IF;

  -- Calculate new PE
  v_new_pe := v_old_pe + p_delta_pe;

  -- Update pulse_energy in profiles
  UPDATE profiles
  SET 
    pulse_energy = v_new_pe,
    updated_at = NOW()
  WHERE id = p_user_id;

  -- Sync user_xp for backward compatibility
  UPDATE user_xp
  SET 
    total_xp = v_new_pe,
    xp_since_reward = xp_since_reward + p_delta_pe
  WHERE user_id = p_user_id;

  -- Recompute rank based on new PE
  SELECT id INTO v_new_rank_id
  FROM agent_ranks
  WHERE pe_min <= v_new_pe
    AND (pe_max IS NULL OR v_new_pe < pe_max)
  ORDER BY pe_min DESC
  LIMIT 1;

  -- Check if rank changed
  IF v_new_rank_id IS DISTINCT FROM v_old_rank_id THEN
    v_rank_changed := TRUE;

    -- Update rank in profiles
    UPDATE profiles
    SET 
      rank_id = v_new_rank_id,
      rank_updated_at = NOW()
    WHERE id = p_user_id;

    -- Log rank change in history
    INSERT INTO rank_history (user_id, old_rank_id, new_rank_id, delta_pe, reason, metadata)
    VALUES (p_user_id, v_old_rank_id, v_new_rank_id, p_delta_pe, p_reason, p_metadata);
  END IF;

  -- Return result JSON
  RETURN jsonb_build_object(
    'success', TRUE,
    'old_pe', v_old_pe,
    'new_pe', v_new_pe,
    'delta_pe', p_delta_pe,
    'rank_changed', v_rank_changed,
    'old_rank_id', v_old_rank_id,
    'new_rank_id', v_new_rank_id,
    'timestamp', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."award_pulse_energy"("p_user_id" "uuid", "p_delta_pe" integer, "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_streak_badge"("p_user_id" "uuid", "p_streak_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_badge_id UUID;
  v_badge_name TEXT;
  v_badge_icon TEXT;
  v_badges_awarded JSONB := '[]'::JSONB;
  v_milestone INTEGER;
  v_milestones INTEGER[] := ARRAY[5, 10, 15, 25, 30, 50, 100];
BEGIN
  -- Check each milestone
  FOREACH v_milestone IN ARRAY v_milestones
  LOOP
    IF p_streak_days >= v_milestone THEN
      -- Get badge info
      SELECT badge_id, name, icon INTO v_badge_id, v_badge_name, v_badge_icon
      FROM public.badges
      WHERE name = 'streak_' || v_milestone || '_days';
      
      IF v_badge_id IS NOT NULL THEN
        -- Award badge if not already awarded
        INSERT INTO public.user_badges (user_id, badge_id, source)
        VALUES (p_user_id, v_badge_id, 'streak_milestone')
        ON CONFLICT (user_id, badge_id, source) DO NOTHING;
        
        -- If inserted, add to result
        IF FOUND THEN
          v_badges_awarded := v_badges_awarded || jsonb_build_object(
            'badge_id', v_badge_id,
            'name', v_badge_name,
            'icon', v_badge_icon,
            'milestone', v_milestone
          );
        END IF;
      END IF;
    END IF;
  END LOOP;
  
  RETURN v_badges_awarded;
END;
$$;


ALTER FUNCTION "public"."award_streak_badge"("p_user_id" "uuid", "p_streak_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_streak_badge"("p_user_id" "uuid", "p_streak_days" integer) IS 'Awards streak milestone badges to user';



CREATE OR REPLACE FUNCTION "public"."award_xp"("p_user_id" "uuid", "p_xp_amount" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_xp_record RECORD;
  new_total_xp INTEGER;
  new_xp_since_reward INTEGER;
  buzz_rewards INTEGER := 0;
  buzz_map_rewards INTEGER := 0;
BEGIN
  -- Get or create user XP record
  INSERT INTO public.user_xp (user_id, total_xp, xp_since_reward)
  VALUES (p_user_id, 0, 0)
  ON CONFLICT (user_id) DO NOTHING;
  
  -- Get current XP
  SELECT total_xp, xp_since_reward INTO current_xp_record
  FROM public.user_xp
  WHERE user_id = p_user_id;
  
  -- Calculate new values
  new_total_xp := current_xp_record.total_xp + p_xp_amount;
  new_xp_since_reward := current_xp_record.xp_since_reward + p_xp_amount;
  
  -- Calculate buzz rewards (every 100 XP)
  IF new_xp_since_reward >= 100 THEN
    buzz_rewards := new_xp_since_reward / 100;
    new_xp_since_reward := new_xp_since_reward % 100;
  END IF;
  
  -- Calculate buzz map rewards (every 250 XP from total)
  IF new_total_xp >= 250 AND current_xp_record.total_xp < 250 THEN
    buzz_map_rewards := (new_total_xp / 250) - (current_xp_record.total_xp / 250);
  END IF;
  
  -- Update XP
  UPDATE public.user_xp
  SET 
    total_xp = new_total_xp,
    xp_since_reward = new_xp_since_reward,
    updated_at = now()
  WHERE user_id = p_user_id;
  
  -- Award credits if any
  IF buzz_rewards > 0 OR buzz_map_rewards > 0 THEN
    INSERT INTO public.user_credits (user_id, free_buzz_credit, free_buzz_map_credit)
    VALUES (p_user_id, buzz_rewards, buzz_map_rewards)
    ON CONFLICT (user_id) 
    DO UPDATE SET
      free_buzz_credit = user_credits.free_buzz_credit + buzz_rewards,
      free_buzz_map_credit = user_credits.free_buzz_map_credit + buzz_map_rewards,
      updated_at = now();
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'xp_awarded', p_xp_amount,
    'total_xp', new_total_xp,
    'buzz_rewards', buzz_rewards,
    'buzz_map_rewards', buzz_map_rewards
  );
END;
$$;


ALTER FUNCTION "public"."award_xp"("p_user_id" "uuid", "p_xp_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_xp"("p_user_id" "uuid", "p_xp_amount" integer, "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_xp INTEGER;
  v_new_total_xp INTEGER;
  v_buzz_progress INTEGER;
  v_map_progress INTEGER;
BEGIN
  -- Get current XP status
  SELECT 
    COALESCE(total_xp, 0),
    COALESCE(buzz_xp_progress, 0),
    COALESCE(map_xp_progress, 0)
  INTO v_current_xp, v_buzz_progress, v_map_progress
  FROM public.user_xp
  WHERE user_id = p_user_id;
  
  -- If user doesn't exist in user_xp, create entry
  IF NOT FOUND THEN
    INSERT INTO public.user_xp (user_id, total_xp, buzz_xp_progress, map_xp_progress)
    VALUES (p_user_id, 0, 0, 0);
    v_current_xp := 0;
    v_buzz_progress := 0;
    v_map_progress := 0;
  END IF;
  
  -- Calculate new totals
  v_new_total_xp := v_current_xp + p_xp_amount;
  
  -- Update based on source
  IF p_source = 'buzz' THEN
    v_buzz_progress := v_buzz_progress + p_xp_amount;
  ELSIF p_source = 'buzz_map' THEN
    v_map_progress := v_map_progress + p_xp_amount;
  ELSIF p_source IN ('daily_checkin', 'weekly_podium', 'mission_complete') THEN
    -- These sources add to both progress bars
    v_buzz_progress := v_buzz_progress + p_xp_amount;
    v_map_progress := v_map_progress + p_xp_amount;
  END IF;
  
  -- Check if user earned free buzz credit (every 100 XP)
  IF v_buzz_progress >= 100 THEN
    -- Award free buzz credits
    INSERT INTO public.user_credits (user_id, free_buzz_credit)
    VALUES (p_user_id, v_buzz_progress / 100)
    ON CONFLICT (user_id) DO UPDATE
    SET free_buzz_credit = user_credits.free_buzz_credit + (v_buzz_progress / 100);
    
    -- Reset progress, keeping remainder
    v_buzz_progress := v_buzz_progress % 100;
  END IF;
  
  -- Check if user earned free buzz map credit (every 250 XP)
  IF v_map_progress >= 250 THEN
    -- Award free buzz map credits
    INSERT INTO public.user_credits (user_id, free_buzz_map_credit)
    VALUES (p_user_id, v_map_progress / 250)
    ON CONFLICT (user_id) DO UPDATE
    SET free_buzz_map_credit = user_credits.free_buzz_map_credit + (v_map_progress / 250);
    
    -- Reset progress, keeping remainder
    v_map_progress := v_map_progress % 250;
  END IF;
  
  -- Update user_xp
  UPDATE public.user_xp
  SET 
    total_xp = v_new_total_xp,
    buzz_xp_progress = v_buzz_progress,
    map_xp_progress = v_map_progress,
    updated_at = NOW()
  WHERE user_id = p_user_id;
  
  -- 🆕 SYNC PULSE ENERGY + RANK (Bridge XP→PE)
  PERFORM award_pulse_energy(p_user_id, p_xp_amount, p_source, jsonb_build_object('xp_sync', true));
  
  -- Log XP transaction
  INSERT INTO public.xp_transactions (user_id, xp_amount, source, description)
  VALUES (p_user_id, p_xp_amount, p_source, 'XP awarded via ' || p_source);
END;
$$;


ALTER FUNCTION "public"."award_xp"("p_user_id" "uuid", "p_xp_amount" integer, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."battle_apply_transfer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Deduct from loser
  IF NEW.transfer_type = 'energy' THEN
    UPDATE public.profiles
    SET energy_fragments = GREATEST(0, COALESCE(energy_fragments, 0) - NEW.amount)
    WHERE id = NEW.from_user_id;
    
    -- Add to winner
    UPDATE public.profiles
    SET energy_fragments = COALESCE(energy_fragments, 0) + NEW.amount
    WHERE id = NEW.to_user_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."battle_apply_transfer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."battle_audit_set_rng_seed"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.rng_seed IS NULL THEN
    NEW.rng_seed :=
      public.compute_battle_rng_seed(
        NEW.battle_id,
        NEW.event_type,
        COALESCE(NEW."timestamp", now())
      );
  END IF;

  IF NEW.created_by IS NULL THEN
    NEW.created_by := NEW.user_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."battle_audit_set_rng_seed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."battle_auto_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO public.battle_audit (battle_id, event_type, payload)
    VALUES (
      NEW.id,
      'status_change',
      jsonb_build_object(
        'old_status', OLD.status,
        'new_status', NEW.status,
        'timestamp', now()
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."battle_auto_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."battle_resolve_stakes"("p_battle_id" "uuid", "p_winner_id" "uuid", "p_loser_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_battle RECORD;
  v_stake_type TEXT;
  v_stake_percentage INTEGER;
  v_loser_balance INTEGER;
  v_transfer_amount INTEGER;
BEGIN
  SELECT * INTO v_battle FROM public.battles WHERE id = p_battle_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Battle not found');
  END IF;

  v_stake_type := v_battle.stake_type;
  v_stake_percentage := v_battle.stake_percentage;

  IF v_stake_type = 'm1u' THEN
    SELECT COALESCE(m1_units, 0) INTO v_loser_balance FROM public.profiles WHERE id = p_loser_id;
    v_transfer_amount := FLOOR(v_loser_balance * v_stake_percentage / 100);
    
    UPDATE public.profiles SET m1_units = m1_units - v_transfer_amount WHERE id = p_loser_id;
    UPDATE public.profiles SET m1_units = m1_units + v_transfer_amount WHERE id = p_winner_id;

  ELSIF v_stake_type = 'pulse_energy' THEN
    SELECT COALESCE(pulse_energy, 0) INTO v_loser_balance FROM public.profiles WHERE id = p_loser_id;
    v_transfer_amount := FLOOR(v_loser_balance * v_stake_percentage / 100);
    
    UPDATE public.profiles SET pulse_energy = GREATEST(0, pulse_energy - v_transfer_amount) WHERE id = p_loser_id;
    UPDATE public.profiles SET pulse_energy = COALESCE(pulse_energy, 0) + v_transfer_amount WHERE id = p_winner_id;
  END IF;

  UPDATE public.battles SET winner_id = p_winner_id, status = 'resolved', stake_amount = v_transfer_amount WHERE id = p_battle_id;

  RETURN jsonb_build_object('success', true, 'transfer_amount', v_transfer_amount);
END;
$$;


ALTER FUNCTION "public"."battle_resolve_stakes"("p_battle_id" "uuid", "p_winner_id" "uuid", "p_loser_id" "uuid") OWNER TO "postgres";


