CREATE OR REPLACE FUNCTION "public"."buy_lottery_progress"("p_ticket_count" integer, "p_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_cost INT;
  v_current_m1u INT;
  v_progress RECORD;
  v_progress_gain INT;
  v_milestone_reached BOOLEAN := false;
  v_milestone_level INT;
  v_reward_value INT := 0;
  
  -- Deterministic progress thresholds
  c_cost_per_ticket CONSTANT INT := 5; -- M1U cost per ticket
  c_progress_per_ticket CONSTANT INT := 10; -- Progress points per ticket
  c_milestone_threshold CONSTANT INT := 100; -- Points per milestone
  c_milestone_bonus CONSTANT INT := 20; -- M1U bonus per milestone
BEGIN
  -- 1. VERIFY AUTHENTICATION
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'User not authenticated');
  END IF;

  -- 2. VALIDATE INPUT
  IF p_ticket_count < 1 OR p_ticket_count > 10 THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Numero biglietti non valido (1-10)');
  END IF;

  -- 3. CALCULATE COST AND CHECK BALANCE
  v_cost := p_ticket_count * c_cost_per_ticket;
  
  SELECT COALESCE(m1_units, 0) INTO v_current_m1u
  FROM public.profiles WHERE id = v_user_id;
  
  IF v_current_m1u < v_cost THEN
    RETURN jsonb_build_object(
      'status', 'insufficient_funds',
      'message', 'M1U insufficienti',
      'required', v_cost,
      'available', v_current_m1u
    );
  END IF;

  -- 4. DEDUCT M1U
  UPDATE public.profiles
  SET m1_units = m1_units - v_cost
  WHERE id = v_user_id;

  -- 5. CALCULATE DETERMINISTIC PROGRESS
  v_progress_gain := p_ticket_count * c_progress_per_ticket;

  -- 6. GET OR CREATE USER PROGRESS METER
  SELECT * INTO v_progress
  FROM public.user_progress_meters
  WHERE user_id = v_user_id AND meter_type = 'lottery';
  
  IF v_progress IS NULL THEN
    v_milestone_level := 0;
  ELSE
    v_milestone_level := v_progress.milestone_level;
  END IF;

  -- 7. CHECK FOR MILESTONE (deterministic threshold)
  IF v_progress IS NOT NULL THEN
    IF (v_progress.progress_points + v_progress_gain) >= ((v_milestone_level + 1) * c_milestone_threshold) THEN
      v_milestone_reached := true;
      v_milestone_level := v_milestone_level + 1;
      v_reward_value := c_milestone_bonus * v_milestone_level;
    END IF;
  ELSE
    -- First purchase might reach first milestone
    IF v_progress_gain >= c_milestone_threshold THEN
      v_milestone_reached := true;
      v_milestone_level := 1;
      v_reward_value := c_milestone_bonus;
    END IF;
  END IF;

  -- 8. UPSERT PROGRESS METER
  INSERT INTO public.user_progress_meters (
    user_id, meter_type, progress_points, milestone_level,
    last_interaction_date, total_interactions, updated_at
  ) VALUES (
    v_user_id, 'lottery',
    v_progress_gain,
    v_milestone_level,
    CURRENT_DATE,
    p_ticket_count,
    now()
  )
  ON CONFLICT (user_id, meter_type)
  DO UPDATE SET
    progress_points = user_progress_meters.progress_points + v_progress_gain,
    milestone_level = v_milestone_level,
    last_interaction_date = CURRENT_DATE,
    total_interactions = user_progress_meters.total_interactions + p_ticket_count,
    updated_at = now();

  -- 9. AWARD MILESTONE BONUS IF REACHED
  IF v_milestone_reached AND v_reward_value > 0 THEN
    UPDATE public.profiles
    SET m1_units = m1_units + v_reward_value
    WHERE id = v_user_id;
    
    -- Log award
    INSERT INTO public.prize_awards (
      award_type, prize_id, user_id, source, evidence, status
    ) VALUES (
      'progress_milestone',
      'lottery_milestone_' || v_milestone_level,
      v_user_id,
      'lottery_progress',
      jsonb_build_object(
        'ticket_count', p_ticket_count,
        'milestone_level', v_milestone_level,
        'reward_value', v_reward_value,
        'total_progress', COALESCE(v_progress.progress_points, 0) + v_progress_gain
      ),
      'confirmed'
    );
  END IF;

  -- 10. RETURN PROGRESS RESULT (NO WIN/LOSE LANGUAGE)
  RETURN jsonb_build_object(
    'status', 'success',
    'tickets_purchased', p_ticket_count,
    'cost', v_cost,
    'progress_gain', v_progress_gain,
    'total_progress', COALESCE(v_progress.progress_points, 0) + v_progress_gain,
    'milestone_reached', v_milestone_reached,
    'milestone_level', v_milestone_level,
    'milestone_reward', CASE WHEN v_milestone_reached THEN v_reward_value ELSE 0 END,
    'message', CASE
      WHEN v_milestone_reached THEN 'Milestone ' || v_milestone_level || ' raggiunta! +' || v_reward_value || ' M1U'
      ELSE 'Progressione attivata! +' || v_progress_gain || ' punti'
    END
  );
END;
$$;


ALTER FUNCTION "public"."buy_lottery_progress"("p_ticket_count" integer, "p_mission_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."buy_lottery_progress"("p_ticket_count" integer, "p_mission_id" "uuid") IS 'STORE COMPLIANT: Lottery tickets as progress points. No random drawing.';



CREATE OR REPLACE FUNCTION "public"."buy_lottery_tickets"("p_cycle_id" "uuid", "p_quantity" integer, "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'app_web'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_cycle RECORD;
  v_current_m1u NUMERIC;
  v_user_tickets_count INT;
  v_total_cost INT;
  v_purchase_id UUID;
  v_existing_purchase UUID;
  v_ticket_ids UUID[] := ARRAY[]::UUID[];
  v_ticket_codes TEXT[] := ARRAY[]::TEXT[];
  v_i INT;
  v_new_ticket_id UUID;
  v_new_ticket_code TEXT;
  v_is_first_purchase BOOLEAN;
BEGIN
  -- 1. AUTENTICAZIONE
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'NOT_AUTHENTICATED', 'message', 'Non autenticato');
  END IF;
  
  -- 2. VALIDAZIONE
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_quantity > 100 THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'INVALID_QUANTITY', 'message', 'Quantità non valida (1-100)');
  END IF;
  
  -- 3. IDEMPOTENZA
  IF p_request_id IS NOT NULL THEN
    SELECT id INTO v_existing_purchase FROM public.lottery_purchases WHERE request_id = p_request_id;
    IF v_existing_purchase IS NOT NULL THEN
      RETURN jsonb_build_object('status', 'already_purchased', 'purchase_id', v_existing_purchase);
    END IF;
  END IF;
  
  -- 4. VERIFICA CICLO
  SELECT * INTO v_cycle FROM public.mission_cycles WHERE id = p_cycle_id FOR UPDATE;
  IF v_cycle IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'CYCLE_NOT_FOUND', 'message', 'Ciclo non trovato');
  END IF;
  IF v_cycle.status != 'active' THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'CYCLE_NOT_ACTIVE', 'message', 'Ciclo non attivo');
  END IF;
  
  -- 5. VERIFICA CAP
  SELECT COUNT(*) INTO v_user_tickets_count
  FROM public.lottery_tickets WHERE cycle_id = p_cycle_id AND user_id = v_user_id AND status = 'active';
  
  IF v_user_tickets_count + p_quantity > v_cycle.max_tickets_per_user THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'MAX_TICKETS_EXCEEDED', 
      'message', format('Max %s biglietti', v_cycle.max_tickets_per_user));
  END IF;
  
  -- 6. VERIFICA SALDO
  v_total_cost := p_quantity * v_cycle.ticket_price_m1u;
  SELECT m1_units INTO v_current_m1u FROM public.profiles WHERE id = v_user_id;
  IF v_current_m1u IS NULL OR v_current_m1u < v_total_cost THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'INSUFFICIENT_BALANCE', 
      'message', format('Servono %s M1U', v_total_cost));
  END IF;
  
  v_is_first_purchase := (v_user_tickets_count = 0);
  
  -- 7. ADDEBITA
  UPDATE public.profiles SET m1_units = m1_units - v_total_cost, updated_at = now()
  WHERE id = v_user_id AND m1_units >= v_total_cost;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'error', 'code', 'DEBIT_FAILED', 'message', 'Errore addebito');
  END IF;
  
  -- 8. CREA PURCHASE
  INSERT INTO public.lottery_purchases (cycle_id, user_id, tickets_count, unit_price_m1u, request_id, source, status)
  VALUES (p_cycle_id, v_user_id, p_quantity, v_cycle.ticket_price_m1u, p_request_id, p_source, 'completed')
  RETURNING id INTO v_purchase_id;
  
  -- 9. CREA TICKETS CON CODICE
  FOR v_i IN 1..p_quantity LOOP
    v_new_ticket_code := public.generate_ticket_code();
    
    INSERT INTO public.lottery_tickets (cycle_id, user_id, purchase_id, ticket_code, status)
    VALUES (p_cycle_id, v_user_id, v_purchase_id, v_new_ticket_code, 'active')
    RETURNING id INTO v_new_ticket_id;
    
    v_ticket_ids := array_append(v_ticket_ids, v_new_ticket_id);
    v_ticket_codes := array_append(v_ticket_codes, v_new_ticket_code);
  END LOOP;
  
  -- 10. AGGIORNA CONTATORI
  UPDATE public.mission_cycles SET 
    total_tickets = total_tickets + p_quantity,
    total_participants = CASE WHEN v_is_first_purchase THEN total_participants + 1 ELSE total_participants END,
    updated_at = now()
  WHERE id = p_cycle_id;
  
  -- SUCCESSO con codici biglietto!
  RETURN jsonb_build_object(
    'status', 'success',
    'message', format('🎫 %s biglietti acquistati!', p_quantity),
    'purchase_id', v_purchase_id,
    'tickets_count', p_quantity,
    'total_cost', v_total_cost,
    'ticket_ids', v_ticket_ids,
    'ticket_codes', v_ticket_codes,
    'new_balance', v_current_m1u - v_total_cost
  );
END;
$$;


ALTER FUNCTION "public"."buy_lottery_tickets"("p_cycle_id" "uuid", "p_quantity" integer, "p_request_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buzz_map_create_area"("p_user_id" "uuid", "p_cost_m1u" integer, "p_latitude" double precision, "p_longitude" double precision, "p_radius_km" double precision, "p_level" integer, "p_week" integer, "p_price_eur" double precision, "p_current_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_balance INT;
  v_new_balance INT;
  v_row_count INT;
  v_area_id UUID;
BEGIN
  -- ATOMIC TRANSACTION: Both payment AND area creation succeed or both fail
  
  -- STEP 1: ATOMIC UPDATE - Deduct M1U only if sufficient balance exists
  UPDATE public.profiles
  SET 
    m1_units = m1_units - p_cost_m1u,
    updated_at = now()
  WHERE 
    id = p_user_id
    AND m1_units >= p_cost_m1u  -- CRITICAL: only update if sufficient funds
  RETURNING 
    m1_units + p_cost_m1u,  -- Reconstruct old balance
    m1_units                -- New balance after deduction
  INTO v_old_balance, v_new_balance;

  -- Check if UPDATE affected any rows
  GET DIAGNOSTICS v_row_count = ROW_COUNT;

  IF v_row_count = 0 THEN
    -- No rows updated - either insufficient funds or profile doesn't exist
    SELECT m1_units INTO v_old_balance
    FROM public.profiles
    WHERE id = p_user_id;

    IF v_old_balance IS NULL THEN
      -- Profile doesn't exist
      RETURN jsonb_build_object(
        'success', false,
        'error', 'profile_not_found',
        'errorMessage', 'Profilo utente non trovato'
      );
    ELSE
      -- INSUFFICIENT FUNDS - OPTION B behavior
      RETURN jsonb_build_object(
        'success', false,
        'error', 'INSUFFICIENT_FUNDS',
        'errorMessage', 'Saldo M1U insufficiente',
        'current_balance', v_old_balance,
        'required', p_cost_m1u
      );
    END IF;
  END IF;

  -- STEP 2: INSERT map area (SAME TRANSACTION)
  -- If this fails, the entire transaction rolls back (including M1U deduction)
  INSERT INTO public.user_map_areas (
    user_id,
    lat,
    lng,
    center_lat,
    center_lng,
    radius_km,
    source,
    level,
    price_eur,
    week
  ) VALUES (
    p_user_id,
    p_latitude,
    p_longitude,
    p_latitude,
    p_longitude,
    p_radius_km,
    'buzz_map',
    p_level,
    p_price_eur,
    p_week
  )
  RETURNING id INTO v_area_id;

  -- STEP 3: Return success with all details
  RETURN jsonb_build_object(
    'success', true,
    'area_id', v_area_id,
    'spent', p_cost_m1u,
    'old_balance', v_old_balance,
    'new_balance', v_new_balance,
    'level', p_level,
    'radius_km', p_radius_km,
    'coordinates', jsonb_build_object('lat', p_latitude, 'lng', p_longitude),
    'week', p_week,
    'message', 'BUZZ MAP created successfully'
  );

EXCEPTION
  WHEN OTHERS THEN
    -- ANY error (constraint violation, permission denied, etc.) → ROLLBACK EVERYTHING
    RAISE WARNING 'BUZZ MAP transaction failed: % %', SQLERRM, SQLSTATE;
    RETURN jsonb_build_object(
      'success', false,
      'error', 'transaction_failed',
      'errorMessage', 'Errore durante la creazione dell''area: ' || SQLERRM,
      'sqlstate', SQLSTATE
    );
END;
$$;


ALTER FUNCTION "public"."buzz_map_create_area"("p_user_id" "uuid", "p_cost_m1u" integer, "p_latitude" double precision, "p_longitude" double precision, "p_radius_km" double precision, "p_level" integer, "p_week" integer, "p_price_eur" double precision, "p_current_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."buzz_map_create_area"("p_user_id" "uuid", "p_cost_m1u" integer, "p_latitude" double precision, "p_longitude" double precision, "p_radius_km" double precision, "p_level" integer, "p_week" integer, "p_price_eur" double precision, "p_current_count" integer) IS 'Atomically deducts M1U and creates BUZZ MAP area in single transaction. Implements OPTION B with guaranteed rollback on any failure.';



CREATE OR REPLACE FUNCTION "public"."buzz_map_spend_m1u"("p_user_id" "uuid", "p_cost_m1u" integer, "p_latitude" double precision, "p_longitude" double precision, "p_radius_km" double precision) RETURNS TABLE("success" boolean, "spent" integer, "new_balance" integer, "error" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_balance INT;
BEGIN
  -- Verifica saldo M1U
  SELECT m1_units INTO v_balance FROM public.profiles WHERE id = p_user_id;
  
  IF v_balance IS NULL THEN
    RETURN QUERY SELECT FALSE, 0, 0, 'user_not_found'::TEXT;
    RETURN;
  END IF;
  
  IF v_balance < p_cost_m1u THEN
    RETURN QUERY SELECT FALSE, 0, v_balance, 'insufficient_balance'::TEXT;
    RETURN;
  END IF;
  
  -- Sottrai M1U
  UPDATE public.profiles 
  SET m1_units = m1_units - p_cost_m1u,
      updated_at = NOW()
  WHERE id = p_user_id
  RETURNING m1_units INTO v_balance;
  
  -- Log transazione M1U
  INSERT INTO public.m1_transactions (user_id, amount, type, description)
  VALUES (p_user_id, -p_cost_m1u, 'buzz_map', 'BUZZ MAP area generation')
  ON CONFLICT DO NOTHING;
  
  -- Ritorna successo
  RETURN QUERY SELECT TRUE, p_cost_m1u, v_balance, NULL::TEXT;
END;
$$;


ALTER FUNCTION "public"."buzz_map_spend_m1u"("p_user_id" "uuid", "p_cost_m1u" integer, "p_latitude" double precision, "p_longitude" double precision, "p_radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buzz_spend_m1u"("p_cost_m1u" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_current_balance integer;
  v_new_balance integer;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Lock row per evitare race conditions
  SELECT balance INTO v_current_balance
  FROM public.user_m1_units
  WHERE user_id = v_user_id
  FOR UPDATE;
  
  -- Crea wallet se non esiste
  IF v_current_balance IS NULL THEN
    INSERT INTO public.user_m1_units (user_id, balance, total_earned, total_spent)
    VALUES (v_user_id, 0, 0, 0);
    v_current_balance := 0;
  END IF;
  
  -- Verifica saldo sufficiente
  IF v_current_balance < p_cost_m1u THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'insufficient_m1u',
      'current_balance', v_current_balance,
      'required', p_cost_m1u
    );
  END IF;
  
  -- Scala M1U
  v_new_balance := v_current_balance - p_cost_m1u;
  
  UPDATE public.user_m1_units
  SET 
    balance = v_new_balance,
    total_spent = total_spent + p_cost_m1u,
    updated_at = now()
  WHERE user_id = v_user_id;
  
  -- Log transazione
  INSERT INTO public.m1u_transactions (user_id, amount, type, source)
  VALUES (v_user_id, p_cost_m1u, 'debit', 'buzz');
  
  RETURN jsonb_build_object(
    'success', true,
    'spent', p_cost_m1u,
    'new_balance', v_new_balance
  );
END;
$$;


