CREATE OR REPLACE FUNCTION "public"."calculate_access_start_date"("plan_name" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  CASE UPPER(plan_name)
    WHEN 'SILVER' THEN
      RETURN '2025-08-19 00:00:00+00'::TIMESTAMP WITH TIME ZONE;
    WHEN 'GOLD' THEN
      RETURN '2025-08-18 07:00:00+00'::TIMESTAMP WITH TIME ZONE;
    WHEN 'BLACK' THEN
      RETURN '2025-08-18 00:00:00+00'::TIMESTAMP WITH TIME ZONE;
    WHEN 'TITANIUM' THEN
      RETURN '2025-08-16 00:00:00+00'::TIMESTAMP WITH TIME ZONE;
    ELSE
      -- Piano base o non riconosciuto - accesso solo al momento del lancio
      RETURN '2025-08-19 12:00:00+00'::TIMESTAMP WITH TIME ZONE;
  END CASE;
END;
$$;


ALTER FUNCTION "public"."calculate_access_start_date"("plan_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_access_start_time"("p_plan" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  early_access_hours INTEGER := 0;
BEGIN
  CASE p_plan
    WHEN 'silver' THEN early_access_hours := 2;
    WHEN 'gold' THEN early_access_hours := 24;
    WHEN 'black' THEN early_access_hours := 48;
    WHEN 'titanium' THEN early_access_hours := 72;
    ELSE early_access_hours := 0;
  END CASE;
  
  -- Per ora restituisce subito l'accesso
  -- In futuro si può modificare per calcolare in base alle missioni
  RETURN now();
END;
$$;


