CREATE OR REPLACE FUNCTION "public"."calculate_buzz_price"("daily_count" integer) RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF daily_count BETWEEN 0 AND 10 THEN
    RETURN 1.99;
  ELSIF daily_count BETWEEN 11 AND 20 THEN
    RETURN 3.99;
  ELSIF daily_count BETWEEN 21 AND 30 THEN
    RETURN 5.99;
  ELSIF daily_count BETWEEN 31 AND 40 THEN
    RETURN 7.99;
  ELSIF daily_count BETWEEN 41 AND 50 THEN
    RETURN 9.99;
  ELSE
    RETURN 0; -- Valore che indica "bloccato"
  END IF;
END;
$$;


ALTER FUNCTION "public"."calculate_buzz_price"("daily_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_day_clarity"("p_day_index" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_min_clarity NUMERIC;
  v_max_clarity NUMERIC;
  v_day_in_band INTEGER;
  v_band_size INTEGER;
BEGIN
  -- Day 1-7: 0.10-0.25 (molto vago)
  IF p_day_index <= 7 THEN
    v_min_clarity := 0.10;
    v_max_clarity := 0.25;
    v_day_in_band := p_day_index;
    v_band_size := 7;
  -- Day 8-15: 0.25-0.45 (comprensibile)
  ELSIF p_day_index <= 15 THEN
    v_min_clarity := 0.25;
    v_max_clarity := 0.45;
    v_day_in_band := p_day_index - 7;
    v_band_size := 8;
  -- Day 16-23: 0.45-0.70 (chiaro)
  ELSIF p_day_index <= 23 THEN
    v_min_clarity := 0.45;
    v_max_clarity := 0.70;
    v_day_in_band := p_day_index - 15;
    v_band_size := 8;
  -- Day 24-30: 0.70-0.85 (molto chiaro, mai certo)
  ELSE
    v_min_clarity := 0.70;
    v_max_clarity := 0.85;
    v_day_in_band := p_day_index - 23;
    v_band_size := 7;
  END IF;
  
  -- Linear interpolation within band
  RETURN v_min_clarity + (v_max_clarity - v_min_clarity) * (v_day_in_band::NUMERIC / v_band_size);
END;
$$;


ALTER FUNCTION "public"."calculate_day_clarity"("p_day_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_direction"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  dlng DOUBLE PRECISION;
  y DOUBLE PRECISION;
  x DOUBLE PRECISION;
  bearing DOUBLE PRECISION;
  directions TEXT[] := ARRAY['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
BEGIN
  dlng := radians(lng2 - lng1);
  y := sin(dlng) * cos(radians(lat2));
  x := cos(radians(lat1)) * sin(radians(lat2)) - sin(radians(lat1)) * cos(radians(lat2)) * cos(dlng);
  bearing := degrees(atan2(y, x));
  bearing := bearing + 360;
  bearing := bearing - 360 * floor(bearing / 360); -- Fix: use floor division instead of modulo
  RETURN directions[floor((bearing + 22.5) / 45)::int % 8 + 1];
END;
$$;


ALTER FUNCTION "public"."calculate_direction"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_distance_meters"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS double precision
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r DOUBLE PRECISION := 6371000; -- Earth radius in meters
  dlat DOUBLE PRECISION;
  dlng DOUBLE PRECISION;
  a DOUBLE PRECISION;
  c DOUBLE PRECISION;
BEGIN
  dlat := radians(lat2 - lat1);
  dlng := radians(lng2 - lng1);
  a := sin(dlat/2) * sin(dlat/2) + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2) * sin(dlng/2);
  c := 2 * atan2(sqrt(a), sqrt(1-a));
  RETURN r * c;
END;
$$;


ALTER FUNCTION "public"."calculate_distance_meters"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_domination_status"("p_win_progress" integer, "p_threshold" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  IF p_win_progress >= p_threshold THEN RETURN 'conquered';
  ELSIF p_win_progress >= CEIL(p_threshold * 0.8) THEN RETURN 'contested';
  ELSE RETURN 'neutral';
  END IF;
END;
$$;


