CREATE OR REPLACE FUNCTION "public"."can_use_intelligence_tool"("p_user_id" "uuid", "p_mission_id" "uuid", "p_tool_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  mission_start_date DATE;
  current_week INTEGER;
  tool_week_requirement INTEGER;
  daily_usage_count INTEGER;
BEGIN
  -- Get mission start date
  SELECT start_date::DATE INTO mission_start_date
  FROM public.monthly_missions
  WHERE id = p_mission_id AND status = 'active';
  
  -- If no active mission, deny access
  IF mission_start_date IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Calculate current week (starting from 1)
  current_week := GREATEST(1, CEIL((CURRENT_DATE - mission_start_date) / 7.0));
  
  -- Set week requirements for each tool
  CASE p_tool_name
    WHEN 'radar' THEN tool_week_requirement := 3;
    WHEN 'interceptor' THEN tool_week_requirement := 4;
    WHEN 'precision' THEN tool_week_requirement := 5;
    ELSE tool_week_requirement := 999; -- Invalid tool
  END CASE;
  
  -- Check if current week meets requirement
  IF current_week < tool_week_requirement THEN
    RETURN FALSE;
  END IF;
  
  -- Check daily usage limit (1 per day per tool)
  SELECT COUNT(*) INTO daily_usage_count
  FROM public.intelligence_tool_usage
  WHERE user_id = p_user_id
    AND mission_id = p_mission_id
    AND tool_name = p_tool_name
    AND used_on = CURRENT_DATE;
  
  -- Allow if not used today
  RETURN daily_usage_count = 0;
END;
$$;


ALTER FUNCTION "public"."can_use_intelligence_tool"("p_user_id" "uuid", "p_mission_id" "uuid", "p_tool_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_access_mission"("user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  user_profile RECORD;
  current_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
  -- Ottieni il profilo dell'utente
  SELECT * INTO user_profile
  FROM public.profiles
  WHERE id = user_id;
  
  -- Se l'utente non esiste, nega l'accesso
  IF user_profile IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Se l'accesso non è abilitato, nega
  IF NOT user_profile.access_enabled THEN
    RETURN FALSE;
  END IF;
  
  -- Se non c'è una data di inizio accesso, nega
  IF user_profile.access_start_date IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Verifica se è arrivato il momento dell'accesso
  RETURN current_time >= user_profile.access_start_date;
END;
$$;


ALTER FUNCTION "public"."can_user_access_mission"("user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_buzz_mappa"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  week_start DATE;
  current_week INTEGER;
  max_allowed INTEGER;
  user_record RECORD;
BEGIN
  -- Get current week info
  week_start := public.get_week_start_date();
  current_week := public.get_current_game_week();
  max_allowed := public.get_max_buzz_for_week(current_week);
  
  -- Get or create user's weekly record
  SELECT * INTO user_record
  FROM public.user_weekly_buzz_limits
  WHERE user_id = p_user_id AND week_start_date = week_start;
  
  -- If no record exists, user can buzz (first time this week)
  IF user_record IS NULL THEN
    RETURN TRUE;
  END IF;
  
  -- Check if user has remaining buzzes
  RETURN user_record.buzz_map_count < max_allowed;
END;
$$;


ALTER FUNCTION "public"."can_user_buzz_mappa"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_use_buzz"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_week INTEGER;
  current_year INTEGER;
  user_allowance RECORD;
BEGIN
  -- Get current week and year
  SELECT week_num, year_num INTO current_week, current_year 
  FROM public.get_current_week_and_year();
  
  -- Get user's weekly allowance
  SELECT * INTO user_allowance
  FROM public.weekly_buzz_allowances
  WHERE user_id = p_user_id 
    AND week_number = current_week 
    AND year = current_year;
  
  -- If no allowance record exists, user can't use buzz
  IF user_allowance IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Check if user has remaining buzz uses
  RETURN user_allowance.used_buzz_count < user_allowance.max_buzz_count;
END;
$$;


ALTER FUNCTION "public"."can_user_use_buzz"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_lottery_cycle"("p_cycle_id" "uuid", "p_reason" "text" DEFAULT 'Admin cancellation'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
  v_cycle RECORD;
  v_refund_count INT := 0;
  v_total_refunded INT := 0;
  v_purchase RECORD;
BEGIN
  -- Verifica admin
  v_user_id := auth.uid();
  
  SELECT role INTO v_user_role
  FROM public.profiles
  WHERE id = v_user_id;
  
  IF v_user_role NOT IN ('admin', 'owner') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'UNAUTHORIZED',
      'message', 'Solo gli admin possono annullare cicli'
    );
  END IF;
  
  -- Recupera ciclo
  SELECT * INTO v_cycle
  FROM public.mission_cycles
  WHERE id = p_cycle_id
  FOR UPDATE;
  
  IF v_cycle IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'CYCLE_NOT_FOUND',
      'message', 'Ciclo non trovato'
    );
  END IF;
  
  IF v_cycle.status = 'completed' THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'ALREADY_COMPLETED',
      'message', 'Il ciclo è già completato, non può essere annullato'
    );
  END IF;
  
  IF v_cycle.status = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'ALREADY_CANCELLED',
      'message', 'Il ciclo è già stato annullato'
    );
  END IF;
  
  -- Rimborsa tutti gli acquisti
  FOR v_purchase IN (
    SELECT * FROM public.lottery_purchases
    WHERE cycle_id = p_cycle_id AND status = 'completed'
  ) LOOP
    -- Accredita M1U
    UPDATE public.profiles
    SET m1_units = m1_units + v_purchase.total_m1u,
        updated_at = now()
    WHERE id = v_purchase.user_id;
    
    -- Marca come refunded
    UPDATE public.lottery_purchases
    SET status = 'refunded', refunded_at = now()
    WHERE id = v_purchase.id;
    
    -- Voida i ticket
    UPDATE public.lottery_tickets
    SET status = 'void'
    WHERE purchase_id = v_purchase.id;
    
    v_refund_count := v_refund_count + 1;
    v_total_refunded := v_total_refunded + v_purchase.total_m1u;
    
    -- Audit per singolo refund
    INSERT INTO public.lottery_audit_logs (
      cycle_id, user_id, purchase_id, event_type, event_details
    )
    VALUES (
      p_cycle_id, v_purchase.user_id, v_purchase.id, 'ticket_refunded',
      jsonb_build_object('amount', v_purchase.total_m1u, 'reason', p_reason)
    );
  END LOOP;
  
  -- Aggiorna ciclo come cancelled
  UPDATE public.mission_cycles
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_cycle_id;
  
  -- Audit finale
  INSERT INTO public.lottery_audit_logs (
    cycle_id, user_id, event_type, event_details
  )
  VALUES (
    p_cycle_id, v_user_id, 'cycle_cancelled',
    jsonb_build_object(
      'reason', p_reason,
      'refunds_count', v_refund_count,
      'total_refunded', v_total_refunded
    )
  );
  
  RETURN jsonb_build_object(
    'status', 'success',
    'cycle_id', p_cycle_id,
    'refunds_count', v_refund_count,
    'total_refunded', v_total_refunded,
    'message', format('Ciclo annullato. Rimborsati %s acquisti per un totale di %s M1U.', v_refund_count, v_total_refunded)
  );
END;
$$;


ALTER FUNCTION "public"."cancel_lottery_cycle"("p_cycle_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_lottery_cycle"("p_cycle_id" "uuid", "p_reason" "text") IS 'M1SSION™ Lottery - Annulla ciclo con refund completo (solo admin).';



CREATE OR REPLACE FUNCTION "public"."check_abuse_limit"("p_event_type" "text", "p_user_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  event_count INTEGER;
BEGIN
  -- Conta gli eventi dello stesso tipo negli ultimi 30 secondi
  SELECT COUNT(*) INTO event_count
  FROM public.abuse_logs
  WHERE user_id = p_user_id
    AND event_type = p_event_type
    AND timestamp >= NOW() - INTERVAL '30 seconds';
  
  -- Restituisce true se superato il limite di 5 eventi
  RETURN event_count >= 5;
END;
$$;


ALTER FUNCTION "public"."check_abuse_limit"("p_event_type" "text", "p_user_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_aion_access"("p_question_preview" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_plan TEXT;
  v_m1u_balance INTEGER;
  v_free_weekly_slots INTEGER;
  v_cost_after_free INTEGER;
  v_daily_cap INTEGER;
  v_free_uses_this_week INTEGER;
  v_daily_uses_today INTEGER;
  v_week_start DATE;
  v_current_week_start DATE;
  v_today DATE;
  v_can_use BOOLEAN := false;
  v_use_free_slot BOOLEAN := false;
  v_m1u_to_spend INTEGER := 0;
  v_error_code TEXT := NULL;
  v_remaining_free INTEGER := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    -- 🔍 LOG DENIED: not authenticated
    INSERT INTO public.aion_usage_logs (user_id, plan, authorized, error_code, question_preview)
    VALUES (NULL, 'UNKNOWN', false, 'NOT_AUTHENTICATED', LEFT(p_question_preview, 100));
    RETURN jsonb_build_object('authorized', false, 'error_code', 'NOT_AUTHENTICATED');
  END IF;

  v_today := CURRENT_DATE;
  v_current_week_start := v_today - EXTRACT(DOW FROM v_today)::INTEGER + 1;
  IF EXTRACT(DOW FROM v_today) = 0 THEN
    v_current_week_start := v_today - 6;
  END IF;

  SELECT COALESCE(UPPER(subscription_plan), 'FREE'), COALESCE(m1_units, 0)
  INTO v_plan, v_m1u_balance
  FROM public.profiles WHERE id = v_user_id;

  IF v_plan IS NULL OR v_plan NOT IN ('FREE', 'SILVER', 'GOLD', 'BLACK', 'TITANIUM') THEN
    v_plan := 'FREE';
  END IF;

  SELECT free_weekly_slots, cost_after_free, daily_cap
  INTO v_free_weekly_slots, v_cost_after_free, v_daily_cap
  FROM public.aion_plan_config WHERE plan = v_plan;

  IF v_free_weekly_slots IS NULL THEN
    v_free_weekly_slots := 0;
    v_cost_after_free := 2;
  END IF;

  SELECT free_uses_this_week, week_start_date, daily_uses_today, last_use_date
  INTO v_free_uses_this_week, v_week_start, v_daily_uses_today, v_today
  FROM public.user_aion_state WHERE user_id = v_user_id;

  IF NOT FOUND THEN
    INSERT INTO public.user_aion_state (user_id, free_uses_this_week, week_start_date, daily_uses_today, last_use_date)
    VALUES (v_user_id, 0, v_current_week_start, 0, CURRENT_DATE);
    v_free_uses_this_week := 0;
    v_daily_uses_today := 0;
  ELSE
    IF v_week_start < v_current_week_start THEN
      v_free_uses_this_week := 0;
      UPDATE public.user_aion_state SET free_uses_this_week = 0, week_start_date = v_current_week_start WHERE user_id = v_user_id;
    END IF;
    SELECT last_use_date, daily_uses_today INTO v_today, v_daily_uses_today FROM public.user_aion_state WHERE user_id = v_user_id;
    IF v_today < CURRENT_DATE THEN
      v_daily_uses_today := 0;
      UPDATE public.user_aion_state SET daily_uses_today = 0, last_use_date = CURRENT_DATE WHERE user_id = v_user_id;
    END IF;
  END IF;

  v_remaining_free := GREATEST(0, v_free_weekly_slots - v_free_uses_this_week);

  -- Check TITANIUM daily cap
  IF v_plan = 'TITANIUM' AND v_daily_cap IS NOT NULL AND v_daily_uses_today >= v_daily_cap THEN
    -- 🔍 LOG DENIED: daily cap exceeded
    INSERT INTO public.aion_usage_logs (user_id, plan, authorized, error_code, question_preview)
    VALUES (v_user_id, v_plan, false, 'AION_DAILY_CAP_EXCEEDED', LEFT(p_question_preview, 100));
    RETURN jsonb_build_object('authorized', false, 'error_code', 'AION_DAILY_CAP_EXCEEDED', 'plan', v_plan, 'daily_uses', v_daily_uses_today, 'daily_cap', v_daily_cap);
  END IF;

  IF v_remaining_free > 0 THEN
    v_can_use := true; v_use_free_slot := true; v_m1u_to_spend := 0;
  ELSIF v_m1u_balance >= v_cost_after_free THEN
    v_can_use := true; v_use_free_slot := false; v_m1u_to_spend := v_cost_after_free;
  ELSE
    v_can_use := false; v_error_code := 'INSUFFICIENT_M1U_FOR_AION';
  END IF;

  IF NOT v_can_use THEN
    -- 🔍 LOG DENIED: insufficient M1U
    INSERT INTO public.aion_usage_logs (user_id, plan, authorized, error_code, m1u_spent, question_preview)
    VALUES (v_user_id, v_plan, false, v_error_code, 0, LEFT(p_question_preview, 100));
    RETURN jsonb_build_object('authorized', false, 'error_code', v_error_code, 'plan', v_plan, 'm1u_balance', v_m1u_balance, 'm1u_required', v_cost_after_free, 'free_remaining', v_remaining_free);
  END IF;

  -- AUTHORIZED
  IF v_use_free_slot THEN
    UPDATE public.user_aion_state SET free_uses_this_week = free_uses_this_week + 1, daily_uses_today = daily_uses_today + 1, last_use_date = CURRENT_DATE, updated_at = NOW() WHERE user_id = v_user_id;
  ELSE
    UPDATE public.profiles SET m1_units = m1_units - v_m1u_to_spend, updated_at = NOW() WHERE id = v_user_id;
    UPDATE public.user_aion_state SET daily_uses_today = daily_uses_today + 1, last_use_date = CURRENT_DATE, updated_at = NOW() WHERE user_id = v_user_id;
    INSERT INTO public.user_m1_units_events (user_id, delta, reason, metadata) VALUES (v_user_id, -v_m1u_to_spend, 'AION_CONSULT', jsonb_build_object('plan', v_plan));
  END IF;

  -- 🔍 LOG SUCCESS
  INSERT INTO public.aion_usage_logs (user_id, plan, used_free_slot, m1u_spent, authorized, error_code, question_preview)
  VALUES (v_user_id, v_plan, v_use_free_slot, v_m1u_to_spend, true, NULL, LEFT(p_question_preview, 100));

  SELECT m1_units INTO v_m1u_balance FROM public.profiles WHERE id = v_user_id;
  RETURN jsonb_build_object('authorized', true, 'plan', v_plan, 'used_free_slot', v_use_free_slot, 'm1u_spent', v_m1u_to_spend, 'm1u_balance', v_m1u_balance, 'free_remaining', CASE WHEN v_use_free_slot THEN v_remaining_free - 1 ELSE v_remaining_free END, 'daily_uses', v_daily_uses_today + 1);
END;
$$;


