CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("ip_addr" "inet", "api_endpoint" "text", "max_requests" integer DEFAULT 3, "window_minutes" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    current_count INTEGER;
    window_start_time TIMESTAMP WITH TIME ZONE;
BEGIN
    window_start_time := now() - (window_minutes || ' minutes')::INTERVAL;
    
    -- Clean old entries
    DELETE FROM public.api_rate_limits 
    WHERE window_start < window_start_time;
    
    -- Get current count for this IP and endpoint
    SELECT request_count INTO current_count
    FROM public.api_rate_limits
    WHERE ip_address = ip_addr 
    AND endpoint = api_endpoint
    AND window_start >= window_start_time;
    
    IF current_count IS NULL THEN
        -- First request in this window
        INSERT INTO public.api_rate_limits (ip_address, endpoint, request_count, window_start)
        VALUES (ip_addr, api_endpoint, 1, now());
        RETURN TRUE;
    ELSIF current_count < max_requests THEN
        -- Update count
        UPDATE public.api_rate_limits 
        SET request_count = request_count + 1, last_request = now()
        WHERE ip_address = ip_addr AND endpoint = api_endpoint;
        RETURN TRUE;
    ELSE
        -- Rate limit exceeded
        RETURN FALSE;
    END IF;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("ip_addr" "inet", "api_endpoint" "text", "max_requests" integer, "window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_limit_key" "text", "p_limit_type" "text", "p_endpoint" "text", "p_max_requests" integer DEFAULT 5, "p_window_seconds" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_window_start TIMESTAMPTZ;
    v_current_count INTEGER;
    v_remaining INTEGER;
    v_allowed BOOLEAN;
BEGIN
    -- Calculate current window start
    v_window_start := date_trunc('second', now()) - 
        (EXTRACT(EPOCH FROM now())::INTEGER % p_window_seconds) * INTERVAL '1 second';
    
    -- Try to insert or update rate limit record
    INSERT INTO iap_rate_limits (limit_key, limit_type, endpoint, request_count, window_start, window_duration_seconds, last_request_at)
    VALUES (p_limit_key, p_limit_type, p_endpoint, 1, v_window_start, p_window_seconds, now())
    ON CONFLICT (limit_key, limit_type, endpoint, window_start) DO UPDATE SET
        request_count = iap_rate_limits.request_count + 1,
        last_request_at = now()
    RETURNING request_count INTO v_current_count;
    
    v_remaining := GREATEST(0, p_max_requests - v_current_count);
    v_allowed := v_current_count <= p_max_requests;
    
    RETURN jsonb_build_object(
        'allowed', v_allowed,
        'current_count', v_current_count,
        'max_requests', p_max_requests,
        'remaining', v_remaining,
        'window_seconds', p_window_seconds,
        'reset_at', v_window_start + (p_window_seconds * INTERVAL '1 second')
    );
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_limit_key" "text", "p_limit_type" "text", "p_endpoint" "text", "p_max_requests" integer, "p_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_rate_limit"("p_limit_key" "text", "p_limit_type" "text", "p_endpoint" "text", "p_max_requests" integer, "p_window_seconds" integer) IS 'Check and update rate limit for a request';



CREATE OR REPLACE FUNCTION "public"."check_replay"("p_user_id" "uuid", "p_transaction_id" "text", "p_purchase_token" "text", "p_endpoint" "text", "p_ttl_minutes" integer DEFAULT 10) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_token_hash TEXT;
    v_is_replay BOOLEAN;
BEGIN
    -- Create unique token hash
    v_token_hash := encode(
        sha256(
            (COALESCE(p_user_id::TEXT, '') || '|' || 
             COALESCE(p_transaction_id, '') || '|' || 
             COALESCE(p_purchase_token, '') || '|' || 
             p_endpoint)::BYTEA
        ), 
        'hex'
    );
    
    -- Try to insert token
    INSERT INTO iap_request_tokens (token_hash, user_id, transaction_id, purchase_token, endpoint, expires_at)
    VALUES (v_token_hash, p_user_id, p_transaction_id, p_purchase_token, p_endpoint, now() + (p_ttl_minutes * INTERVAL '1 minute'))
    ON CONFLICT (token_hash) DO NOTHING;
    
    -- If insert succeeded (affected rows = 1), it's a new request
    -- If insert was skipped (conflict), it's a replay
    GET DIAGNOSTICS v_is_replay = ROW_COUNT;
    
    RETURN v_is_replay = 0;  -- True if replay (no rows inserted)
END;
$$;


ALTER FUNCTION "public"."check_replay"("p_user_id" "uuid", "p_transaction_id" "text", "p_purchase_token" "text", "p_endpoint" "text", "p_ttl_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_replay"("p_user_id" "uuid", "p_transaction_id" "text", "p_purchase_token" "text", "p_endpoint" "text", "p_ttl_minutes" integer) IS 'Check if request is a replay attack';



CREATE OR REPLACE FUNCTION "public"."check_security_rate_limit"("p_action" "text", "p_limit" integer DEFAULT 5, "p_window_minutes" integer DEFAULT 15) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_count integer;
  window_start timestamptz;
BEGIN
  window_start := now() - (p_window_minutes || ' minutes')::interval;
  
  SELECT COUNT(*) INTO current_count
  FROM public.security_audit_log
  WHERE user_id = auth.uid()
    AND event_type = p_action
    AND created_at >= window_start;
    
  RETURN current_count < p_limit;
END;
$$;


