CREATE OR REPLACE FUNCTION "public"."claim_cashback"("p_user_id" "uuid") RETURNS TABLE("credited_m1u" integer, "new_balance" integer, "next_claim_available" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_accumulated INTEGER;
  v_last_claim TIMESTAMPTZ;
  v_new_balance INTEGER;
BEGIN
  -- Carica wallet
  SELECT accumulated_m1u, last_claim_at 
  INTO v_accumulated, v_last_claim
  FROM user_cashback_wallet
  WHERE user_id = p_user_id;

  -- Verifica esistenza wallet
  IF v_accumulated IS NULL THEN
    RAISE EXCEPTION 'No cashback wallet found';
  END IF;

  -- Verifica se c'è qualcosa da riscattare
  IF v_accumulated <= 0 THEN
    RAISE EXCEPTION 'Nothing to claim';
  END IF;

  -- Verifica cooldown 7 giorni
  IF v_last_claim IS NOT NULL AND v_last_claim > NOW() - INTERVAL '7 days' THEN
    RAISE EXCEPTION 'Claim available in % days', 
      CEIL(EXTRACT(EPOCH FROM (v_last_claim + INTERVAL '7 days' - NOW())) / 86400);
  END IF;

  -- Trasferisci M1U al profilo
  UPDATE profiles
  SET m1_units = COALESCE(m1_units, 0) + v_accumulated
  WHERE id = p_user_id
  RETURNING m1_units INTO v_new_balance;

  -- Reset wallet e aggiorna last_claim
  UPDATE user_cashback_wallet
  SET 
    accumulated_m1u = 0,
    last_claim_at = NOW(),
    updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Return result
  RETURN QUERY SELECT 
    v_accumulated AS credited_m1u,
    v_new_balance AS new_balance,
    NOW() + INTERVAL '7 days' AS next_claim_available;
END;
$$;


ALTER FUNCTION "public"."claim_cashback"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_clue_milestone"("p_milestone_key" "text", "p_m1u_amount" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_new_balance INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF EXISTS(SELECT 1 FROM public.user_clue_milestones WHERE user_id = v_user_id AND milestone_key = p_milestone_key) THEN
    RETURN jsonb_build_object('success', false, 'already_claimed', true);
  END IF;
  
  INSERT INTO public.user_clue_milestones (user_id, milestone_key, m1u_amount) VALUES (v_user_id, p_milestone_key, p_m1u_amount);
  
  UPDATE public.profiles SET m1_units = COALESCE(m1_units, 0) + p_m1u_amount, updated_at = now() WHERE id = v_user_id RETURNING m1_units INTO v_new_balance;
  
  RETURN jsonb_build_object('success', true, 'm1u_granted', p_m1u_amount, 'new_balance', v_new_balance);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'already_claimed', true);
END;
$$;


