CREATE OR REPLACE FUNCTION "public"."claim_final_prize"("p_grand_prize_id" "text", "p_user_id" "uuid", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  existing_winner UUID;
BEGIN
  -- Check se già claimed
  SELECT winner_user_id INTO existing_winner
  FROM public.final_prize_claims
  WHERE grand_prize_id = p_grand_prize_id;
  
  IF existing_winner IS NOT NULL THEN
    IF existing_winner = p_user_id THEN
      RETURN jsonb_build_object(
        'success', true,
        'status', 'already_won',
        'message', 'Sei già il vincitore di questo premio!'
      );
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'status', 'already_claimed',
        'error', 'Il premio finale è già stato vinto.',
        'winner_claimed_at', (SELECT won_at FROM public.final_prize_claims WHERE grand_prize_id = p_grand_prize_id)
      );
    END IF;
  END IF;
  
  -- Tenta insert atomico
  BEGIN
    INSERT INTO public.final_prize_claims (grand_prize_id, winner_user_id, evidence)
    VALUES (p_grand_prize_id, p_user_id, p_evidence);
    
    -- Registra in prize_awards
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence)
    VALUES ('final', p_grand_prize_id, p_user_id, 'final_prize_claim', p_evidence);
    
    RETURN jsonb_build_object(
      'success', true,
      'status', 'winner',
      'won_at', now(),
      'message', '🎉 CONGRATULAZIONI! Sei il VINCITORE del premio finale!'
    );
    
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 'already_claimed',
      'error', 'Il premio finale è stato vinto da un altro utente un istante prima.'
    );
  END;
END;
$$;


ALTER FUNCTION "public"."claim_final_prize"("p_grand_prize_id" "text", "p_user_id" "uuid", "p_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_final_prize"("p_grand_prize_id" "text", "p_user_id" "uuid", "p_evidence" "jsonb") IS 'Claim atomico per premio finale con idempotenza e lock via PK.';



CREATE OR REPLACE FUNCTION "public"."claim_lottery_prize"("p_winner_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_winner RECORD;
  v_new_balance NUMERIC;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'NOT_AUTHENTICATED',
      'message', 'Devi essere autenticato per riscuotere il premio'
    );
  END IF;
  
  -- Recupera il winner record
  SELECT * INTO v_winner
  FROM public.lottery_winners
  WHERE id = p_winner_id
  FOR UPDATE;
  
  IF v_winner IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'WINNER_NOT_FOUND',
      'message', 'Record vincitore non trovato'
    );
  END IF;
  
  -- Verifica ownership
  IF v_winner.user_id != v_user_id THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'NOT_OWNER',
      'message', 'Questo premio non ti appartiene'
    );
  END IF;
  
  -- Verifica stato
  IF v_winner.claim_status = 'claimed' THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'ALREADY_CLAIMED',
      'message', 'Premio già riscosso'
    );
  END IF;
  
  IF v_winner.claim_status IN ('expired', 'forfeited') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'PRIZE_EXPIRED',
      'message', 'Il tempo per riscuotere il premio è scaduto'
    );
  END IF;
  
  -- Verifica deadline
  IF now() > v_winner.claim_deadline THEN
    -- Marca come expired
    UPDATE public.lottery_winners
    SET claim_status = 'expired', updated_at = now()
    WHERE id = p_winner_id;
    
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'DEADLINE_PASSED',
      'message', 'Il tempo per riscuotere il premio è scaduto'
    );
  END IF;
  
  -- Accredita M1U
  UPDATE public.profiles
  SET m1_units = m1_units + v_winner.prize_m1u,
      updated_at = now()
  WHERE id = v_user_id
  RETURNING m1_units INTO v_new_balance;
  
  -- Marca come claimed
  UPDATE public.lottery_winners
  SET claim_status = 'claimed',
      claimed_at = now(),
      updated_at = now()
  WHERE id = p_winner_id;
  
  -- Log audit
  INSERT INTO public.lottery_audit_logs (cycle_id, event_type, user_id, event_details)
  VALUES (
    v_winner.cycle_id,
    'prize_claimed',
    v_user_id,
    jsonb_build_object(
      'winner_id', p_winner_id,
      'rank', v_winner.rank,
      'prize_m1u', v_winner.prize_m1u,
      'new_balance', v_new_balance
    )
  );
  
  RETURN jsonb_build_object(
    'status', 'success',
    'message', format('Congratulazioni! Hai riscosso %s M1U!', v_winner.prize_m1u),
    'prize_m1u', v_winner.prize_m1u,
    'rank', v_winner.rank,
    'prize_label', v_winner.prize_label,
    'new_balance', v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."claim_lottery_prize"("p_winner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_secondary_prize"("p_prize_id" "text", "p_user_id" "uuid", "p_source" "text" DEFAULT NULL::"text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb", "p_marker_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  existing_winner UUID;
BEGIN
  -- Check se già claimed
  SELECT winner_user_id INTO existing_winner
  FROM public.secondary_prize_claims
  WHERE prize_id = p_prize_id;
  
  IF existing_winner IS NOT NULL THEN
    IF existing_winner = p_user_id THEN
      RETURN jsonb_build_object(
        'success', true,
        'status', 'already_won',
        'message', 'Hai già vinto questo premio!'
      );
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'status', 'already_claimed',
        'error', 'Questo premio è già stato vinto da un altro utente.'
      );
    END IF;
  END IF;
  
  -- Tenta insert atomico
  BEGIN
    INSERT INTO public.secondary_prize_claims (prize_id, winner_user_id, evidence, marker_id)
    VALUES (p_prize_id, p_user_id, p_evidence, p_marker_id);
    
    -- Registra in prize_awards
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence)
    VALUES ('secondary', p_prize_id, p_user_id, p_source, p_evidence);
    
    RETURN jsonb_build_object(
      'success', true,
      'status', 'winner',
      'won_at', now(),
      'message', 'Congratulazioni! Hai vinto il premio!'
    );
    
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 'already_claimed',
      'error', 'Il premio è stato vinto da un altro utente un istante prima.'
    );
  END;
END;
$$;


ALTER FUNCTION "public"."claim_secondary_prize"("p_prize_id" "text", "p_user_id" "uuid", "p_source" "text", "p_evidence" "jsonb", "p_marker_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_secondary_prize"("p_prize_id" "text", "p_user_id" "uuid", "p_source" "text", "p_evidence" "jsonb", "p_marker_id" "uuid") IS 'Claim atomico per premio secondario con idempotenza e lock via PK.';



CREATE OR REPLACE FUNCTION "public"."cleanup_duplicate_subscriptions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
  cleaned_count INTEGER := 0;
BEGIN
  -- For each user, keep only the most recent subscription of each tier
  WITH ranked_subs AS (
    SELECT 
      id,
      user_id,
      tier,
      status,
      ROW_NUMBER() OVER (
        PARTITION BY user_id, tier 
        ORDER BY created_at DESC
      ) as rn,
      ROW_NUMBER() OVER (
        PARTITION BY user_id 
        ORDER BY 
          CASE WHEN status = 'active' THEN 1 ELSE 2 END,
          created_at DESC
      ) as global_rn
    FROM public.subscriptions
  ),
  to_cancel AS (
    SELECT id 
    FROM ranked_subs 
    WHERE rn > 1 OR (global_rn > 1 AND status = 'active')
  )
  UPDATE public.subscriptions 
  SET 
    status = 'canceled',
    updated_at = now()
  WHERE id IN (SELECT id FROM to_cancel)
    AND status != 'canceled';
  
  GET DIAGNOSTICS cleaned_count = ROW_COUNT;
  
  result := jsonb_build_object(
    'success', true,
    'duplicates_cleaned', cleaned_count,
    'timestamp', now()
  );
  
  -- Log cleanup action
  INSERT INTO public.panel_logs (event_type, details)
  VALUES ('aggressive_cleanup', result);
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."cleanup_duplicate_subscriptions"() OWNER TO "postgres";


