CREATE OR REPLACE FUNCTION "public"."complete_micro_missions_and_reward"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_already_rewarded BOOLEAN; v_current_m1u INTEGER; v_reward_amount INTEGER := 50;
BEGIN
  SELECT micro_missions_rewarded INTO v_already_rewarded FROM profiles WHERE id = auth.uid();
  IF v_already_rewarded = true THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_rewarded', 'message', 'Ricompensa già ricevuta');
  END IF;
  SELECT COALESCE(m1_units, 0) INTO v_current_m1u FROM profiles WHERE id = auth.uid();
  UPDATE profiles SET micro_missions_completed = true, micro_missions_rewarded = true,
    micro_missions_rewarded_at = NOW(), m1_units = v_current_m1u + v_reward_amount, updated_at = NOW()
  WHERE id = auth.uid();
  RETURN jsonb_build_object('success', true, 'reward', v_reward_amount, 'new_balance', v_current_m1u + v_reward_amount);
END;
$$;


