CREATE OR REPLACE FUNCTION "public"."compute_clue_slot"("p_buzz_index" integer, "p_total_per_type" integer DEFAULT 500) RETURNS TABLE("week" smallint, "tier" smallint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  per_week INT;
  per_tier INT;
  idx INT;
BEGIN
  IF p_buzz_index IS NULL OR p_buzz_index < 1 THEN
    p_buzz_index := 1;
  END IF;

  IF p_total_per_type IS NULL OR p_total_per_type < 20 THEN
    p_total_per_type := 500;
  END IF;

  per_week := CEIL(p_total_per_type::NUMERIC / 4)::INT;
  per_tier := GREATEST(1, CEIL(per_week::NUMERIC / 5)::INT);

  idx := p_buzz_index - 1;

  week := LEAST(4, (FLOOR(idx::NUMERIC / per_week) + 1)::INT)::SMALLINT;

  tier := LEAST(
    5,
    (FLOOR(((idx % per_week)::NUMERIC) / per_tier) + 1)::INT
  )::SMALLINT;

  RETURN NEXT;
END $$;


ALTER FUNCTION "public"."compute_clue_slot"("p_buzz_index" integer, "p_total_per_type" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_clue_slot_v2"("p_buzz_index" integer, "p_total" integer DEFAULT 500, "p_weeks" integer DEFAULT 4, "p_tiers" integer DEFAULT 5) RETURNS TABLE("week" smallint, "tier" smallint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  per_week INTEGER;
  per_tier INTEGER;
  idx INTEGER;
BEGIN
  IF p_total <= 0 OR p_weeks <= 0 OR p_tiers <= 0 THEN
    RAISE EXCEPTION 'Invalid params';
  END IF;

  per_week := CEIL(p_total::NUMERIC / p_weeks)::INT;
  per_tier := CEIL(per_week::NUMERIC / p_tiers)::INT;

  idx := GREATEST(1, LEAST(p_buzz_index, p_total));

  week := ((idx - 1) / per_week) + 1;
  tier := (((idx - 1) % per_week) / per_tier) + 1;

  week := GREATEST(1, LEAST(week, p_weeks))::SMALLINT;
  tier := GREATEST(1, LEAST(tier, p_tiers))::SMALLINT;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."compute_clue_slot_v2"("p_buzz_index" integer, "p_total" integer, "p_weeks" integer, "p_tiers" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_buzz_mappa"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  week_start DATE;
  current_week INTEGER;
  max_allowed INTEGER;
  next_reset TIMESTAMP WITH TIME ZONE;
  result JSONB;
BEGIN
  -- Get current week info
  week_start := public.get_week_start_date();
  current_week := public.get_current_game_week();
  max_allowed := public.get_max_buzz_for_week(current_week);
  
  -- Calculate next reset (next Monday at 00:00)
  next_reset := (week_start + INTERVAL '7 days')::TIMESTAMP WITH TIME ZONE;
  
  -- Insert or update user's weekly record
  INSERT INTO public.user_weekly_buzz_limits (
    user_id, week_start_date, week_number, buzz_map_count, 
    max_buzz_map_allowed, last_buzz_at, next_reset_at
  )
  VALUES (
    p_user_id, week_start, current_week, 1, 
    max_allowed, NOW(), next_reset
  )
  ON CONFLICT (user_id, week_start_date)
  DO UPDATE SET
    buzz_map_count = user_weekly_buzz_limits.buzz_map_count + 1,
    last_buzz_at = NOW(),
    updated_at = NOW()
  RETURNING 
    buzz_map_count, 
    max_buzz_map_allowed,
    week_number,
    next_reset_at
  INTO result;
  
  -- Return status info
  RETURN jsonb_build_object(
    'success', TRUE,
    'buzz_count', (result->>'buzz_map_count')::INTEGER,
    'max_allowed', (result->>'max_buzz_map_allowed')::INTEGER,
    'week_number', (result->>'week_number')::INTEGER,
    'next_reset', result->>'next_reset_at',
    'remaining', (result->>'max_buzz_map_allowed')::INTEGER - (result->>'buzz_map_count')::INTEGER
  );
END;
$$;


ALTER FUNCTION "public"."consume_buzz_mappa"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_buzz_usage"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_week INTEGER;
  current_year INTEGER;
  updated_rows INTEGER;
BEGIN
  -- Get current week and year
  SELECT week_num, year_num INTO current_week, current_year 
  FROM public.get_current_week_and_year();
  
  -- Update used buzz count if within limits
  UPDATE public.weekly_buzz_allowances
  SET used_buzz_count = used_buzz_count + 1
  WHERE user_id = p_user_id 
    AND week_number = current_week 
    AND year = current_year
    AND used_buzz_count < max_buzz_count;
  
  GET DIAGNOSTICS updated_rows = ROW_COUNT;
  
  RETURN updated_rows > 0;
END;
$$;


ALTER FUNCTION "public"."consume_buzz_usage"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_credit"("p_user_id" "uuid", "p_credit_type" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_credits_available INTEGER;
BEGIN
  -- Check available credits
  IF p_credit_type = 'buzz' THEN
    SELECT free_buzz_credit INTO v_credits_available
    FROM public.user_credits
    WHERE user_id = p_user_id;
    
    IF v_credits_available > 0 THEN
      UPDATE public.user_credits
      SET free_buzz_credit = free_buzz_credit - 1
      WHERE user_id = p_user_id;
      RETURN TRUE;
    END IF;
  ELSIF p_credit_type = 'buzz_map' THEN
    SELECT free_buzz_map_credit INTO v_credits_available
    FROM public.user_credits
    WHERE user_id = p_user_id;
    
    IF v_credits_available > 0 THEN
      UPDATE public.user_credits
      SET free_buzz_map_credit = free_buzz_map_credit - 1
      WHERE user_id = p_user_id;
      RETURN TRUE;
    END IF;
  END IF;
  
  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."consume_credit"("p_user_id" "uuid", "p_credit_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_free_buzz"() RETURNS "public"."consume_free_buzz_result"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_row public.admin_buzz_overrides%rowtype;
  v_remaining int;
  v_result public.consume_free_buzz_result;
begin
  if v_uid is null then
    v_result := (false, 0, 'not_authenticated');
    return v_result;
  end if;

  select * into v_row
  from public.admin_buzz_overrides
  where user_id = v_uid
    and (expires_at is null or expires_at > now())
  for update;

  if not found then
    v_result := (false, 0, 'no_override');
    return v_result;
  end if;

  v_remaining := greatest(v_row.free_quota - v_row.free_used, 0);

  if v_remaining <= 0 then
    v_result := (false, 0, 'no_free_remaining');
    return v_result;
  end if;

  update public.admin_buzz_overrides
     set free_used = free_used + 1
   where user_id = v_uid;

  v_remaining := v_remaining - 1;
  v_result := (true, v_remaining, 'consumed');
  return v_result;
end
$$;


ALTER FUNCTION "public"."consume_free_buzz"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contribute_to_jackpot_fund"("p_tier" integer, "p_purchase_amount" numeric, "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_fund RECORD;
  v_contribution NUMERIC;
BEGIN
  -- Recupera il fund per questo tier
  SELECT * INTO v_fund FROM public.scratch_jackpot_fund WHERE tier = p_tier FOR UPDATE;
  
  IF v_fund IS NULL THEN
    RETURN; -- Nessun fund configurato per questo tier
  END IF;
  
  -- Calcola contributo
  v_contribution := p_purchase_amount * v_fund.contribution_rate;
  
  -- Aggiorna il fund
  UPDATE public.scratch_jackpot_fund
  SET balance = balance + v_contribution,
      total_contributed = total_contributed + v_contribution,
      updated_at = now()
  WHERE tier = p_tier;
  
  -- Log
  INSERT INTO public.scratch_jackpot_logs (tier, user_id, event_type, amount, fund_balance_before, fund_balance_after, details)
  VALUES (
    p_tier, 
    p_user_id, 
    'contribution', 
    v_contribution, 
    v_fund.balance, 
    v_fund.balance + v_contribution,
    jsonb_build_object('purchase_amount', p_purchase_amount, 'rate', v_fund.contribution_rate)
  );
END;
$$;


ALTER FUNCTION "public"."contribute_to_jackpot_fund"("p_tier" integer, "p_purchase_amount" numeric, "p_user_id" "uuid") OWNER TO "postgres";


