CREATE OR REPLACE FUNCTION "public"."create_free_subscription"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_sub record;
begin
  -- Se esiste già una ACTIVE, restituiscila (idempotente)
  select id, tier, status, created_at
    into v_sub
    from public.subscriptions
   where user_id = v_user and status = 'active'
   order by created_at desc
   limit 1;

  if found then
    return jsonb_build_object('id', v_sub.id, 'tier', v_sub.tier, 'status', v_sub.status);
  end if;

  -- Inserisci FREE attivo
  insert into public.subscriptions (user_id, tier, status)
  values (v_user, 'free', 'active')
  on conflict do nothing;

  -- Ritorna lo stato finale
  select id, tier, status, created_at
    into v_sub
    from public.subscriptions
   where user_id = v_user and status = 'active'
   order by created_at desc
   limit 1;

  return jsonb_build_object('id', v_sub.id, 'tier', v_sub.tier, 'status', v_sub.status);
end;
$$;


ALTER FUNCTION "public"."create_free_subscription"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_group_chat"("p_member_ids" "uuid"[], "p_group_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_conv_id UUID;
  v_mid UUID;
BEGIN
  INSERT INTO chat_conversations (type, name)
  VALUES ('group', p_group_name)
  RETURNING id INTO v_conv_id;
  
  INSERT INTO chat_members (conversation_id, user_id, role)
  VALUES (v_conv_id, v_user_id, 'owner');
  
  FOREACH v_mid IN ARRAY p_member_ids LOOP
    IF v_mid <> v_user_id THEN
      INSERT INTO chat_members (conversation_id, user_id, role)
      VALUES (v_conv_id, v_mid, 'member')
      ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
  
  INSERT INTO chat_messages (conversation_id, sender_id, content_encrypted, message_type)
  VALUES (v_conv_id, v_user_id, encrypt_chat_message('Gruppo creato'), 'system');
  
  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."create_group_chat"("p_member_ids" "uuid"[], "p_group_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lottery_cycle"("p_starts_at" timestamp with time zone DEFAULT "now"(), "p_duration_days" integer DEFAULT 30, "p_ticket_price_m1u" integer DEFAULT 10, "p_min_tickets_required" integer DEFAULT 4000, "p_max_tickets_per_user" integer DEFAULT 100, "p_prizes_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
  v_cycle_id UUID;
  v_ends_at TIMESTAMPTZ;
  v_default_prizes JSONB := '[
    {"rank": 1, "percent": 50, "label": "1° Premio"},
    {"rank": 2, "percent": 30, "label": "2° Premio"},
    {"rank": 3, "percent": 20, "label": "3° Premio"}
  ]'::jsonb;
BEGIN
  -- Verifica admin
  v_user_id := auth.uid();
  
  SELECT role INTO v_user_role
  FROM public.profiles
  WHERE id = v_user_id;
  
  IF v_user_role NOT IN ('admin', 'owner') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'UNAUTHORIZED',
      'message', 'Solo gli admin possono creare cicli lotteria'
    );
  END IF;
  
  -- Verifica no cicli attivi sovrapposti
  IF EXISTS (
    SELECT 1 FROM public.mission_cycles
    WHERE status = 'active'
    AND (p_starts_at, p_starts_at + (p_duration_days || ' days')::interval) 
        OVERLAPS (starts_at, ends_at)
  ) THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'OVERLAPPING_CYCLE',
      'message', 'Esiste già un ciclo attivo che si sovrappone a queste date'
    );
  END IF;
  
  v_ends_at := p_starts_at + (p_duration_days || ' days')::interval;
  
  -- Crea ciclo
  INSERT INTO public.mission_cycles (
    starts_at,
    ends_at,
    status,
    ticket_price_m1u,
    min_tickets_required,
    max_tickets_per_user,
    prizes_json,
    created_by
  )
  VALUES (
    p_starts_at,
    v_ends_at,
    CASE WHEN p_starts_at <= now() THEN 'active' ELSE 'active' END,
    p_ticket_price_m1u,
    p_min_tickets_required,
    p_max_tickets_per_user,
    COALESCE(p_prizes_json, v_default_prizes),
    v_user_id
  )
  RETURNING id INTO v_cycle_id;
  
  -- Audit log
  INSERT INTO public.lottery_audit_logs (
    cycle_id, user_id, event_type, event_details
  )
  VALUES (
    v_cycle_id,
    v_user_id,
    'cycle_created',
    jsonb_build_object(
      'starts_at', p_starts_at,
      'ends_at', v_ends_at,
      'duration_days', p_duration_days,
      'ticket_price_m1u', p_ticket_price_m1u,
      'min_tickets_required', p_min_tickets_required,
      'max_tickets_per_user', p_max_tickets_per_user
    )
  );
  
  RETURN jsonb_build_object(
    'status', 'success',
    'cycle_id', v_cycle_id,
    'starts_at', p_starts_at,
    'ends_at', v_ends_at,
    'message', 'Ciclo lotteria creato con successo'
  );
END;
$$;


ALTER FUNCTION "public"."create_lottery_cycle"("p_starts_at" timestamp with time zone, "p_duration_days" integer, "p_ticket_price_m1u" integer, "p_min_tickets_required" integer, "p_max_tickets_per_user" integer, "p_prizes_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_lottery_cycle"("p_starts_at" timestamp with time zone, "p_duration_days" integer, "p_ticket_price_m1u" integer, "p_min_tickets_required" integer, "p_max_tickets_per_user" integer, "p_prizes_json" "jsonb") IS 'M1SSION™ Lottery - Crea nuovo ciclo (solo admin). Verifica no overlap.';



