CREATE OR REPLACE FUNCTION "public"."decrement_user_m1u"("p_user_id" "uuid", "p_amount" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_current_balance INTEGER;
    v_new_balance INTEGER;
BEGIN
    -- Get current balance
    SELECT COALESCE(m1_units, 0) INTO v_current_balance
    FROM profiles
    WHERE id = p_user_id;
    
    -- Check if sufficient balance
    IF v_current_balance < p_amount THEN
        RAISE EXCEPTION 'Insufficient M1U balance: % < %', v_current_balance, p_amount;
    END IF;
    
    -- Update profiles.m1_units
    UPDATE profiles
    SET 
        m1_units = m1_units - p_amount,
        updated_at = now()
    WHERE id = p_user_id
    RETURNING m1_units INTO v_new_balance;
    
    -- Also update user_wallet if exists
    UPDATE user_wallet
    SET 
        balance_m1u = balance_m1u - p_amount,
        total_spent_m1u = total_spent_m1u + p_amount,
        updated_at = now()
    WHERE user_id = p_user_id;
    
    RETURN v_new_balance;
END;
$$;


ALTER FUNCTION "public"."decrement_user_m1u"("p_user_id" "uuid", "p_amount" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decrement_user_m1u"("p_user_id" "uuid", "p_amount" integer) IS 'Atomically decrement user M1U balance with balance check';



CREATE OR REPLACE FUNCTION "public"."decrypt_chat_message"("encrypted_content" "bytea") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN pgp_sym_decrypt(encrypted_content, 'm1ss10n_ch4t_3ncrypt10n_k3y_2025');
EXCEPTION WHEN OTHERS THEN
  RETURN '[Messaggio non disponibile]';
END;
$$;


ALTER FUNCTION "public"."decrypt_chat_message"("encrypted_content" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."determine_is_fake"("p_mission_id" "uuid", "p_clue_index" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_seed BIGINT;
  v_hash TEXT;
BEGIN
  -- Create deterministic seed from mission_id + clue_index
  v_hash := md5(p_mission_id::TEXT || ':' || p_clue_index::TEXT);
  v_seed := ('x' || substr(v_hash, 1, 8))::bit(32)::bigint;
  
  -- 25% fake = every 4th clue on average (seed mod 4 == 0)
  RETURN (v_seed % 4) = 0;
END;
$$;


ALTER FUNCTION "public"."determine_is_fake"("p_mission_id" "uuid", "p_clue_index" integer) OWNER TO "postgres";


