CREATE OR REPLACE FUNCTION "public"."execute_final_shoot"("p_user_id" "uuid", "p_mission_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  prize_lat DOUBLE PRECISION;
  prize_lng DOUBLE PRECISION;
  distance DOUBLE PRECISION;
  tolerance_meters DOUBLE PRECISION := 19;
  is_winner BOOLEAN;
  attempt_record_id UUID;
  existing_winner UUID;
  -- Pricing variables
  v_pricing JSONB;
  v_attempts_used INTEGER;
  v_next_attempt INTEGER;
  v_tier TEXT;
  v_cost INTEGER;
  v_allowed BOOLEAN;
  v_reason TEXT;
  -- Balance variables
  v_balance_before INTEGER;
  v_balance_after INTEGER;
BEGIN
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 1: Verifica disponibilità Final Shoot (ultimi 7 giorni)
  -- ═══════════════════════════════════════════════════════════════════════════
  IF NOT public.is_final_shoot_available(p_mission_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 'not_available',
      'error', 'Final Shot non ancora disponibile. Attendi gli ultimi 7 giorni di missione.'
    );
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 2: Get pricing info (server-side calculation)
  -- ═══════════════════════════════════════════════════════════════════════════
  v_pricing := public.get_final_shoot_pricing(p_user_id, p_mission_id);
  v_attempts_used := (v_pricing->>'attempts_used')::INTEGER;
  v_next_attempt := (v_pricing->>'next_attempt_number')::INTEGER;
  v_tier := v_pricing->>'tier';
  v_cost := (v_pricing->>'cost_m1u')::INTEGER;
  v_allowed := (v_pricing->>'allowed')::BOOLEAN;
  v_reason := v_pricing->>'reason';
  
  -- Check if cap reached
  IF NOT v_allowed THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 'cap_reached',
      'error', 'Hai raggiunto il limite massimo di 23 tentativi per questa missione.',
      'attempts_used', v_attempts_used,
      'pricing', v_pricing
    );
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 3: Get current balance and charge M1U if needed
  -- ═══════════════════════════════════════════════════════════════════════════
  -- Get current balance with row lock
  SELECT COALESCE(m1_units, 0) INTO v_balance_before
  FROM public.profiles
  WHERE id = p_user_id
  FOR UPDATE;
  
  -- Default: balance unchanged for free attempts
  v_balance_after := v_balance_before;
  
  IF v_cost > 0 THEN
    -- Check sufficient funds
    IF v_balance_before < v_cost THEN
      RETURN jsonb_build_object(
        'success', false,
        'status', 'insufficient_funds',
        'error', format('Saldo M1U insufficiente. Richiesti: %s M1U, Disponibili: %s M1U', v_cost, v_balance_before),
        'required_m1u', v_cost,
        'balance_before', v_balance_before,
        'balance_after', v_balance_before, -- unchanged
        'tier', v_tier,
        'pricing', v_pricing
      );
    END IF;
    
    -- Deduct M1U atomically
    UPDATE public.profiles
    SET 
      m1_units = m1_units - v_cost,
      updated_at = now()
    WHERE id = p_user_id
    RETURNING m1_units INTO v_balance_after;
    
    -- Also update user_wallet if exists
    UPDATE public.user_wallet
    SET 
      balance_m1u = balance_m1u - v_cost,
      total_spent_m1u = total_spent_m1u + v_cost,
      updated_at = now()
    WHERE user_id = p_user_id;
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 4: Verifica se esiste già un vincitore per questa missione
  -- ═══════════════════════════════════════════════════════════════════════════
  SELECT winner_user_id INTO existing_winner
  FROM public.final_shoot_winners
  WHERE mission_id = p_mission_id
  LIMIT 1;
  
  IF existing_winner IS NOT NULL THEN
    -- REFUND if paid (mission already won)
    IF v_cost > 0 THEN
      UPDATE public.profiles
      SET m1_units = m1_units + v_cost, updated_at = now()
      WHERE id = p_user_id
      RETURNING m1_units INTO v_balance_after;
      
      UPDATE public.user_wallet
      SET balance_m1u = balance_m1u + v_cost, total_spent_m1u = total_spent_m1u - v_cost, updated_at = now()
      WHERE user_id = p_user_id;
    END IF;
    
    IF existing_winner = p_user_id THEN
      RETURN jsonb_build_object(
        'success', false,
        'status', 'already_won',
        'error', 'Hai già vinto questa missione!',
        'refunded', v_cost > 0,
        'refund_amount', v_cost,
        'balance_before', v_balance_before,
        'balance_after', v_balance_after
      );
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'status', 'mission_claimed',
        'error', 'Questa missione è già stata vinta da un altro utente.',
        'refunded', v_cost > 0,
        'refund_amount', v_cost,
        'balance_before', v_balance_before,
        'balance_after', v_balance_after
      );
    END IF;
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 5: Ottieni coordinate premio
  -- ═══════════════════════════════════════════════════════════════════════════
  SELECT cmd.prize_lat, cmd.prize_lng INTO prize_lat, prize_lng
  FROM public.current_mission_data cmd
  WHERE cmd.is_active = true
  ORDER BY cmd.created_at DESC
  LIMIT 1;
  
  IF prize_lat IS NULL OR prize_lng IS NULL THEN
    -- REFUND if paid (config error)
    IF v_cost > 0 THEN
      UPDATE public.profiles
      SET m1_units = m1_units + v_cost, updated_at = now()
      WHERE id = p_user_id
      RETURNING m1_units INTO v_balance_after;
      
      UPDATE public.user_wallet
      SET balance_m1u = balance_m1u + v_cost, total_spent_m1u = total_spent_m1u - v_cost, updated_at = now()
      WHERE user_id = p_user_id;
    END IF;
    
    RETURN jsonb_build_object(
      'success', false,
      'status', 'config_error',
      'error', 'Coordinate premio non configurate.',
      'refunded', v_cost > 0,
      'refund_amount', v_cost,
      'balance_before', v_balance_before,
      'balance_after', v_balance_after
    );
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 6: Calcola distanza usando formula Haversine (in metri)
  -- ═══════════════════════════════════════════════════════════════════════════
  distance := 6371000 * 2 * ASIN(
    SQRT(
      POWER(SIN(RADIANS(p_lat - prize_lat) / 2), 2) +
      COS(RADIANS(prize_lat)) * COS(RADIANS(p_lat)) *
      POWER(SIN(RADIANS(p_lng - prize_lng) / 2), 2)
    )
  );
  
  -- Determina se è vincitore (entro 19 metri)
  is_winner := distance <= tolerance_meters;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 7: Registra tentativo con pricing info
  -- ═══════════════════════════════════════════════════════════════════════════
  INSERT INTO public.final_shoot_attempts (
    user_id, mission_id, attempt_lat, attempt_lng, 
    distance_meters, is_winner, attempt_number,
    cost_m1u, tier, charged
  ) VALUES (
    p_user_id, p_mission_id, p_lat, p_lng,
    distance, is_winner, v_next_attempt,
    v_cost, v_tier, (v_cost > 0)
  )
  RETURNING id INTO attempt_record_id;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- STEP 8: Se vincitore, tenta lock atomico
  -- ═══════════════════════════════════════════════════════════════════════════
  IF is_winner THEN
    BEGIN
      INSERT INTO public.final_shoot_winners (mission_id, winner_user_id, attempt_id, won_at, distance_meters)
      VALUES (p_mission_id, p_user_id, attempt_record_id, NOW(), distance)
      ON CONFLICT (mission_id) DO NOTHING;
      
      -- Verifica se siamo stati noi a vincere
      SELECT winner_user_id INTO existing_winner
      FROM public.final_shoot_winners
      WHERE mission_id = p_mission_id;
      
      IF existing_winner = p_user_id THEN
        RETURN jsonb_build_object(
          'success', true,
          'status', 'winner',
          'winner', true,
          'distance_meters', distance,
          'attempts_remaining', 23 - v_next_attempt,
          'message', 'Complimenti! Hai trovato il premio!',
          'cost_charged', v_cost,
          'tier', v_tier,
          'balance_before', v_balance_before,
          'balance_after', v_balance_after
        );
      ELSE
        -- Race condition lost - still charged (attempt was valid)
        RETURN jsonb_build_object(
          'success', true,
          'status', 'race_lost',
          'winner', false,
          'distance_meters', distance,
          'attempts_remaining', 23 - v_next_attempt,
          'hint', 'Eri sulla posizione giusta, ma qualcun altro ha vinto per primo!',
          'cost_charged', v_cost,
          'tier', v_tier,
          'balance_before', v_balance_before,
          'balance_after', v_balance_after
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object(
        'success', true,
        'status', 'race_error',
        'winner', false,
        'distance_meters', distance,
        'attempts_remaining', 23 - v_next_attempt,
        'hint', 'Tentativo registrato, ma verifica risultato.',
        'cost_charged', v_cost,
        'tier', v_tier,
        'balance_before', v_balance_before,
        'balance_after', v_balance_after
      );
    END;
  ELSE
    -- Non vincitore - hint con soglie ragionevoli
    RETURN jsonb_build_object(
      'success', true,
      'status', 'missed',
      'winner', false,
      'distance_meters', distance,
      'attempts_remaining', 23 - v_next_attempt,
      'hint', CASE 
        WHEN distance <= 19 THEN '🎯 PERFETTO! HAI VINTO!'
        WHEN distance <= 150 THEN '🔥 Ci sei quasi! Pochissimi passi!'
        WHEN distance <= 500 THEN '🌡️ Molto vicino! Sei in zona calda!'
        WHEN distance <= 1000 THEN '☀️ Vicino! Continua così!'
        WHEN distance <= 3000 THEN '😊 Sei in zona. Esplora meglio!'
        WHEN distance <= 5000 THEN '😐 Zona giusta ma non vicinissimo.'
        WHEN distance <= 10000 THEN '❄️ Lontano. Cambia direzione!'
        WHEN distance <= 25000 THEN '🥶 Molto lontano. Riconsidera la zona!'
        ELSE '🌍 Lontanissimo! Sei fuori area.'
      END,
      'cost_charged', v_cost,
      'tier', v_tier,
      'balance_before', v_balance_before,
      'balance_after', v_balance_after,
      'pricing', public.get_final_shoot_pricing(p_user_id, p_mission_id)
    );
  END IF;
  
EXCEPTION WHEN OTHERS THEN
  -- On any error, attempt refund if paid
  IF v_cost > 0 THEN
    BEGIN
      UPDATE public.profiles
      SET m1_units = m1_units + v_cost, updated_at = now()
      WHERE id = p_user_id
      RETURNING m1_units INTO v_balance_after;
      
      UPDATE public.user_wallet
      SET balance_m1u = balance_m1u + v_cost, total_spent_m1u = total_spent_m1u - v_cost, updated_at = now()
      WHERE user_id = p_user_id;
    EXCEPTION WHEN OTHERS THEN
      -- Log refund failure but don't mask original error
      NULL;
    END;
  END IF;
  
  RETURN jsonb_build_object(
    'success', false,
    'status', 'error',
    'error', SQLERRM,
    'refund_attempted', v_cost > 0,
    'balance_before', v_balance_before,
    'balance_after', COALESCE(v_balance_after, v_balance_before)
  );
END;
$$;


ALTER FUNCTION "public"."execute_final_shoot"("p_user_id" "uuid", "p_mission_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_final_shoot"("p_user_id" "uuid", "p_mission_id" "uuid", "p_lat" double precision, "p_lng" double precision) IS 'Execute Final Shoot attempt with atomic M1U charging. 
Validates funds before attempt, refunds on system errors.';



CREATE OR REPLACE FUNCTION "public"."execute_wheel_progress"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_today DATE := CURRENT_DATE;
  v_spin_id UUID;
  v_progress RECORD;
  v_segment_id INT;
  v_progress_gain INT;
  v_milestone_reached BOOLEAN := false;
  v_milestone_level INT;
  v_reward_value INT := 0;
  v_reward_type TEXT := 'm1u';
  v_current_m1u INT;
  
  -- Deterministic milestone thresholds (every 100 points = milestone)
  c_milestone_threshold CONSTANT INT := 100;
  c_base_progress CONSTANT INT := 10; -- Base progress per interaction
  c_milestone_bonus CONSTANT INT := 5; -- Bonus M1U per milestone
BEGIN
  -- 1. VERIFY AUTHENTICATION
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'User not authenticated'
    );
  END IF;

  -- 2. CHECK IF ALREADY INTERACTED TODAY (1 per day limit)
  SELECT * INTO v_progress
  FROM public.user_progress_meters
  WHERE user_id = v_user_id AND meter_type = 'wheel';
  
  IF v_progress IS NOT NULL AND v_progress.last_interaction_date = v_today THEN
    RETURN jsonb_build_object(
      'status', 'already_completed_today',
      'message', 'Progressione giornaliera completata. Torna domani!',
      'progress_points', v_progress.progress_points,
      'milestone_level', v_progress.milestone_level
    );
  END IF;

  -- 3. CALCULATE DETERMINISTIC PROGRESS (NO RNG)
  -- Progress gain is deterministic based on consecutive days
  IF v_progress IS NULL THEN
    v_progress_gain := c_base_progress;
    v_milestone_level := 0;
  ELSE
    -- Streak bonus: +1 progress for each consecutive day (max +5)
    v_progress_gain := c_base_progress + LEAST(5, v_progress.total_interactions / 7);
    v_milestone_level := v_progress.milestone_level;
  END IF;

  -- 4. DETERMINE SEGMENT (DETERMINISTIC based on progress level)
  -- Segment cycles through 1-16 based on total progress
  -- This ensures visual variety without randomness
  v_segment_id := ((COALESCE(v_progress.progress_points, 0) + v_progress_gain) / 10 % 16) + 1;
  
  -- 5. CHECK FOR MILESTONE (deterministic threshold)
  IF v_progress IS NOT NULL THEN
    IF (v_progress.progress_points + v_progress_gain) >= ((v_milestone_level + 1) * c_milestone_threshold) THEN
      v_milestone_reached := true;
      v_milestone_level := v_milestone_level + 1;
      v_reward_value := c_milestone_bonus * v_milestone_level; -- Increasing rewards
    END IF;
  END IF;

  -- 6. UPSERT PROGRESS RECORD
  INSERT INTO public.user_progress_meters (
    user_id,
    meter_type,
    progress_points,
    milestone_level,
    last_interaction_date,
    total_interactions,
    updated_at
  ) VALUES (
    v_user_id,
    'wheel',
    COALESCE(v_progress.progress_points, 0) + v_progress_gain,
    v_milestone_level,
    v_today,
    COALESCE(v_progress.total_interactions, 0) + 1,
    now()
  )
  ON CONFLICT (user_id, meter_type) 
  DO UPDATE SET
    progress_points = user_progress_meters.progress_points + v_progress_gain,
    milestone_level = v_milestone_level,
    last_interaction_date = v_today,
    total_interactions = user_progress_meters.total_interactions + 1,
    updated_at = now()
  RETURNING id INTO v_spin_id;

  -- 7. AWARD M1U IF MILESTONE REACHED (deterministic)
  IF v_milestone_reached AND v_reward_value > 0 THEN
    SELECT COALESCE(m1_units, 0) INTO v_current_m1u
    FROM public.profiles WHERE id = v_user_id;
    
    UPDATE public.profiles
    SET m1_units = COALESCE(m1_units, 0) + v_reward_value
    WHERE id = v_user_id;
    
    -- Log award
    INSERT INTO public.prize_awards (
      award_type, prize_id, user_id, source, evidence, status
    ) VALUES (
      'progress_milestone',
      'wheel_milestone_' || v_milestone_level,
      v_user_id,
      'wheel_progress',
      jsonb_build_object(
        'milestone_level', v_milestone_level,
        'reward_value', v_reward_value,
        'progress_points', COALESCE(v_progress.progress_points, 0) + v_progress_gain
      ),
      'confirmed'
    );
  END IF;

  -- 8. RECORD IN wheel_spins FOR COMPATIBILITY
  INSERT INTO public.wheel_spins (
    user_id,
    spin_date,
    segment_id,
    reward_type,
    reward_value,
    reward_label
  ) VALUES (
    v_user_id,
    v_today,
    v_segment_id,
    CASE WHEN v_milestone_reached THEN 'm1u' ELSE 'progress' END,
    CASE WHEN v_milestone_reached THEN v_reward_value ELSE v_progress_gain END,
    CASE WHEN v_milestone_reached 
         THEN 'Milestone ' || v_milestone_level || ' (+' || v_reward_value || ' M1U)'
         ELSE 'Avanzamento +' || v_progress_gain
    END
  )
  ON CONFLICT (user_id, spin_date) DO NOTHING;

  -- 9. RETURN PROGRESS RESULT (NO WIN/LOSE LANGUAGE)
  RETURN jsonb_build_object(
    'status', 'success',
    'interaction_id', v_spin_id,
    'segment_id', v_segment_id,
    'progress_gain', v_progress_gain,
    'total_progress', COALESCE(v_progress.progress_points, 0) + v_progress_gain,
    'milestone_reached', v_milestone_reached,
    'milestone_level', v_milestone_level,
    'reward_type', CASE WHEN v_milestone_reached THEN 'm1u' ELSE 'progress' END,
    'reward_value', CASE WHEN v_milestone_reached THEN v_reward_value ELSE v_progress_gain END,
    'message', CASE 
      WHEN v_milestone_reached THEN 'Milestone ' || v_milestone_level || ' raggiunta! +' || v_reward_value || ' M1U'
      ELSE 'Progressione completata! +' || v_progress_gain || ' punti'
    END
  );
END;
$$;


ALTER FUNCTION "public"."execute_wheel_progress"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_wheel_progress"() IS 'STORE COMPLIANT: Deterministic daily progress. No random(), no win/lose.';



CREATE OR REPLACE FUNCTION "public"."execute_wheel_spin"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_today DATE := CURRENT_DATE;
  v_spin_id UUID;
  v_segment_id INT;
  v_reward_type TEXT;
  v_reward_value INT;
  v_reward_label TEXT;
  v_random INT;
  v_current_m1u INT;
  v_current_pe INT;
  
  -- Segmenti definiti come array (evita tabelle temporanee)
  -- Formato: segment_id, cumulative_weight
  -- Total weight = 119
  v_weights INT[] := ARRAY[2, 17, 27, 30, 32, 33, 35, 37, 47, 59, 64, 79, 91, 101, 111, 119];
BEGIN
  -- 1. VERIFICA UTENTE AUTENTICATO
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'User not authenticated'
    );
  END IF;

  -- 2. CALCOLA OUTCOME (weighted random)
  v_random := floor(random() * 119)::INT + 1;
  
  -- Trova segmento vincente basato su pesi cumulativi
  IF v_random <= 2 THEN
    v_segment_id := 1; v_reward_label := '50 M1U'; v_reward_value := 50; v_reward_type := 'm1u';
  ELSIF v_random <= 17 THEN
    v_segment_id := 2; v_reward_label := '5 M1U'; v_reward_value := 5; v_reward_type := 'm1u';
  ELSIF v_random <= 27 THEN
    v_segment_id := 3; v_reward_label := 'LOSE'; v_reward_value := 0; v_reward_type := 'nothing';
  ELSIF v_random <= 30 THEN
    v_segment_id := 4; v_reward_label := '50 PE'; v_reward_value := 50; v_reward_type := 'pe';
  ELSIF v_random <= 32 THEN
    v_segment_id := 5; v_reward_label := '50 M1U'; v_reward_value := 50; v_reward_type := 'm1u';
  ELSIF v_random <= 33 THEN
    v_segment_id := 6; v_reward_label := '200 PE'; v_reward_value := 200; v_reward_type := 'pe';
  ELSIF v_random <= 35 THEN
    v_segment_id := 7; v_reward_label := '100 PE'; v_reward_value := 100; v_reward_type := 'pe';
  ELSIF v_random <= 37 THEN
    v_segment_id := 8; v_reward_label := '50 M1U'; v_reward_value := 50; v_reward_type := 'm1u';
  ELSIF v_random <= 47 THEN
    v_segment_id := 9; v_reward_label := 'LOSE'; v_reward_value := 0; v_reward_type := 'nothing';
  ELSIF v_random <= 59 THEN
    v_segment_id := 10; v_reward_label := 'Retry'; v_reward_value := 0; v_reward_type := 'retry';
  ELSIF v_random <= 64 THEN
    v_segment_id := 11; v_reward_label := 'CLUE'; v_reward_value := 1; v_reward_type := 'clue';
  ELSIF v_random <= 79 THEN
    v_segment_id := 12; v_reward_label := '5 M1U'; v_reward_value := 5; v_reward_type := 'm1u';
  ELSIF v_random <= 91 THEN
    v_segment_id := 13; v_reward_label := 'Retry'; v_reward_value := 0; v_reward_type := 'retry';
  ELSIF v_random <= 101 THEN
    v_segment_id := 14; v_reward_label := 'LOSE'; v_reward_value := 0; v_reward_type := 'nothing';
  ELSIF v_random <= 111 THEN
    v_segment_id := 15; v_reward_label := '3 M1U'; v_reward_value := 3; v_reward_type := 'm1u';
  ELSE
    v_segment_id := 16; v_reward_label := '2 M1U'; v_reward_value := 2; v_reward_type := 'm1u';
  END IF;

  -- 3. TENTA INSERIMENTO ATOMICO (verifica 1 spin/day)
  BEGIN
    INSERT INTO public.wheel_spins (
      user_id, spin_date, segment_id, reward_type, reward_value, reward_label
    ) VALUES (
      v_user_id, v_today, v_segment_id, v_reward_type, v_reward_value, v_reward_label
    )
    RETURNING id INTO v_spin_id;
    
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'status', 'already_spun_today',
      'message', 'You have already spun the wheel today. Come back tomorrow!'
    );
  END;

  -- 4. ASSEGNA REWARD SERVER-SIDE
  IF v_reward_type = 'm1u' AND v_reward_value > 0 THEN
    SELECT COALESCE(m1_units, 0) INTO v_current_m1u FROM public.profiles WHERE id = v_user_id;
    UPDATE public.profiles SET m1_units = COALESCE(m1_units, 0) + v_reward_value WHERE id = v_user_id;
    
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence, status)
    VALUES ('wheel', 'fortune_wheel_m1u_' || v_reward_value, v_user_id, 'fortune_wheel',
      jsonb_build_object('spin_id', v_spin_id, 'segment_id', v_segment_id, 'reward_value', v_reward_value,
        'balance_before', v_current_m1u, 'balance_after', v_current_m1u + v_reward_value), 'confirmed');
    
  ELSIF v_reward_type = 'pe' AND v_reward_value > 0 THEN
    SELECT COALESCE(pulse_energy, 0) INTO v_current_pe FROM public.profiles WHERE id = v_user_id;
    UPDATE public.profiles SET pulse_energy = COALESCE(pulse_energy, 0) + v_reward_value WHERE id = v_user_id;
    
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence, status)
    VALUES ('wheel', 'fortune_wheel_pe_' || v_reward_value, v_user_id, 'fortune_wheel',
      jsonb_build_object('spin_id', v_spin_id, 'segment_id', v_segment_id, 'reward_value', v_reward_value,
        'balance_before', v_current_pe, 'balance_after', v_current_pe + v_reward_value), 'confirmed');
    
  ELSIF v_reward_type = 'clue' THEN
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence, status)
    VALUES ('wheel', 'fortune_wheel_clue', v_user_id, 'fortune_wheel',
      jsonb_build_object('spin_id', v_spin_id, 'segment_id', v_segment_id), 'confirmed');
  END IF;

  -- 5. UPDATE last_fortune_spin
  UPDATE public.profiles SET last_fortune_spin = now() WHERE id = v_user_id;

  -- 6. RITORNA PAYLOAD
  RETURN jsonb_build_object(
    'status', 'success',
    'spin_id', v_spin_id,
    'segment_id', v_segment_id,
    'reward_type', v_reward_type,
    'reward_value', v_reward_value,
    'reward_label', v_reward_label,
    'message', CASE 
      WHEN v_reward_type = 'm1u' THEN 'Hai vinto ' || v_reward_value || ' M1U!'
      WHEN v_reward_type = 'pe' THEN 'Hai vinto ' || v_reward_value || ' PE!'
      WHEN v_reward_type = 'clue' THEN 'Hai vinto un indizio!'
      WHEN v_reward_type = 'retry' THEN 'Riprova domani!'
      ELSE 'LOSE - Riprova domani!'
    END
  );
END;
$$;


ALTER FUNCTION "public"."execute_wheel_spin"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_wheel_spin"() IS 'RPC per eseguire uno spin della Fortune Wheel. Determina outcome server-side, assegna reward atomicamente, garantisce 1 spin/day.';



CREATE OR REPLACE FUNCTION "public"."expire_unclaimed_prizes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expired_count INT;
BEGIN
  UPDATE public.lottery_winners
  SET claim_status = 'expired', updated_at = now()
  WHERE claim_status = 'pending' AND claim_deadline < now();
  
  GET DIAGNOSTICS v_expired_count = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'status', 'success',
    'expired_count', v_expired_count
  );
END;
$$;


ALTER FUNCTION "public"."expire_unclaimed_prizes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extract_location_features"("p_lat" numeric, "p_lng" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_hemisphere TEXT;
  v_lat_band TEXT;
  v_climate_hint TEXT;
  v_coastal_proximity TEXT;
  v_timezone_band TEXT;
  v_abs_lat NUMERIC;
BEGIN
  v_abs_lat := ABS(p_lat);
  
  -- Hemisphere
  v_hemisphere := CASE WHEN p_lat >= 0 THEN 'north' ELSE 'south' END;
  
  -- Latitude band
  v_lat_band := CASE
    WHEN v_abs_lat > 66.5 THEN 'polar'
    WHEN v_abs_lat > 35 THEN 'temperate'
    WHEN v_abs_lat > 23.5 THEN 'subtropical'
    ELSE 'tropical'
  END;
  
  -- Climate hint (simplified inference)
  v_climate_hint := CASE
    WHEN v_abs_lat > 60 THEN 'continental'
    WHEN v_abs_lat BETWEEN 30 AND 45 AND p_lng BETWEEN -10 AND 35 THEN 'mediterranean'
    WHEN v_abs_lat < 25 THEN 'tropical'
    WHEN p_lng BETWEEN -130 AND -60 OR p_lng BETWEEN 100 AND 180 THEN 'oceanic'
    ELSE 'continental'
  END;
  
  -- Coastal proximity (simplified - would need coastline data for accuracy)
  -- Default to 'inland', can be enhanced with actual coastline distance
  v_coastal_proximity := 'inland';
  
  -- Timezone band
  v_timezone_band := CASE
    WHEN p_lng < -30 THEN 'west'
    WHEN p_lng < 30 THEN 'central'
    ELSE 'east'
  END;
  
  RETURN jsonb_build_object(
    'hemisphere', v_hemisphere,
    'lat_band', v_lat_band,
    'climate_hint', v_climate_hint,
    'coastal_proximity', v_coastal_proximity,
    'urban_density', 'urban',  -- Default, can be enhanced
    'timezone_band', v_timezone_band
  );
END;
$$;


ALTER FUNCTION "public"."extract_location_features"("p_lat" numeric, "p_lng" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_cycle_and_draw"("p_cycle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
  v_cycle RECORD;
  v_draw_id UUID;
  v_public_seed TEXT;
  v_prize_multiplier NUMERIC(5,4);
  v_threshold_reached BOOLEAN;
  v_total_prize_pool INT;
  v_winners JSONB := '[]'::jsonb;
  v_ranked_tickets RECORD;
  v_prize_config RECORD;
  v_rank_counter INT := 0;
  v_prize_amount INT;
  v_winner_user_id UUID;
BEGIN
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 1. VERIFICA AUTORIZZAZIONE
  -- ═══════════════════════════════════════════════════════════════════════════
  
  v_user_id := auth.uid();
  
  SELECT role INTO v_user_role
  FROM public.profiles
  WHERE id = v_user_id;
  
  IF v_user_role NOT IN ('admin', 'owner') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'UNAUTHORIZED',
      'message', 'Solo gli admin possono eseguire l''estrazione'
    );
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 2. RECUPERA E BLOCCA CICLO
  -- ═══════════════════════════════════════════════════════════════════════════
  
  SELECT * INTO v_cycle
  FROM public.mission_cycles
  WHERE id = p_cycle_id
  FOR UPDATE;
  
  IF v_cycle IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'CYCLE_NOT_FOUND',
      'message', 'Ciclo non trovato'
    );
  END IF;
  
  IF v_cycle.status NOT IN ('active', 'locking') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'INVALID_STATUS',
      'message', format('Il ciclo è in stato "%s", non può essere estratto', v_cycle.status)
    );
  END IF;
  
  -- Verifica almeno 1 ticket
  IF v_cycle.total_tickets = 0 THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'NO_TICKETS',
      'message', 'Nessun biglietto venduto, estrazione non possibile'
    );
  END IF;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 3. LOCK CICLO (no nuovi acquisti)
  -- ═══════════════════════════════════════════════════════════════════════════
  
  UPDATE public.mission_cycles
  SET status = 'drawing', updated_at = now()
  WHERE id = p_cycle_id;
  
  -- Audit
  INSERT INTO public.lottery_audit_logs (
    cycle_id, user_id, event_type, event_details
  )
  VALUES (
    p_cycle_id, v_user_id, 'draw_started',
    jsonb_build_object('total_tickets', v_cycle.total_tickets)
  );
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 4. GENERA PUBLIC SEED (verifiable randomness)
  -- ═══════════════════════════════════════════════════════════════════════════
  
  v_public_seed := encode(
    sha256(
      (
        p_cycle_id::text || 
        now()::text || 
        gen_random_uuid()::text || 
        v_cycle.total_tickets::text ||
        (SELECT string_agg(id::text, '') FROM public.lottery_tickets WHERE cycle_id = p_cycle_id ORDER BY created_at LIMIT 10)
      )::bytea
    ),
    'hex'
  );
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 5. CALCOLA PRIZE MULTIPLIER (CONTROMISURA SOGLIA)
  -- ═══════════════════════════════════════════════════════════════════════════
  
  v_threshold_reached := v_cycle.total_tickets >= v_cycle.min_tickets_required;
  
  IF v_threshold_reached THEN
    v_prize_multiplier := 1.0000;
  ELSE
    -- Multiplier proporzionale, con minimo 0.25 (25%)
    v_prize_multiplier := GREATEST(
      0.2500,
      ROUND(v_cycle.total_tickets::numeric / v_cycle.min_tickets_required, 4)
    );
  END IF;
  
  -- Prize pool effettivo
  v_total_prize_pool := v_cycle.prize_pool_total;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 6. ESTRAZIONE VINCITORI (ranking deterministico basato su seed)
  -- ═══════════════════════════════════════════════════════════════════════════
  
  -- Per ogni ticket, calcola un rank_score = hash(public_seed + ticket_seed)
  -- Ordina per rank_score, i primi N sono i vincitori
  
  FOR v_ranked_tickets IN (
    SELECT 
      lt.id AS ticket_id,
      lt.user_id,
      lt.ticket_seed,
      encode(
        sha256((v_public_seed || lt.ticket_seed::text || lt.id::text)::bytea),
        'hex'
      ) AS rank_score
    FROM public.lottery_tickets lt
    WHERE lt.cycle_id = p_cycle_id AND lt.status = 'active'
    ORDER BY rank_score ASC
    LIMIT 3 -- Top 3
  ) LOOP
    v_rank_counter := v_rank_counter + 1;
    
    -- Calcola premio per questo rank
    SELECT 
      (elem->>'percent')::numeric / 100 * v_total_prize_pool * v_prize_multiplier
    INTO v_prize_amount
    FROM jsonb_array_elements(v_cycle.prizes_json) elem
    WHERE (elem->>'rank')::int = v_rank_counter;
    
    v_prize_amount := COALESCE(FLOOR(v_prize_amount), 0);
    
    -- Aggiorna ticket come vincitore
    UPDATE public.lottery_tickets
    SET status = 'winner',
        draw_rank = v_rank_counter,
        prize_amount = v_prize_amount
    WHERE id = v_ranked_tickets.ticket_id;
    
    -- Accredita M1U al vincitore
    IF v_prize_amount > 0 THEN
      UPDATE public.profiles
      SET m1_units = m1_units + v_prize_amount,
          updated_at = now()
      WHERE id = v_ranked_tickets.user_id;
      
      -- Registra in prize_awards
      INSERT INTO public.prize_awards (
        award_type, prize_id, user_id, source, evidence
      )
      VALUES (
        'event',
        'lottery_' || p_cycle_id::text || '_rank_' || v_rank_counter,
        v_ranked_tickets.user_id,
        'lottery_draw',
        jsonb_build_object(
          'cycle_id', p_cycle_id,
          'ticket_id', v_ranked_tickets.ticket_id,
          'rank', v_rank_counter,
          'prize_amount', v_prize_amount,
          'prize_multiplier', v_prize_multiplier
        )
      );
      
      -- Analytics
      INSERT INTO public.analytics_events (
        event_name, user_id, session_id, platform, props, event_version
      )
      VALUES (
        'lottery_prize_awarded',
        v_ranked_tickets.user_id,
        'server',
        'web',
        jsonb_build_object(
          'cycle_id', p_cycle_id,
          'rank', v_rank_counter,
          'prize_amount', v_prize_amount
        ),
        1
      );
    END IF;
    
    -- Aggiungi a winners JSON
    v_winners := v_winners || jsonb_build_object(
      'rank', v_rank_counter,
      'user_id', v_ranked_tickets.user_id,
      'ticket_id', v_ranked_tickets.ticket_id,
      'prize_m1u', v_prize_amount
    );
  END LOOP;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 7. CREA RECORD DRAW (immutabile)
  -- ═══════════════════════════════════════════════════════════════════════════
  
  INSERT INTO public.lottery_draws (
    cycle_id,
    draw_started_at,
    draw_completed_at,
    public_seed,
    algorithm_version,
    winners,
    total_tickets_at_draw,
    total_participants_at_draw,
    prize_multiplier,
    threshold_reached
  )
  VALUES (
    p_cycle_id,
    now() - interval '1 second', -- started appena prima
    now(),
    v_public_seed,
    'v1.0.0',
    v_winners,
    v_cycle.total_tickets,
    v_cycle.total_participants,
    v_prize_multiplier,
    v_threshold_reached
  )
  RETURNING id INTO v_draw_id;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 8. AGGIORNA CICLO COME COMPLETATO
  -- ═══════════════════════════════════════════════════════════════════════════
  
  UPDATE public.mission_cycles
  SET status = 'completed',
      prize_multiplier = v_prize_multiplier,
      prizes_effective_json = (
        SELECT jsonb_agg(
          jsonb_build_object(
            'rank', (elem->>'rank')::int,
            'percent', (elem->>'percent')::numeric,
            'label', elem->>'label',
            'amount_m1u', FLOOR(
              (elem->>'percent')::numeric / 100 * v_total_prize_pool * v_prize_multiplier
            )
          )
        )
        FROM jsonb_array_elements(v_cycle.prizes_json) elem
      ),
      updated_at = now()
  WHERE id = p_cycle_id;
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 9. AUDIT FINALE
  -- ═══════════════════════════════════════════════════════════════════════════
  
  INSERT INTO public.lottery_audit_logs (
    cycle_id, user_id, event_type, event_details
  )
  VALUES (
    p_cycle_id, v_user_id, 'draw_completed',
    jsonb_build_object(
      'draw_id', v_draw_id,
      'winners', v_winners,
      'prize_multiplier', v_prize_multiplier,
      'threshold_reached', v_threshold_reached,
      'public_seed', v_public_seed
    )
  );
  
  -- Analytics globale
  INSERT INTO public.analytics_events (
    event_name, user_id, session_id, platform, props, event_version
  )
  VALUES (
    'lottery_draw_complete',
    v_user_id,
    'server',
    'web',
    jsonb_build_object(
      'cycle_id', p_cycle_id,
      'draw_id', v_draw_id,
      'total_tickets', v_cycle.total_tickets,
      'winners_count', jsonb_array_length(v_winners),
      'prize_multiplier', v_prize_multiplier,
      'threshold_reached', v_threshold_reached
    ),
    1
  );
  
  -- ═══════════════════════════════════════════════════════════════════════════
  -- 10. RETURN SUCCESS
  -- ═══════════════════════════════════════════════════════════════════════════
  
  RETURN jsonb_build_object(
    'status', 'success',
    'draw_id', v_draw_id,
    'cycle_id', p_cycle_id,
    'total_tickets', v_cycle.total_tickets,
    'total_participants', v_cycle.total_participants,
    'prize_pool_total', v_total_prize_pool,
    'prize_multiplier', v_prize_multiplier,
    'threshold_reached', v_threshold_reached,
    'winners', v_winners,
    'public_seed', v_public_seed,
    'message', CASE 
      WHEN v_threshold_reached THEN 
        'Estrazione completata! Soglia raggiunta, premi al 100%!'
      ELSE 
        format('Estrazione completata! Soglia non raggiunta (%.0f%%), premi ridotti.', v_prize_multiplier * 100)
    END
  );

EXCEPTION
  WHEN OTHERS THEN
    -- Rollback status
    UPDATE public.mission_cycles
    SET status = 'active', updated_at = now()
    WHERE id = p_cycle_id AND status = 'drawing';
    
    -- Log errore
    INSERT INTO public.lottery_audit_logs (
      cycle_id, user_id, event_type, event_details
    )
    VALUES (
      p_cycle_id, v_user_id, 'error',
      jsonb_build_object('error', SQLERRM, 'phase', 'draw')
    );
    
    RAISE LOG 'Error in finalize_cycle_and_draw: %', SQLERRM;
    
    RETURN jsonb_build_object(
      'status', 'error',
      'code', 'DRAW_FAILED',
      'message', 'Errore durante l''estrazione. Il ciclo è stato ripristinato.',
      'error', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."finalize_cycle_and_draw"("p_cycle_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_cycle_and_draw"("p_cycle_id" "uuid") IS 'M1SSION™ Lottery - Estrazione finale con prize_multiplier e assegnazione premi.';



CREATE OR REPLACE FUNCTION "public"."flag_battle_suspicious"("p_battle_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_admin BOOLEAN;
BEGIN
  -- Only admins (user_roles.role IN admin/superadmin) may flag
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.role IN ('admin', 'superadmin')
  )
  INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin role required to flag battle as suspicious';
  END IF;

  INSERT INTO public.battle_admin_actions (
    battle_id,
    action_type,
    reason,
    created_by
  )
  VALUES (
    p_battle_id,
    'flag_suspicious',
    p_reason,
    auth.uid()
  );
END;
$$;


ALTER FUNCTION "public"."flag_battle_suspicious"("p_battle_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_candidates_for_user"("p_user_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("feed_item_id" "uuid", "score" numeric, "title" "text", "url" "text", "tags" "text"[], "locale" "text", "published_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH prefs AS (
    SELECT COALESCE(resolved_tags, ARRAY[]::text[]) as tags
    FROM public.v_user_resolved_tags
    WHERE user_id = p_user_id
  ), items AS (
    SELECT 
      efi.id, 
      efi.score, 
      efi.title, 
      efi.url, 
      efi.tags, 
      efi.locale, 
      efi.published_at
    FROM public.external_feed_items efi
    CROSS JOIN prefs
    WHERE (efi.tags && prefs.tags)  -- overlap con tag preferenze
      AND efi.published_at > now() - INTERVAL '72 hours'
      AND COALESCE(efi.score, 0) >= 0.72
    ORDER BY efi.published_at DESC, efi.score DESC
    LIMIT GREATEST(p_limit, 1)
  )
  SELECT id, score, title, url, tags, locale, published_at FROM items;
$$;


ALTER FUNCTION "public"."fn_candidates_for_user"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_dna_apply_delta"("p_user" "uuid", "p_delta" "jsonb", "p_source" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cur record;
  i int; a int; e int; r int; v int;
  new_archetype text;
BEGIN
  -- Ensure DNA exists
  INSERT INTO public.agent_dna(user_id) 
  VALUES (p_user)
  ON CONFLICT (user_id) DO NOTHING;

  -- Lock and get current values
  SELECT * INTO cur 
  FROM public.agent_dna 
  WHERE user_id = p_user 
  FOR UPDATE;

  -- Apply delta with clamping (0-100)
  i := GREATEST(0, LEAST(100, COALESCE(cur.intuito, 50) + COALESCE((p_delta->>'intuito')::int, 0)));
  a := GREATEST(0, LEAST(100, COALESCE(cur.audacia, 50) + COALESCE((p_delta->>'audacia')::int, 0)));
  e := GREATEST(0, LEAST(100, COALESCE(cur.etica, 50) + COALESCE((p_delta->>'etica')::int, 0)));
  r := GREATEST(0, LEAST(100, COALESCE(cur.rischio, 50) + COALESCE((p_delta->>'rischio')::int, 0)));
  v := GREATEST(0, LEAST(100, COALESCE(cur.vibrazione, 50) + COALESCE((p_delta->>'vibrazione')::int, 0)));

  -- Compute new archetype
  new_archetype := public.fn_dna_compute_archetype(i, a, e, r, v);

  -- Update DNA profile
  UPDATE public.agent_dna
  SET 
    intuito = i,
    audacia = a,
    etica = e,
    rischio = r,
    vibrazione = v,
    archetype = new_archetype,
    mutated_at = now(),
    updated_at = now()
  WHERE user_id = p_user;

  -- Log the event
  INSERT INTO public.agent_dna_events(user_id, source, delta, note)
  VALUES (p_user, p_source, p_delta, p_note);
END;
$$;


ALTER FUNCTION "public"."fn_dna_apply_delta"("p_user" "uuid", "p_delta" "jsonb", "p_source" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_dna_compute_archetype"("p_i" smallint, "p_a" smallint, "p_e" smallint, "p_r" smallint, "p_v" smallint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_i >= 70 AND p_v >= 70 THEN 'Seeker'
    WHEN p_a >= 65 AND p_r >= 65 THEN 'Breaker'
    WHEN p_i >= 65 AND p_e >= 65 THEN 'Oracle'
    WHEN p_e >= 75 AND p_r < 40 THEN 'Warden'
    ELSE 'Nomad'
  END;
$$;


