CREATE OR REPLACE FUNCTION "public"."force_subscription_sync"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  active_sub RECORD;
  final_tier TEXT := 'Base';
BEGIN
  -- Get most recent active subscription
  SELECT * INTO active_sub
  FROM public.subscriptions
  WHERE user_id = p_user_id 
    AND status = 'active'
    AND (end_date IS NULL OR end_date > now())
  ORDER BY created_at DESC
  LIMIT 1;
  
  -- Determine final tier
  IF active_sub.id IS NOT NULL THEN
    final_tier := active_sub.tier;
  END IF;
  
  -- Developer override
  IF EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id AND email = 'wikus77@hotmail.it') THEN
    final_tier := 'Titanium';
  END IF;
  
  -- Update profile
  UPDATE public.profiles
  SET 
    subscription_tier = final_tier,
    tier = final_tier,
    updated_at = now()
  WHERE id = p_user_id;
  
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."force_subscription_sync"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."force_user_to_base_tier"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
  cleaned_subs INTEGER;
BEGIN
  -- Force cancel ALL subscriptions for user
  UPDATE public.subscriptions 
  SET 
    status = 'canceled',
    updated_at = now()
  WHERE user_id = p_user_id 
    AND status != 'canceled';
  
  GET DIAGNOSTICS cleaned_subs = ROW_COUNT;
  
  -- Force profile to Base (ignore developer override for this function)
  UPDATE public.profiles
  SET 
    subscription_tier = 'Base',
    tier = 'Base',
    updated_at = now()
  WHERE id = p_user_id;
  
  -- Build result
  result := jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'subscriptions_canceled', cleaned_subs,
    'profile_reset', true,
    'timestamp', now()
  );
  
  -- Log the operation
  INSERT INTO public.panel_logs (event_type, details)
  VALUES ('force_base_tier', result);
  
  RETURN result;
END;
$$;


