CREATE OR REPLACE FUNCTION "public"."generate_agent_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_code TEXT;
  code_exists BOOLEAN;
BEGIN
  LOOP
    -- Generate AG-XXXX format with random alphanumeric
    new_code := 'AG-' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 4));
    
    -- Check if code exists in either table
    SELECT EXISTS(
      SELECT 1 FROM public.profiles WHERE agent_code = new_code
      UNION
      SELECT 1 FROM public.pre_registered_users WHERE agent_code = new_code
    ) INTO code_exists;
    
    -- If unique, return the code
    IF NOT code_exists THEN
      RETURN new_code;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_agent_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_qr_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_code TEXT;
  code_exists BOOLEAN;
  attempts INTEGER := 0;
BEGIN
  LOOP
    -- Generate 8-character alphanumeric code
    new_code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT || EXTRACT(EPOCH FROM NOW())::TEXT) FROM 1 FOR 8));
    
    -- Check if code exists
    SELECT EXISTS(SELECT 1 FROM public.qr_buzz_codes WHERE code = new_code) INTO code_exists;
    
    attempts := attempts + 1;
    
    -- If unique or too many attempts, return
    IF NOT code_exists OR attempts >= 50 THEN
      EXIT;
    END IF;
  END LOOP;
  
  RETURN new_code;
END;
$$;


ALTER FUNCTION "public"."generate_qr_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_referral_code"() RETURNS character varying
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_code VARCHAR(10); v_exists BOOLEAN;
BEGIN
  LOOP
    v_code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT) FROM 1 FOR 8));
    SELECT EXISTS(SELECT 1 FROM profiles WHERE referral_code = v_code) INTO v_exists;
    IF NOT v_exists THEN RETURN v_code; END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_referral_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_ticket_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_numbers TEXT;
  v_letter TEXT;
  v_code TEXT;
  v_exists BOOLEAN;
BEGIN
  LOOP
    -- Genera 9 numeri random
    v_numbers := LPAD(FLOOR(RANDOM() * 1000000000)::TEXT, 9, '0');
    
    -- Genera 1 lettera random (A-Z)
    v_letter := CHR(65 + FLOOR(RANDOM() * 26)::INT);
    
    -- Combina
    v_code := v_numbers || v_letter;
    
    -- Verifica unicità
    SELECT EXISTS(SELECT 1 FROM public.lottery_tickets WHERE ticket_code = v_code) INTO v_exists;
    
    IF NOT v_exists THEN
      RETURN v_code;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_ticket_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_agent_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_code TEXT;
  code_exists BOOLEAN;
  attempts INTEGER := 0;
  max_attempts INTEGER := 100;
BEGIN
  LOOP
    -- Genera codice nel formato AGT-XXXXX (5 cifre)
    new_code := 'AGT-' || LPAD(FLOOR(RANDOM() * 100000)::TEXT, 5, '0');
    
    -- Verifica se il codice esiste già
    SELECT EXISTS(
      SELECT 1 FROM public.profiles WHERE agent_code = new_code
    ) INTO code_exists;
    
    -- Incrementa tentativi per evitare loop infiniti
    attempts := attempts + 1;
    
    -- Se il codice è unico o abbiamo raggiunto il massimo dei tentativi, esci
    IF NOT code_exists OR attempts >= max_attempts THEN
      EXIT;
    END IF;
  END LOOP;
  
  RETURN new_code;
END;
$$;


ALTER FUNCTION "public"."generate_unique_agent_code"() OWNER TO "postgres";


