CREATE OR REPLACE FUNCTION "public"."geo_push_upsert_state"("p_user_id" "uuid", "p_marker_id" "uuid", "p_last_enter_at" timestamp with time zone, "p_last_sent_at" timestamp with time zone, "p_enter_inc" integer, "p_sent_inc" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  insert into geo_push.delivery_state(user_id, marker_id, last_enter_at, last_sent_at, enter_count, sent_count)
  values (p_user_id, p_marker_id, p_last_enter_at, p_last_sent_at, coalesce(p_enter_inc,0), coalesce(p_sent_inc,0))
  on conflict (user_id, marker_id) do update
    set last_enter_at = excluded.last_enter_at,
        last_sent_at  = coalesce(excluded.last_sent_at, geo_push.delivery_state.last_sent_at),
        enter_count   = geo_push.delivery_state.enter_count + coalesce(p_enter_inc,0),
        sent_count    = geo_push.delivery_state.sent_count + coalesce(p_sent_inc,0);
end;
$$;


