CREATE OR REPLACE FUNCTION "public"."get_active_subscription"("p_user_id" "uuid") RETURNS TABLE("tier" "text", "status" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.tier,
    s.status,
    s.current_period_end
  FROM public.subscriptions s
  WHERE s.user_id = p_user_id 
    AND s.status = 'active'
    AND (s.current_period_end IS NULL OR s.current_period_end > now())
  ORDER BY s.created_at DESC
  LIMIT 1;
  
  -- Se non trova subscription attiva, ritorna Base
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'Base'::TEXT, 'active'::TEXT, NULL::TIMESTAMPTZ;
  END IF;
END;
$$;


