CREATE OR REPLACE FUNCTION "public"."get_admin_kpi_snapshot"() RETURNS TABLE("active_users_24h" bigint, "active_users_7d" bigint, "anon_users_24h" bigint, "total_events" bigint, "events_24h" bigint, "final_shot_attempts" bigint, "final_shot_wins" bigint, "last_final_winner_id" "uuid", "last_final_win_at" timestamp with time zone, "secondary_prizes_awarded" bigint, "final_prizes_awarded" bigint, "secondary_claims_total" bigint, "final_claims_total" bigint, "marker_rewards_claimed" bigint, "logins_24h" bigint, "signups_24h" bigint, "landing_views_24h" bigint, "spectator_views_24h" bigint, "streak_checkins_24h" bigint, "streak_breaks_24h" bigint, "streak_active_users_7d" bigint, "wheel_spins_24h" bigint, "wheel_rewards_24h" bigint, "wheel_spins_total" bigint, "wheel_m1u_distributed" bigint, "wheel_pe_distributed" bigint, "minigame_runs_24h" bigint, "minigame_completions_24h" bigint, "minigame_abandons_24h" bigint, "minigame_completion_rate_7d" numeric, "last_event_ts" timestamp with time zone, "snapshot_ts" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
