CREATE OR REPLACE FUNCTION "public"."get_agent_dna_visual"("seed" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  uid UUID := auth.uid();
  visual_data JSONB;
  user_str TEXT;
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('targets', jsonb_build_object());
  END IF;

  -- Try to get existing data
  SELECT data INTO visual_data 
  FROM public.agent_dna_visual 
  WHERE user_id = uid;

  -- If no data exists and seed is true, generate deterministic positions
  IF visual_data IS NULL AND seed THEN
    user_str := uid::TEXT;
    
    -- Generate deterministic cell positions [x,y,z] in 4x4x4 grid (0-3 range)
    visual_data := jsonb_build_object(
      'targets', jsonb_build_object(
        'audacia', jsonb_build_object(
          'cell', ARRAY[
            (ascii(substr(user_str, 1, 1)) % 4),
            (ascii(substr(user_str, 2, 1)) % 4),
            (ascii(substr(user_str, 3, 1)) % 4)
          ],
          'level', 1
        ),
        'etica', jsonb_build_object(
          'cell', ARRAY[
            (ascii(substr(user_str, 4, 1)) % 4),
            (ascii(substr(user_str, 5, 1)) % 4),
            (ascii(substr(user_str, 6, 1)) % 4)
          ],
          'level', 1
        ),
        'rischio', jsonb_build_object(
          'cell', ARRAY[
            (ascii(substr(user_str, 7, 1)) % 4),
            (ascii(substr(user_str, 8, 1)) % 4),
            (ascii(substr(user_str, 9, 1)) % 4)
          ],
          'level', 1
        ),
        'intuito', jsonb_build_object(
          'cell', ARRAY[
            (ascii(substr(user_str, 10, 1)) % 4),
            (ascii(substr(user_str, 11, 1)) % 4),
            (ascii(substr(user_str, 12, 1)) % 4)
          ],
          'level', 1
        ),
        'vibrazione', jsonb_build_object(
          'cell', ARRAY[
            (ascii(substr(user_str, 13, 1)) % 4),
            (ascii(substr(user_str, 14, 1)) % 4),
            (ascii(substr(user_str, 15, 1)) % 4)
          ],
          'level', 1
        )
      )
    );

    -- Store the generated data
    INSERT INTO public.agent_dna_visual(user_id, data)
    VALUES (uid, visual_data)
    ON CONFLICT (user_id) DO UPDATE SET data = EXCLUDED.data;
  END IF;

  RETURN COALESCE(visual_data, jsonb_build_object('targets', jsonb_build_object()));
END;
$$;


ALTER FUNCTION "public"."get_agent_dna_visual"("seed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_agent_dna_visual"("user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_dna_row agent_dna%ROWTYPE;
  v_seed text;
  v_result jsonb;
BEGIN
  -- Security check
  IF auth.uid() != user_id THEN
    RAISE EXCEPTION 'Unauthorized access to DNA data';
  END IF;

  -- Get DNA scores
  SELECT * INTO v_dna_row
  FROM public.agent_dna
  WHERE agent_dna.user_id = get_agent_dna_visual.user_id
  LIMIT 1;

  -- Generate stable seed for visual jitter
  v_seed := encode(digest(user_id::text || 'DNA-VIS-1', 'sha256'), 'hex');

  -- Build result with COALESCE fallback to 50
  v_result := jsonb_build_object(
    'dna', jsonb_build_object(
      'intuito', COALESCE(v_dna_row.intuito, 50),
      'audacia', COALESCE(v_dna_row.audacia, 50),
      'etica', COALESCE(v_dna_row.etica, 50),
      'rischio', COALESCE(v_dna_row.rischio, 50),
      'vibrazione', COALESCE(v_dna_row.vibrazione, 50)
    ),
    'targets', jsonb_build_object(
      'ETICA', jsonb_build_object('x', -1, 'y', 1, 'z', 0),
      'INTUITO', jsonb_build_object('x', 0, 'y', 1, 'z', 1),
      'AUDACIA', jsonb_build_object('x', 1, 'y', 0, 'z', -1),
      'VIBRAZIONE', jsonb_build_object('x', -1, 'y', -1, 'z', 1),
      'RISCHIO', jsonb_build_object('x', 1, 'y', -1, 'z', 0)
    ),
    'seed', v_seed
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_agent_dna_visual"("user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_agent_dna_visual"("user_id" "uuid") IS 'Returns DNA profile with target coordinates and visual seed for tesseract renderer. Security: user can only access their own data.';



CREATE OR REPLACE FUNCTION "public"."get_aion_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_plan TEXT;
  v_m1u_balance INTEGER;
  v_free_weekly_slots INTEGER;
  v_cost_after_free INTEGER;
  v_daily_cap INTEGER;
  v_free_uses_this_week INTEGER;
  v_daily_uses_today INTEGER;
  v_current_week_start DATE;
  v_remaining_free INTEGER;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'NOT_AUTHENTICATED');
  END IF;

  v_current_week_start := CURRENT_DATE - EXTRACT(DOW FROM CURRENT_DATE)::INTEGER + 1;

  -- Get user info
  SELECT COALESCE(UPPER(subscription_plan), 'FREE'), COALESCE(m1_units, 0)
  INTO v_plan, v_m1u_balance
  FROM public.profiles WHERE id = v_user_id;

  IF v_plan NOT IN ('FREE', 'SILVER', 'GOLD', 'BLACK', 'TITANIUM') THEN
    v_plan := 'FREE';
  END IF;

  -- Get plan config
  SELECT free_weekly_slots, cost_after_free, daily_cap
  INTO v_free_weekly_slots, v_cost_after_free, v_daily_cap
  FROM public.aion_plan_config WHERE plan = v_plan;

  -- Get state
  SELECT 
    CASE WHEN week_start_date < v_current_week_start THEN 0 ELSE free_uses_this_week END,
    CASE WHEN last_use_date < CURRENT_DATE THEN 0 ELSE daily_uses_today END
  INTO v_free_uses_this_week, v_daily_uses_today
  FROM public.user_aion_state WHERE user_id = v_user_id;

  IF NOT FOUND THEN
    v_free_uses_this_week := 0;
    v_daily_uses_today := 0;
  END IF;

  v_remaining_free := GREATEST(0, COALESCE(v_free_weekly_slots, 0) - v_free_uses_this_week);

  RETURN jsonb_build_object(
    'plan', v_plan,
    'm1u_balance', v_m1u_balance,
    'free_weekly_slots', COALESCE(v_free_weekly_slots, 0),
    'free_remaining', v_remaining_free,
    'cost_per_consult', CASE WHEN v_remaining_free > 0 THEN 0 ELSE COALESCE(v_cost_after_free, 2) END,
    'daily_uses', v_daily_uses_today,
    'daily_cap', v_daily_cap
  );
END;
$$;


