CREATE OR REPLACE FUNCTION "public"."get_buzz_override"() RETURNS TABLE("cooldown_disabled" boolean, "free_remaining" integer, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_cooldown boolean := false;
  v_free_quota int := 0;
  v_free_used int := 0;
  v_expires timestamptz := null;
begin
  if v_uid is null then
    return query select false::boolean, 0::int, null::timestamptz;
    return;
  end if;

  select o.cooldown_disabled, o.free_quota, o.free_used, o.expires_at
    into v_cooldown, v_free_quota, v_free_used, v_expires
  from public.admin_buzz_overrides o
  where o.user_id = v_uid
    and (o.expires_at is null or o.expires_at > now())
  limit 1;

  if not found then
    return query select false::boolean, 0::int, null::timestamptz;
  else
    return query
      select v_cooldown,
             greatest(v_free_quota - v_free_used, 0),
             v_expires;
  end if;
end
$$;


