CREATE OR REPLACE FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "conversation_id" "uuid", "sender_id" "uuid", "content" "text", "created_at" timestamp with time zone, "sender_username" "text", "sender_avatar" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    m.id,
    m.conversation_id,
    m.sender_id,
    COALESCE(
      pgp_sym_decrypt(m.content_encrypted, 'm1ssion_chat_key_2025')::TEXT,
      '[Messaggio]'
    ) as content,
    m.created_at,
    p.username as sender_username,
    p.avatar_url as sender_avatar
  FROM chat_messages m
  LEFT JOIN profiles p ON p.id = m.sender_id
  WHERE m.conversation_id = p_conversation_id
  ORDER BY m.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_username" "text", "sender_avatar" "text", "content" "text", "message_type" "text", "metadata" "jsonb", "created_at" timestamp with time zone, "is_own" boolean, "read_by" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT m.id, m.sender_id, COALESCE(p.full_name, p.username, p.agent_code, 'Agente'),
    p.avatar_url, decrypt_chat_message(m.content_encrypted), m.message_type::TEXT,
    m.metadata, m.created_at, (m.sender_id = auth.uid()), COALESCE(m.read_by, '{}')
  FROM chat_messages m JOIN profiles p ON p.id = m.sender_id
  WHERE m.conversation_id = p_conversation_id AND m.deleted_at IS NULL
    AND (p_before IS NULL OR m.created_at < p_before)
  ORDER BY m.created_at DESC LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_username" "text", "sender_avatar" "text", "content" "text", "message_type" "text", "metadata" "jsonb", "created_at" timestamp with time zone, "is_own" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_user_id UUID;
  v_is_member BOOLEAN;
BEGIN
  v_current_user_id := auth.uid();
  IF v_current_user_id IS NULL THEN
    RETURN;
  END IF;
  
  SELECT EXISTS(
    SELECT 1 FROM chat_members WHERE conversation_id = p_conversation_id AND user_id = v_current_user_id
  ) INTO v_is_member;
  
  IF NOT v_is_member THEN
    RETURN;
  END IF;
  
  UPDATE chat_members SET last_read_at = NOW() 
  WHERE conversation_id = p_conversation_id AND user_id = v_current_user_id;
  
  RETURN QUERY
  SELECT 
    m.id AS message_id,
    m.sender_id,
    -- ✅ FIX: Use COALESCE for fallback display name
    COALESCE(p.full_name, p.username, p.agent_code, 'Agente') AS sender_username,
    p.avatar_url AS sender_avatar,
    decrypt_chat_message(m.content_encrypted) AS content,
    m.message_type,
    m.metadata,
    m.created_at,
    (m.sender_id = v_current_user_id) AS is_own
  FROM chat_messages m
  JOIN profiles p ON p.id = m.sender_id
  WHERE m.conversation_id = p_conversation_id
    AND m.deleted_at IS NULL
    AND (p_before IS NULL OR m.created_at < p_before)
  ORDER BY m.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_chat_messages"("p_conversation_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


