CREATE OR REPLACE FUNCTION "public"."get_clue_meta_v2"("p_buzz_index" integer, "p_total" integer DEFAULT 500) RETURNS TABLE("week" smallint, "tier" smallint, "decoy_rate" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH slot AS (
    SELECT (public.compute_clue_slot_v2(p_buzz_index, p_total)).*
  )
  SELECT
    s.week,
    s.tier,
    m.decoy_rate
  FROM slot s
  JOIN public.clue_progression_matrix m
    ON m.week = s.week AND m.tier = s.tier;
$$;


