ALTER FUNCTION "public"."get_country_code_from_coords"("p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_country_domination_state"() RETURNS TABLE("country_code" character, "owner_id" "uuid", "owner_name" "text", "owner_agent_code" "text", "win_progress" integer, "conquest_threshold" integer, "status" "text", "conquered_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    cd.country_code,
    cd.owner_id,
    COALESCE(p.full_name, p.nickname, p.agent_code, 'Agent') as owner_name,
    p.agent_code as owner_agent_code,
    cd.win_progress,
    cd.conquest_threshold,
    cd.status,
    cd.conquered_at
  FROM country_domination cd
  LEFT JOIN profiles p ON p.id = cd.owner_id
  WHERE cd.status IN ('contested', 'conquered')
  ORDER BY cd.status DESC, cd.win_progress DESC;
END;
$$;


ALTER FUNCTION "public"."get_country_domination_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_buzz_price"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_count INTEGER;
  current_price NUMERIC;
BEGIN
  SELECT COALESCE(buzz_count, 0) INTO current_count
  FROM public.user_buzz_counter
  WHERE user_id = p_user_id AND date = CURRENT_DATE;
  
  IF current_count IS NULL THEN current_count := 0; END IF;
  current_price := public.calculate_buzz_price(current_count);
  RETURN current_price;
END;
$$;


ALTER FUNCTION "public"."get_current_buzz_price"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_game_week"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  game_start_date DATE := '2025-01-20'::DATE; -- Fixed start date for M1SSION™
  current_week INTEGER;
BEGIN
  -- Calculate weeks since game start (1-indexed)
  current_week := CEIL((CURRENT_DATE - game_start_date) / 7.0);
  
  -- Ensure we're in a valid range (1-4, cycle repeats)
  current_week := ((current_week - 1) % 4) + 1;
  
  RETURN current_week;
END;
$$;


ALTER FUNCTION "public"."get_current_game_week"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_mission_week"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  mission_start_date DATE;
  current_week INTEGER;
BEGIN
  -- Ottieni la data di inizio missione (assumo che sia nella tabella missions)
  SELECT MIN(publication_date)::DATE INTO mission_start_date 
  FROM public.missions WHERE status = 'active';
  
  -- Se non c'è una missione attiva, restituisci 1 come default
  IF mission_start_date IS NULL THEN
    RETURN 1;
  END IF;
  
  -- Calcola la settimana corrente (arrotondata per eccesso)
  current_week := CEIL((CURRENT_DATE - mission_start_date) / 7.0);
  
  -- Minimo settimana 1
  RETURN GREATEST(1, current_week);
END;
$$;


