CREATE OR REPLACE FUNCTION "public"."get_leaderboard"("p_scope" "text" DEFAULT 'global'::"text", "p_filter_value" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "agent_code" "text", "full_name" "text", "avatar_url" "text", "city" "text", "region" "text", "country" "text", "subscription_plan" "text", "streak_days" integer, "pulse_energy" integer, "m1_units" integer, "clues_unlocked" bigint, "buzz_used" bigint, "total_score" bigint, "rank" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  WITH user_stats AS (
    SELECT 
      p.id,
      p.agent_code,
      p.full_name,
      p.avatar_url,
      p.city,
      p.region,
      p.country,
      p.subscription_plan,
      COALESCE(p.current_streak_days, 0) as streak_days,
      COALESCE(p.pulse_energy, 0) as pulse_energy,
      COALESCE(p.m1_units, 0) as m1_units,
      COALESCE(uc.clues_count, 0) as clues_unlocked,
      COALESCE(bc.buzz_total, 0) as buzz_used,
      (
        COALESCE(p.pulse_energy, 0) * 2 +
        COALESCE(uc.clues_count, 0) * 10 +
        COALESCE(bc.buzz_total, 0) * 5 +
        COALESCE(p.current_streak_days, 0) * 3
      ) as total_score
    FROM public.profiles p
    LEFT JOIN (
      SELECT user_id, COUNT(*)::BIGINT as clues_count 
      FROM public.user_clues 
      GROUP BY user_id
    ) uc ON p.id = uc.user_id
    LEFT JOIN (
      SELECT user_id, SUM(COALESCE(buzz_count, 0))::BIGINT as buzz_total 
      FROM public.user_buzz_counter 
      GROUP BY user_id
    ) bc ON p.id = bc.user_id
    WHERE p.agent_code IS NOT NULL
  )
  SELECT 
    us.id,
    us.agent_code,
    us.full_name,
    us.avatar_url,
    us.city,
    us.region,
    us.country,
    us.subscription_plan,
    us.streak_days::INTEGER,
    us.pulse_energy::INTEGER,
    us.m1_units::INTEGER,
    us.clues_unlocked,
    us.buzz_used,
    us.total_score,
    ROW_NUMBER() OVER (ORDER BY us.total_score DESC) as rank
  FROM user_stats us
  WHERE 
    CASE 
      WHEN p_scope = 'city' AND p_filter_value IS NOT NULL THEN us.city = p_filter_value
      WHEN p_scope = 'region' AND p_filter_value IS NOT NULL THEN us.region = p_filter_value
      WHEN p_scope = 'country' AND p_filter_value IS NOT NULL THEN us.country = p_filter_value
      ELSE TRUE
    END
  ORDER BY us.total_score DESC
  LIMIT p_limit;
END;
$$;


