COMMENT ON FUNCTION "public"."get_lottery_status"("p_cycle_id" "uuid") IS 'M1SSION™ Lottery - Status completo ciclo con statistiche utente.';



CREATE OR REPLACE FUNCTION "public"."get_map_radius_km"("p_week" integer, "p_generation_count" integer) RETURNS double precision
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  CASE p_week
    WHEN 1 THEN
      CASE p_generation_count
        WHEN 1 THEN RETURN 500.0;
        WHEN 2 THEN RETURN 400.0;
        ELSE RETURN 500.0;
      END CASE;
    WHEN 2 THEN
      CASE p_generation_count
        WHEN 1 THEN RETURN 350.0;
        WHEN 2 THEN RETURN 300.0;
        WHEN 3 THEN RETURN 250.0;
        ELSE RETURN 300.0;
      END CASE;
    WHEN 3 THEN
      CASE p_generation_count
        WHEN 1 THEN RETURN 250.0;
        WHEN 2 THEN RETURN 200.0;
        WHEN 3 THEN RETURN 150.0;
        ELSE RETURN 200.0;
      END CASE;
    WHEN 4 THEN
      CASE p_generation_count
        WHEN 1 THEN RETURN 100.0;
        WHEN 2 THEN RETURN 50.0;
        WHEN 3 THEN RETURN 15.0;
        WHEN 4 THEN RETURN 5.0;
        ELSE RETURN 25.0;
      END CASE;
    ELSE
      RETURN 10.0; -- Default per settimane > 4
  END CASE;
END;
$$;


