CREATE OR REPLACE FUNCTION "public"."get_my_balance"() RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
with
r as (
  select reward_type, reward_value, redeemed_at
  from public.qr_redemptions
  where user_id = auth.uid()
),
bytype as (
  select reward_type, sum(reward_value) as total
  from r
  group by reward_type
),
agg as (
  select
    sum(case when reward_type = 'buzz_credit'     then reward_value else 0 end)::int as buzz_credit,
    sum(case when reward_type = 'buzz_map_credit' then reward_value else 0 end)::int as buzz_map_credit,
    max(redeemed_at) as last_activity
  from r
)
select jsonb_build_object(
  'user_id',         auth.uid(),
  'buzz_credit',     coalesce(agg.buzz_credit, 0),
  'buzz_map_credit', coalesce(agg.buzz_map_credit, 0),
  -- mappa generica per TUTTI i tipi (anche futuri)
  'by_type',         coalesce(
                       (select jsonb_object_agg(bt.reward_type, bt.total) from bytype bt),
                       '{}'::jsonb
                     ),
  'updated_at',      coalesce(agg.last_activity, now())
)
from agg;
$$;


