CREATE OR REPLACE FUNCTION "public"."get_my_conversations"() RETURNS TABLE("conversation_id" "uuid", "conversation_type" "text", "conversation_name" "text", "other_user_id" "uuid", "other_user_username" "text", "other_user_avatar" "text", "last_message" "text", "last_message_at" timestamp with time zone, "last_message_sender_id" "uuid", "unread_count" bigint, "is_muted" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_user_id UUID;
BEGIN
  v_current_user_id := auth.uid();
  IF v_current_user_id IS NULL THEN
    RETURN;
  END IF;
  
  RETURN QUERY
  SELECT 
    c.id AS conversation_id,
    c.type AS conversation_type,
    c.name AS conversation_name,
    CASE WHEN c.type = 'direct' THEN (
      SELECT cm2.user_id FROM chat_members cm2 
      WHERE cm2.conversation_id = c.id AND cm2.user_id != v_current_user_id
      LIMIT 1
    ) ELSE NULL END AS other_user_id,
    CASE WHEN c.type = 'direct' THEN (
      SELECT COALESCE(p.full_name, p.username, p.agent_code, 'Agente') 
      FROM chat_members cm2 
      JOIN profiles p ON p.id = cm2.user_id
      WHERE cm2.conversation_id = c.id AND cm2.user_id != v_current_user_id
      LIMIT 1
    ) ELSE c.name END AS other_user_username,
    CASE WHEN c.type = 'direct' THEN (
      SELECT p.avatar_url FROM chat_members cm2 
      JOIN profiles p ON p.id = cm2.user_id
      WHERE cm2.conversation_id = c.id AND cm2.user_id != v_current_user_id
      LIMIT 1
    ) ELSE NULL END AS other_user_avatar,
    (SELECT decrypt_chat_message(m.content_encrypted) 
     FROM chat_messages m 
     WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
     ORDER BY m.created_at DESC LIMIT 1) AS last_message,
    (SELECT m.created_at
     FROM chat_messages m 
     WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
     ORDER BY m.created_at DESC LIMIT 1) AS last_message_at,
    (SELECT m.sender_id
     FROM chat_messages m 
     WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
     ORDER BY m.created_at DESC LIMIT 1) AS last_message_sender_id,
    (SELECT COUNT(*)::BIGINT
     FROM chat_messages m
     WHERE m.conversation_id = c.id 
       AND m.deleted_at IS NULL
       AND m.created_at > COALESCE(cm.last_read_at, '1970-01-01'::timestamptz)
       AND m.sender_id != v_current_user_id) AS unread_count,
    cm.muted AS is_muted
  FROM chat_conversations c
  JOIN chat_members cm ON cm.conversation_id = c.id AND cm.user_id = v_current_user_id
  ORDER BY last_message_at DESC NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_my_conversations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_lottery_wins"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_wins JSONB;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Non autenticato');
  END IF;
  
  SELECT jsonb_agg(jsonb_build_object(
    'id', lw.id,
    'cycle_id', lw.cycle_id,
    'rank', lw.rank,
    'prize_m1u', lw.prize_m1u,
    'prize_label', lw.prize_label,
    'claim_status', lw.claim_status,
    'claim_deadline', lw.claim_deadline,
    'claimed_at', lw.claimed_at,
    'time_remaining_seconds', GREATEST(0, EXTRACT(EPOCH FROM (lw.claim_deadline - now()))::int),
    'created_at', lw.created_at
  ) ORDER BY lw.created_at DESC)
  INTO v_wins
  FROM public.lottery_winners lw
  WHERE lw.user_id = v_user_id;
  
  RETURN jsonb_build_object(
    'status', 'success',
    'wins', COALESCE(v_wins, '[]'::jsonb),
    'pending_count', (
      SELECT COUNT(*) FROM public.lottery_winners 
      WHERE user_id = v_user_id AND claim_status = 'pending'
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_my_lottery_wins"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_direct_chat"("p_other_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_user_id UUID;
  v_conversation_id UUID;
BEGIN
  v_current_user_id := auth.uid();
  IF v_current_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Permetti self-chat per testing
  -- Check if direct conversation already exists
  SELECT c.id INTO v_conversation_id
  FROM chat_conversations c
  WHERE c.type = 'direct'
    AND EXISTS (SELECT 1 FROM chat_members WHERE conversation_id = c.id AND user_id = v_current_user_id)
    AND EXISTS (SELECT 1 FROM chat_members WHERE conversation_id = c.id AND user_id = p_other_user_id);
  
  IF v_conversation_id IS NOT NULL THEN
    RETURN v_conversation_id;
  END IF;
  
  -- Create new conversation
  INSERT INTO chat_conversations (type) VALUES ('direct') RETURNING id INTO v_conversation_id;
  
  -- Add members
  IF v_current_user_id = p_other_user_id THEN
    -- Self-chat: solo un membro
    INSERT INTO chat_members (conversation_id, user_id, role) VALUES 
      (v_conversation_id, v_current_user_id, 'member');
  ELSE
    INSERT INTO chat_members (conversation_id, user_id, role) VALUES 
      (v_conversation_id, v_current_user_id, 'member'),
      (v_conversation_id, p_other_user_id, 'member');
  END IF;
  
  RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_direct_chat"("p_other_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pe_daily_stats"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today_total INTEGER;
  v_actions_breakdown JSONB;
BEGIN
  -- Totale PE oggi
  SELECT COALESCE(SUM(pe_awarded), 0)
  INTO v_today_total
  FROM pe_daily_awards
  WHERE user_id = p_user_id
    AND award_date = CURRENT_DATE;

  -- Breakdown per azione
  SELECT COALESCE(
    jsonb_object_agg(action_type, count),
    '{}'::jsonb
  )
  INTO v_actions_breakdown
  FROM (
    SELECT action_type, COUNT(*) as count
    FROM pe_daily_awards
    WHERE user_id = p_user_id
      AND award_date = CURRENT_DATE
    GROUP BY action_type
  ) t;

  RETURN jsonb_build_object(
    'user_id', p_user_id,
    'date', CURRENT_DATE,
    'total_pe_today', v_today_total,
    'actions_breakdown', v_actions_breakdown
  );
END;
$$;


