CREATE OR REPLACE FUNCTION "public"."get_user_sync_status"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  result JSONB;
  profile_data RECORD;
  permissions_data JSONB;
  recent_logs JSONB;
BEGIN
  -- Get profile data
  SELECT * INTO profile_data
  FROM public.profiles
  WHERE id = p_user_id;
  
  -- Get permissions
  SELECT jsonb_agg(
    jsonb_build_object(
      'type', permission_type,
      'value', permission_value,
      'granted_at', granted_at
    )
  ) INTO permissions_data
  FROM public.user_permissions
  WHERE user_id = p_user_id;
  
  -- Get recent logs (last 10)
  SELECT jsonb_agg(
    jsonb_build_object(
      'action', action,
      'details', details,
      'created_at', created_at
    )
  ) INTO recent_logs
  FROM (
    SELECT action, details, created_at
    FROM public.user_logs
    WHERE user_id = p_user_id
    ORDER BY created_at DESC
    LIMIT 10
  ) recent;
  
  -- Build result
  result := jsonb_build_object(
    'user_id', p_user_id,
    'plan', profile_data.plan,
    'can_access_app', profile_data.can_access_app,
    'early_access_hours', profile_data.early_access_hours,
    'last_plan_change', profile_data.last_plan_change,
    'permissions', COALESCE(permissions_data, '[]'::jsonb),
    'recent_logs', COALESCE(recent_logs, '[]'::jsonb),
    'sync_timestamp', NOW()
  );
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_user_sync_status"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_weekly_buzz_status"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  week_start DATE;
  current_week INTEGER;
  max_allowed INTEGER;
  user_record RECORD;
  next_reset TIMESTAMP WITH TIME ZONE;
BEGIN
  -- Get current week info
  week_start := public.get_week_start_date();
  current_week := public.get_current_game_week();
  max_allowed := public.get_max_buzz_for_week(current_week);
  next_reset := (week_start + INTERVAL '7 days')::TIMESTAMP WITH TIME ZONE;
  
  -- Get user's current weekly record
  SELECT * INTO user_record
  FROM public.user_weekly_buzz_limits
  WHERE user_id = p_user_id AND week_start_date = week_start;
  
  -- If no record, user hasn't used any buzzes this week
  IF user_record IS NULL THEN
    RETURN jsonb_build_object(
      'buzz_count', 0,
      'max_allowed', max_allowed,
      'week_number', current_week,
      'next_reset', next_reset,
      'remaining', max_allowed,
      'can_buzz', TRUE,
      'week_start', week_start
    );
  END IF;
  
  -- Return current status
  RETURN jsonb_build_object(
    'buzz_count', user_record.buzz_map_count,
    'max_allowed', user_record.max_buzz_map_allowed,
    'week_number', user_record.week_number,
    'next_reset', user_record.next_reset_at,
    'remaining', user_record.max_buzz_map_allowed - user_record.buzz_map_count,
    'can_buzz', user_record.buzz_map_count < user_record.max_buzz_map_allowed,
    'week_start', week_start,
    'last_buzz_at', user_record.last_buzz_at
  );
END;
$$;


