CREATE OR REPLACE FUNCTION "public"."get_week_start"("p_date" "date" DEFAULT CURRENT_DATE) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT p_date - EXTRACT(DOW FROM p_date)::INTEGER + 1;
$$;


ALTER FUNCTION "public"."get_week_start"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_week_start_date"() RETURNS "date"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  current_day_of_week INTEGER;
  week_start DATE;
BEGIN
  -- Get day of week (1=Monday, 7=Sunday)
  current_day_of_week := EXTRACT(DOW FROM CURRENT_DATE);
  -- Adjust for PostgreSQL DOW (0=Sunday)
  IF current_day_of_week = 0 THEN
    current_day_of_week := 7;
  END IF;
  
  -- Calculate Monday of current week
  week_start := CURRENT_DATE - (current_day_of_week - 1);
  
  RETURN week_start;
END;
$$;


ALTER FUNCTION "public"."get_week_start_date"() OWNER TO "postgres";


