CREATE OR REPLACE FUNCTION "public"."grant_subscription_entitlement"("p_user_id" "uuid", "p_tier" "text", "p_platform" "text", "p_expires_at" timestamp with time zone, "p_original_transaction_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Validate tier
    IF p_tier NOT IN ('silver', 'gold', 'black', 'titanium') THEN
        RAISE EXCEPTION 'Invalid subscription tier: %', p_tier;
    END IF;
    
    -- Upsert entitlements
    INSERT INTO user_entitlements (
        user_id, 
        sub_tier, 
        sub_status, 
        sub_expires_at, 
        sub_platform, 
        original_transaction_id,
        updated_at
    )
    VALUES (
        p_user_id, 
        p_tier, 
        'active', 
        p_expires_at, 
        p_platform, 
        p_original_transaction_id,
        now()
    )
    ON CONFLICT (user_id) DO UPDATE SET
        sub_tier = EXCLUDED.sub_tier,
        sub_status = EXCLUDED.sub_status,
        sub_expires_at = EXCLUDED.sub_expires_at,
        sub_platform = EXCLUDED.sub_platform,
        original_transaction_id = COALESCE(EXCLUDED.original_transaction_id, user_entitlements.original_transaction_id),
        updated_at = now();
    
    -- Update profiles
    UPDATE profiles
    SET 
        subscription_tier = p_tier,
        updated_at = now()
    WHERE id = p_user_id;
    
    -- Return updated entitlements
    SELECT jsonb_build_object(
        'sub_tier', sub_tier,
        'sub_status', sub_status,
        'sub_expires_at', sub_expires_at,
        'sub_platform', sub_platform,
        'is_active', true
    ) INTO v_result
    FROM user_entitlements
    WHERE user_id = p_user_id;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."grant_subscription_entitlement"("p_user_id" "uuid", "p_tier" "text", "p_platform" "text", "p_expires_at" timestamp with time zone, "p_original_transaction_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grant_subscription_entitlement"("p_user_id" "uuid", "p_tier" "text", "p_platform" "text", "p_expires_at" timestamp with time zone, "p_original_transaction_id" "text") IS 'Grant subscription tier to user';



