CREATE OR REPLACE FUNCTION "public"."handle_join_request"("p_request_id" "uuid", "p_conversation_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_user_id UUID;
  v_requester_id UUID;
  v_is_admin BOOLEAN;
BEGIN
  v_current_user_id := auth.uid();
  
  SELECT EXISTS(
    SELECT 1 FROM chat_members 
    WHERE conversation_id = p_conversation_id 
    AND user_id = v_current_user_id 
    AND role IN ('owner', 'admin')
  ) INTO v_is_admin;
  
  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'Only owner or admin can handle join requests';
  END IF;
  
  SELECT user_id INTO v_requester_id
  FROM chat_join_requests
  WHERE id = p_request_id;
  
  IF p_action = 'approve' THEN
    INSERT INTO chat_members (conversation_id, user_id, role)
    VALUES (p_conversation_id, v_requester_id, 'member')
    ON CONFLICT DO NOTHING;
    
    UPDATE chat_join_requests
    SET status = 'approved', handled_at = NOW(), handled_by = v_current_user_id
    WHERE id = p_request_id;
  ELSE
    UPDATE chat_join_requests
    SET status = 'rejected', handled_at = NOW(), handled_by = v_current_user_id
    WHERE id = p_request_id;
  END IF;
  
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."handle_join_request"("p_request_id" "uuid", "p_conversation_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Log per debug
  RAISE LOG 'TRIGGER FIRED: Creando profilo per utente % con email %', NEW.id, NEW.email;
  
  -- Inserisce automaticamente un profilo per ogni nuovo utente auth
  INSERT INTO public.profiles (
    id,
    email,
    agent_code,
    plan,
    credits,
    can_access_app,
    is_pre_registered,
    created_at,
    updated_at
  ) VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'agent_code', public.generate_agent_code()),
    COALESCE(NEW.raw_user_meta_data->>'plan', 'base'),
    COALESCE((NEW.raw_user_meta_data->>'credits')::integer, 100),
    COALESCE((NEW.raw_user_meta_data->>'can_access_app')::boolean, false),
    COALESCE((NEW.raw_user_meta_data->>'is_pre_registered')::boolean, true),
    now(),
    now()
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    agent_code = COALESCE(EXCLUDED.agent_code, profiles.agent_code),
    plan = COALESCE(EXCLUDED.plan, profiles.plan),
    credits = COALESCE(EXCLUDED.credits, profiles.credits),
    can_access_app = COALESCE(EXCLUDED.can_access_app, profiles.can_access_app),
    is_pre_registered = COALESCE(EXCLUDED.is_pre_registered, profiles.is_pre_registered),
    updated_at = now();
    
  RAISE LOG 'TRIGGER SUCCESS: Profilo creato/aggiornato per utente %', NEW.id;
  RETURN NEW;
END;
$$;


