      NEW.inviter_id, 
      25, 
      'referral', 
      jsonb_build_object(
        'ref_user_id', NEW.user_id, 
        'status', NEW.status
      )
    );
    PERFORM public.award_xp(NEW.inviter_id, 25, 'referral'); -- retro-compat
  END IF;
  RETURN NEW;
END;
