CREATE OR REPLACE FUNCTION "public"."haversine_m"("lat1" double precision, "lon1" double precision, "lat2" double precision, "lon2" double precision) RETURNS double precision
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    R CONSTANT DOUBLE PRECISION := 6371000; -- Earth's radius in meters
    dLat DOUBLE PRECISION;
    dLon DOUBLE PRECISION;
    a DOUBLE PRECISION;
    c DOUBLE PRECISION;
BEGIN
    dLat := radians(lat2 - lat1);
    dLon := radians(lon2 - lon1);
    a := sin(dLat/2) * sin(dLat/2) + cos(radians(lat1)) * cos(radians(lat2)) * sin(dLon/2) * sin(dLon/2);
    c := 2 * atan2(sqrt(a), sqrt(1-a));
    RETURN R * c;
END;
$$;


ALTER FUNCTION "public"."haversine_m"("lat1" double precision, "lon1" double precision, "lat2" double precision, "lon2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inc_buzz_today"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  d date := (now() AT TIME ZONE 'Europe/Rome')::date;
  new_count integer;
BEGIN
  INSERT INTO public.user_buzz_map_counter (user_id, "date", buzz_map_count, week_map_counts)
  VALUES (p_user_id, d, 1, ARRAY[0,0,0,0,0,0,0])
  ON CONFLICT (user_id, "date")
  DO UPDATE SET buzz_map_count = public.user_buzz_map_counter.buzz_map_count + 1
  RETURNING buzz_map_count INTO new_count;

  RETURN new_count;
END;
$$;


