CREATE OR REPLACE FUNCTION "public"."interest_track"("payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  u uuid := (payload->>'user_id')::uuid;
  s uuid := (payload->>'session_id')::uuid;
  evs jsonb := payload->'events';
  e jsonb;
BEGIN
  -- Validate payload
  IF u IS NULL OR s IS NULL OR evs IS NULL THEN
    RAISE EXCEPTION 'invalid payload';
  END IF;

  -- Verify user is authenticated and matches
  IF auth.uid() != u THEN
    RAISE EXCEPTION 'unauthorized user_id';
  END IF;

  -- Insert events
  FOR e IN SELECT * FROM jsonb_array_elements(evs)
  LOOP
    INSERT INTO public.interest_signals(user_id, session_id, ts, type, section, category, meta, device, keywords)
    VALUES (
      u, s,
      COALESCE((e->>'ts')::timestamptz, now()),
      e->>'type',
      e->>'section',
      e->>'category',
      COALESCE(e->'meta','{}'::jsonb),
      e->>'device',
      COALESCE(string_to_array(COALESCE(e->>'keywords',''), ',')::text[], '{}')
    );
  END LOOP;
END $$;


ALTER FUNCTION "public"."interest_track"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invoke_auto_push_cron"("p_body" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  request_id bigint;
  v_cron_secret text;
  v_url text := 'https://vkjrqirvdvjbemsfzxof.supabase.co/functions/v1/auto-push-cron';
BEGIN
  SELECT cron_secret INTO v_cron_secret FROM auto_push_config LIMIT 1;

  IF v_cron_secret IS NULL OR v_cron_secret = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'CRON_SECRET non configurato');
  END IF;

  SELECT net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', v_cron_secret
    ),
    body := COALESCE(p_body, jsonb_build_object('trigger', 'cron', 'dryRun', false))
  ) INTO request_id;

  RETURN jsonb_build_object('success', true, 'request_id', request_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."invoke_auto_push_cron"("p_body" "jsonb") OWNER TO "postgres";


