CREATE OR REPLACE FUNCTION "public"."is_final_shoot_available"("p_mission_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  mission_end_date TIMESTAMP WITH TIME ZONE;
  days_remaining INTEGER;
BEGIN
  -- 🔧 FIX: Read from current_mission_data (single source of truth)
  SELECT mission_ends_at INTO mission_end_date
  FROM public.current_mission_data
  WHERE is_active = true
    AND (linked_mission_id = p_mission_id OR id = p_mission_id)
  ORDER BY created_at DESC
  LIMIT 1;
  
  IF mission_end_date IS NULL THEN
    RETURN FALSE;
  END IF;
  
  days_remaining := EXTRACT(DAY FROM (mission_end_date - now()));
  
  -- Final Shoot disponibile solo negli ultimi 7 giorni
  RETURN days_remaining <= 7 AND days_remaining >= 0;
END;
$$;


