CREATE OR REPLACE FUNCTION "public"."log_battle_result"("p_user_id" "uuid", "p_opponent_id" "text", "p_lat" double precision, "p_lng" double precision, "p_is_pvp" boolean DEFAULT false, "p_won" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_country_code CHAR(2); v_battle_id UUID; v_country_name TEXT; v_user_id UUID;
  v_threshold INTEGER; v_current_owner UUID; v_new_status TEXT;
  v_top_winner_id UUID; v_top_winner_wins INTEGER; v_user_wins INTEGER;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  
  v_battle_id := gen_random_uuid();
  v_country_code := get_country_code_from_coords(COALESCE(p_lat, 0), COALESCE(p_lng, 0));
  IF v_country_code IS NULL OR v_country_code = '' THEN v_country_code := 'XX'; END IF;
  
  v_country_name := CASE v_country_code
    WHEN 'IT' THEN 'Italia' WHEN 'FR' THEN 'Francia' WHEN 'DE' THEN 'Germania'
    WHEN 'ES' THEN 'Spagna' WHEN 'GB' THEN 'Regno Unito' WHEN 'NL' THEN 'Paesi Bassi'
    WHEN 'BE' THEN 'Belgio' WHEN 'CH' THEN 'Svizzera' WHEN 'AT' THEN 'Austria'
    ELSE v_country_code END;
  
  -- Registra battaglia
  INSERT INTO country_battle_wins (id, battle_id, winner_id, country_code, is_pvp, is_valid_for_domination, won_at, lat, lng, is_win)
  VALUES (v_battle_id, v_battle_id, v_user_id, v_country_code, p_is_pvp, true, NOW(), p_lat, p_lng, p_won);
  
  IF p_won THEN
    -- Assicura paese esista
    INSERT INTO country_domination (country_code, conquest_threshold, win_progress, last_battle_id, last_activity)
    SELECT v_country_code, COALESCE(ct.threshold, 25), 0, v_battle_id, NOW()
    FROM (SELECT 1) AS dummy LEFT JOIN country_thresholds ct ON ct.country_code = v_country_code
    ON CONFLICT (country_code) DO UPDATE SET last_battle_id = v_battle_id, last_activity = NOW();
    
    -- 🆕 CHI HA PIÙ VITTORIE?
    SELECT winner_id, COUNT(*) INTO v_top_winner_id, v_top_winner_wins
    FROM country_battle_wins WHERE country_code = v_country_code AND is_win = true
    GROUP BY winner_id ORDER BY COUNT(*) DESC LIMIT 1;
    
    SELECT COUNT(*) INTO v_user_wins FROM country_battle_wins
    WHERE country_code = v_country_code AND winner_id = v_user_id AND is_win = true;
    
    SELECT owner_id, conquest_threshold INTO v_current_owner, v_threshold
    FROM country_domination WHERE country_code = v_country_code;
    IF v_threshold IS NULL THEN v_threshold := 25; END IF;
    
    -- Aggiorna win_progress con max vittorie
    UPDATE country_domination SET win_progress = v_top_winner_wins WHERE country_code = v_country_code;
    
    -- Status
    IF v_top_winner_wins >= v_threshold THEN v_new_status := 'conquered';
    ELSIF v_top_winner_wins >= CEIL(v_threshold * 0.8) THEN v_new_status := 'contested';
    ELSE v_new_status := 'neutral'; END IF;
    
    -- 🏆 OWNER = CHI HA PIÙ VITTORIE (se >= soglia)
    IF v_top_winner_id IS NOT NULL AND v_top_winner_wins >= v_threshold THEN
      UPDATE country_domination SET owner_id = v_top_winner_id, status = 'conquered',
        conquered_at = CASE WHEN owner_id != v_top_winner_id THEN NOW() ELSE conquered_at END
      WHERE country_code = v_country_code;
    ELSIF v_new_status = 'contested' THEN
      UPDATE country_domination SET status = 'contested' WHERE country_code = v_country_code;
    END IF;
  END IF;
  
  RETURN jsonb_build_object('success', true, 'battle_id', v_battle_id, 'country_code', v_country_code,
    'country_name', v_country_name, 'is_win', p_won, 'your_wins', v_user_wins,
    'top_winner_wins', v_top_winner_wins, 'threshold', v_threshold, 'status', v_new_status);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."log_battle_result"("p_user_id" "uuid", "p_opponent_id" "text", "p_lat" double precision, "p_lng" double precision, "p_is_pvp" boolean, "p_won" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_battle_win"("p_winner_id" "uuid", "p_opponent_id" "text", "p_lat" double precision, "p_lng" double precision, "p_is_pvp" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_country_code CHAR(2);
  v_battle_id UUID;
BEGIN
  -- Verifica autorizzazione
  IF p_winner_id != auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  
  -- Genera ID univoco
  v_battle_id := gen_random_uuid();
  
  -- Calcola paese dalle coordinate
  v_country_code := get_country_code_from_coords(COALESCE(p_lat, 0), COALESCE(p_lng, 0));
  
  -- Se coordinate non valide
  IF v_country_code = 'XX' OR p_lat IS NULL OR p_lng IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid coordinates', 'lat', p_lat, 'lng', p_lng);
  END IF;
  
  -- Inserisci vittoria
  INSERT INTO country_battle_wins (
    battle_id, winner_id, loser_id, country_code,
    lat, lng, is_pvp, is_valid_for_domination, won_at
  ) VALUES (
    v_battle_id, p_winner_id, NULL, v_country_code,
    p_lat, p_lng, p_is_pvp, true, NOW()
  );
  
  -- Assicura esistenza paese in domination
  INSERT INTO country_domination (country_code)
  VALUES (v_country_code)
  ON CONFLICT (country_code) DO NOTHING;
  
  -- Aggiorna progresso
  UPDATE country_domination
  SET win_progress = win_progress + 1, last_battle_id = v_battle_id, last_activity_at = NOW()
  WHERE country_code = v_country_code;
  
  -- Ritorna risultato
  RETURN jsonb_build_object(
    'success', true,
    'battle_id', v_battle_id,
    'country_code', v_country_code,
    'country_name', CASE v_country_code
      WHEN 'IT' THEN 'Italia' WHEN 'FR' THEN 'Francia' WHEN 'DE' THEN 'Germania'
      WHEN 'ES' THEN 'Spagna' WHEN 'GB' THEN 'Regno Unito' WHEN 'US' THEN 'Stati Uniti'
      WHEN 'CH' THEN 'Svizzera' WHEN 'AT' THEN 'Austria' WHEN 'BE' THEN 'Belgio'
      WHEN 'NL' THEN 'Paesi Bassi' WHEN 'MC' THEN 'Monaco' WHEN 'PT' THEN 'Portogallo'
      ELSE v_country_code END,
    'lat', p_lat,
    'lng', p_lng
  );
END;
$$;


