CREATE OR REPLACE FUNCTION "public"."log_iap_notification"("p_platform" "text", "p_notification_id" "text", "p_notification_type" "text", "p_notification_subtype" "text", "p_original_transaction_id" "text", "p_transaction_id" "text", "p_purchase_token" "text", "p_product_id" "text", "p_user_id" "uuid", "p_payload" "jsonb", "p_signature_valid" boolean, "p_environment" "text", "p_event_timestamp" timestamp with time zone, "p_correlation_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_notification_id UUID;
BEGIN
    INSERT INTO iap_notifications (
        platform, notification_id, notification_type, notification_subtype,
        original_transaction_id, transaction_id, purchase_token, product_id,
        user_id, payload, signature_valid, environment, 
        event_timestamp, correlation_id, status
    )
    VALUES (
        p_platform, p_notification_id, p_notification_type, p_notification_subtype,
        p_original_transaction_id, p_transaction_id, p_purchase_token, p_product_id,
        p_user_id, p_payload, p_signature_valid, p_environment,
        p_event_timestamp, p_correlation_id, 'received'
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_notification_id;
    
    -- If NULL, it was a duplicate
    IF v_notification_id IS NULL THEN
        -- Mark as duplicate and return existing ID
        SELECT id INTO v_notification_id
        FROM iap_notifications
        WHERE platform = p_platform
          AND (
            (p_notification_id IS NOT NULL AND notification_id = p_notification_id)
            OR (p_platform = 'ios' AND original_transaction_id = p_original_transaction_id 
                AND notification_type = p_notification_type 
                AND COALESCE(notification_subtype, '') = COALESCE(p_notification_subtype, '')
                AND event_timestamp = p_event_timestamp)
            OR (p_platform = 'android' AND purchase_token = p_purchase_token 
                AND notification_type = p_notification_type 
                AND event_timestamp = p_event_timestamp)
          )
        LIMIT 1;
    END IF;
    
    RETURN v_notification_id;
END;
$$;


ALTER FUNCTION "public"."log_iap_notification"("p_platform" "text", "p_notification_id" "text", "p_notification_type" "text", "p_notification_subtype" "text", "p_original_transaction_id" "text", "p_transaction_id" "text", "p_purchase_token" "text", "p_product_id" "text", "p_user_id" "uuid", "p_payload" "jsonb", "p_signature_valid" boolean, "p_environment" "text", "p_event_timestamp" timestamp with time zone, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_potential_abuse"("p_event_type" "text", "p_user_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  is_abuse BOOLEAN;
  current_count INTEGER;
BEGIN
  -- Inserisci il log dell'evento
  INSERT INTO public.abuse_logs (user_id, event_type)
  VALUES (p_user_id, p_event_type);
  
  -- Verifica se è abuso
  SELECT public.check_abuse_limit(p_event_type, p_user_id) INTO is_abuse;
  
  -- Se è abuso, crea un alert
  IF is_abuse THEN
    -- Conta gli eventi attuali
    SELECT COUNT(*) INTO current_count
    FROM public.abuse_logs
    WHERE user_id = p_user_id
      AND event_type = p_event_type
      AND timestamp >= NOW() - INTERVAL '30 seconds';
    
    -- Inserisci alert solo se non esiste già uno recente
    INSERT INTO public.abuse_alerts (user_id, event_type, event_count)
    SELECT p_user_id, p_event_type, current_count
    WHERE NOT EXISTS (
      SELECT 1 FROM public.abuse_alerts
      WHERE user_id = p_user_id
        AND event_type = p_event_type
        AND alert_timestamp >= NOW() - INTERVAL '1 minute'
    );
  END IF;
  
  RETURN is_abuse;
END;
$$;


ALTER FUNCTION "public"."log_potential_abuse"("p_event_type" "text", "p_user_id" "text") OWNER TO "postgres";


