CREATE OR REPLACE FUNCTION "public"."m1u_fake_update"("_delta" bigint DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_new bigint;
begin
  perform public.m1u_ensure_row(v_uid);

  insert into public.user_m1_units_events(user_id, delta, reason)
  values (v_uid, _delta, 'fake_update');

  update public.user_m1_units
  set balance = balance + _delta, updated_at = now()
  where user_id = v_uid
  returning balance into v_new;

  return jsonb_build_object('ok', true, 'balance', v_new);
end;
$$;


