CREATE OR REPLACE FUNCTION "public"."m1u_get_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id  uuid;
  v_wallet   public.user_m1_units%ROWTYPE;
  v_now      timestamptz := now();
BEGIN
  -- Prende l'utente loggato
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'm1u_get_summary: unauthenticated user';
  END IF;

  -- Legge il wallet
  SELECT *
  INTO v_wallet
  FROM public.user_m1_units
  WHERE user_id = v_user_id;

  -- Se non esiste, lo crea a 0
  IF NOT FOUND THEN
    INSERT INTO public.user_m1_units (user_id, balance, updated_at)
    VALUES (v_user_id, 0, v_now)
    RETURNING * INTO v_wallet;
  END IF;

  -- Ritorna il JSON atteso dalla app
  RETURN jsonb_build_object(
    'user_id',      v_wallet.user_id,
    'balance',      v_wallet.balance,
    'total_earned', 0,
    'total_spent',  0,
    'updated_at',   COALESCE(v_wallet.updated_at, v_now)
  );
END;
$$;


ALTER FUNCTION "public"."m1u_get_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."m1u_ping"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Aggiorna timestamp per triggerare realtime
  UPDATE public.user_m1_units
  SET updated_at = now()
  WHERE user_id = v_user_id;
  
  RETURN jsonb_build_object('success', true, 'timestamp', now());
END;
$$;


