CREATE OR REPLACE FUNCTION "public"."mf_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_links_count bigint;
  v_milestones_count bigint;
begin
  -- Get authenticated user
  v_user_id := auth.uid();
  
  if v_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'Not authenticated'
    );
  end if;
  
  -- Count links
  select count(*) into v_links_count
  from dna_mind_links
  where user_id = v_user_id;
  
  -- Count milestones
  select count(*) into v_milestones_count
  from dna_mind_milestones
  where user_id = v_user_id;
  
  return jsonb_build_object(
    'ok', true,
    'links', v_links_count,
    'milestones', v_milestones_count,
    'timestamp', now()
  );
end;
$$;


ALTER FUNCTION "public"."mf_health"() OWNER TO "postgres";


