    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'mirror_push'
    AS $$
  SELECT last_run_at FROM mirror_push.sync_watermarks WHERE name = p_name ORDER BY last_run_at DESC LIMIT 1;
$$;


