CREATE OR REPLACE FUNCTION "public"."mirror_insert_notification_logs"("p_records" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'mirror_push'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  INSERT INTO mirror_push.notification_logs (
    created_at, sent_at, sent_by, provider, status_code,
    title, body, url, endpoint, project_ref, user_id,
    invocation_id, metadata
  )
  SELECT 
    COALESCE((r->>'created_at')::timestamptz, now()),
    (r->>'sent_at')::timestamptz,
    NULLIF(r->>'sent_by','')::uuid,
    COALESCE(r->>'provider','HARVESTER'),
    COALESCE((r->>'status_code')::int, 200),
    NULLIF(r->>'title',''),
    NULLIF(r->>'body',''),
    NULLIF(r->>'url',''),
    NULLIF(r->>'endpoint',''),
    COALESCE(r->>'project_ref',''),
    NULLIF(r->>'user_id','')::uuid,
    r->>'invocation_id',
    COALESCE(r->'metadata', '{}'::jsonb)
  FROM jsonb_array_elements(p_records) AS r;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."mirror_insert_notification_logs"("p_records" "jsonb") OWNER TO "postgres";


