CREATE OR REPLACE FUNCTION "public"."normalize_feed_url"("input_url" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $_$
begin
  -- Basic URL normalization for deduplication
  return lower(
    regexp_replace(
      regexp_replace(input_url, '[?&](utm_[^&]*|fbclid=[^&]*|gclid=[^&]*)', '', 'g'),
      '#.*$', ''
    )
  );
end $_$;


