CREATE OR REPLACE FUNCTION "public"."prevent_agent_code_modification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  is_admin BOOLEAN;
BEGIN
  -- Allow admin users to modify agent_code
  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() AND role = 'admin'
  ) INTO is_admin;
  
  IF is_admin THEN
    RETURN NEW;
  END IF;
  
  -- Block modification for non-admin users
  IF TG_OP = 'UPDATE' AND OLD.agent_code IS DISTINCT FROM NEW.agent_code THEN
    RAISE EXCEPTION 'Modifica di agent_code non consentita per utenti non-admin';
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_agent_code_modification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_mcp_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_mcp_rank_id INT;
  v_is_joseph BOOLEAN := FALSE;
BEGIN
  -- Get MCP rank ID
  SELECT id INTO v_mcp_rank_id
  FROM agent_ranks
  WHERE code = 'SRC-∞';

  -- Skip check if MCP rank doesn't exist or rank_id not changing to MCP
  IF v_mcp_rank_id IS NULL OR NEW.rank_id != v_mcp_rank_id THEN
    RETURN NEW;
  END IF;

  -- Check if user is Joseph (admin with specific email)
  SELECT EXISTS (
    SELECT 1 FROM auth.users u
    JOIN profiles p ON p.id = u.id
    WHERE p.id = NEW.id
      AND p.role = 'admin'
      AND u.email = 'wikus77@hotmail.it'
  ) INTO v_is_joseph;

  -- Block MCP assignment for non-Joseph users
  IF NOT v_is_joseph THEN
    RAISE EXCEPTION 'MCP rank (SRC-∞) is reserved for Joseph Mulé only. User: %, Rank: %', NEW.id, NEW.rank_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_mcp_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prize_clues_enforce_clue_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v text;
BEGIN
  IF NEW.clue_type IS NULL THEN
    RETURN NEW;
  END IF;

  v := lower(trim(NEW.clue_type));

  IF v IN ('location','loc','place','city','geo','geoint','area','where') THEN
    NEW.clue_type := 'location';
  ELSIF v IN ('prize','reward','premio','item','object','loot','gift') THEN
    NEW.clue_type := 'prize';
  ELSIF v IN ('real','decoy','regular') THEN
    -- vecchi valori -> BLOCCA (oppure mettili a NULL se preferisci)
    RAISE EXCEPTION 'Invalid clue_type legacy value: %', NEW.clue_type;
  ELSE
    RAISE EXCEPTION 'Invalid clue_type: %', NEW.clue_type;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prize_clues_enforce_clue_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_battle_for_domination"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_country_code CHAR(2);
  v_winner_is_real BOOLEAN;
  v_opponent_is_real BOOLEAN;
  v_is_pvp BOOLEAN;
  v_is_valid_for_domination BOOLEAN;
  v_current_owner UUID;
  v_current_progress INTEGER;
  v_threshold INTEGER;
  v_new_status TEXT;
  v_loser_id UUID;
BEGIN
  -- Solo quando resolved_at viene impostato (battaglia conclusa)
  IF NEW.resolved_at IS NULL OR NEW.winner_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Evita ri-processamento (idempotenza)
  IF OLD.resolved_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  -- Determina loser
  IF NEW.creator_id = NEW.winner_id THEN
    v_loser_id := NEW.opponent_id;
  ELSE
    v_loser_id := NEW.creator_id;
  END IF;
  
  -- Calcola country code dalle coordinate
  v_country_code := get_country_code_from_coords(
    COALESCE(NEW.arena_lat, 0),
    COALESCE(NEW.arena_lng, 0)
  );
  
  -- Se coordinate non valide, skip
  IF v_country_code = 'XX' THEN
    RETURN NEW;
  END IF;
  
  -- Verifica se winner è reale
  SELECT EXISTS(
    SELECT 1 FROM profiles WHERE id = NEW.winner_id
  ) INTO v_winner_is_real;
  
  -- Verifica se opponent è reale (per flag is_pvp)
  SELECT EXISTS(
    SELECT 1 FROM profiles WHERE id = v_loser_id
  ) INTO v_opponent_is_real;
  
  -- is_pvp = entrambi reali
  v_is_pvp := v_winner_is_real AND v_opponent_is_real;
  
  -- is_valid_for_domination = winner reale (anche se opponent è fake)
  v_is_valid_for_domination := v_winner_is_real;
  
  -- Inserisci in log vittorie (idempotente via battle_id UNIQUE)
  INSERT INTO country_battle_wins (
    battle_id, winner_id, loser_id, country_code,
    lat, lng, is_pvp, is_valid_for_domination, won_at
  ) VALUES (
    NEW.id, NEW.winner_id, v_loser_id, v_country_code,
    NEW.arena_lat, NEW.arena_lng, v_is_pvp, v_is_valid_for_domination, NEW.resolved_at
  )
  ON CONFLICT (battle_id) DO NOTHING;
  
  -- Se winner non è reale, skip aggiornamento dominio
  IF NOT v_winner_is_real THEN
    RETURN NEW;
  END IF;
  
  -- Assicurati che il paese esista nella tabella domination
  INSERT INTO country_domination (country_code)
  VALUES (v_country_code)
  ON CONFLICT (country_code) DO NOTHING;
  
  -- Aggiorna progresso dominio
  UPDATE country_domination
  SET 
    win_progress = win_progress + 1,
    last_battle_id = NEW.id,
    last_activity_at = NOW()
  WHERE country_code = v_country_code
  RETURNING owner_id, win_progress, conquest_threshold INTO v_current_owner, v_current_progress, v_threshold;
  
  -- Calcola nuovo status
  v_new_status := calculate_domination_status(v_current_progress, v_threshold);
  
  -- Se diventa conquered e non c'era owner (o owner diverso)
  IF v_new_status = 'conquered' AND (v_current_owner IS NULL OR v_current_owner != NEW.winner_id) THEN
    -- Aggiorna owner
    UPDATE country_domination
    SET 
      owner_id = NEW.winner_id,
      status = 'conquered',
      conquered_at = NOW()
    WHERE country_code = v_country_code;
    
    -- Assegna reward +1000 PE (idempotente)
    PERFORM award_domination_reward(NEW.winner_id, 'country', v_country_code);
    
    -- Verifica bonus aggiuntivi (3 paesi, continente)
    PERFORM check_and_award_domination_bonuses(NEW.winner_id);
    
  ELSIF v_new_status = 'contested' THEN
    -- Aggiorna solo status
    UPDATE country_domination
    SET status = 'contested'
    WHERE country_code = v_country_code;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_battle_for_domination"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_battle_for_domination"() IS 'Trigger function: processa battaglia per Risiko Domination. Vittorie vs Fake Agent ora contano.';



CREATE OR REPLACE FUNCTION "public"."process_battle_session_for_domination"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_country_code CHAR(2) := 'IT';
  v_is_pvp BOOLEAN;
  v_current_owner UUID;
  v_current_progress INTEGER;
  v_threshold INTEGER;
  v_new_status TEXT;
  v_loser_id UUID;
BEGIN
  IF NEW.resolved_at IS NULL OR NEW.winner_id IS NULL THEN
    RETURN NEW;
  END IF;
  
  IF OLD.resolved_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  IF NEW.creator_id = NEW.winner_id THEN
    v_loser_id := NEW.defender_id;
  ELSE
    v_loser_id := NEW.creator_id;
  END IF;
  
  SELECT EXISTS(SELECT 1 FROM profiles WHERE id = NEW.winner_id)
     AND EXISTS(SELECT 1 FROM profiles WHERE id = v_loser_id)
  INTO v_is_pvp;
  
  INSERT INTO country_battle_wins (
    battle_id, winner_id, loser_id, country_code,
    lat, lng, is_pvp, is_valid_for_domination, won_at
  ) VALUES (
    NEW.id, NEW.winner_id, v_loser_id, v_country_code,
    NULL, NULL, v_is_pvp, v_is_pvp, NEW.resolved_at
  )
  ON CONFLICT (battle_id) DO NOTHING;
  
  IF NOT v_is_pvp THEN
    RETURN NEW;
  END IF;
  
  INSERT INTO country_domination (country_code, conquest_threshold)
  VALUES (v_country_code, 21)
  ON CONFLICT (country_code) DO NOTHING;
  
  UPDATE country_domination
  SET 
    win_progress = win_progress + 1,
    last_battle_id = NEW.id,
    last_activity_at = NOW()
  WHERE country_code = v_country_code
  RETURNING owner_id, win_progress, conquest_threshold INTO v_current_owner, v_current_progress, v_threshold;
  
  IF v_current_progress >= v_threshold THEN
    v_new_status := 'conquered';
  ELSIF v_current_progress >= CEIL(v_threshold * 0.8) THEN
    v_new_status := 'contested';
  ELSE
    v_new_status := 'neutral';
  END IF;
  
  IF v_new_status = 'conquered' AND (v_current_owner IS NULL OR v_current_owner != NEW.winner_id) THEN
    UPDATE country_domination
    SET owner_id = NEW.winner_id, status = 'conquered', conquered_at = NOW()
    WHERE country_code = v_country_code;
  ELSIF v_new_status = 'contested' AND v_current_owner IS NULL THEN
    UPDATE country_domination
    SET status = 'contested', owner_id = NEW.winner_id
    WHERE country_code = v_country_code;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_battle_session_for_domination"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_iap_purchase"("p_user_id" "uuid", "p_platform" "text", "p_product_code" "text", "p_store_product_id" "text", "p_transaction_id" "text", "p_receipt_hash" "text" DEFAULT NULL::"text", "p_validation_response" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transaction_id UUID;
  v_product_type TEXT;
  v_m1u_amount INT;
  v_subscription_tier TEXT;
  v_current_m1u INT;
  v_new_balance INT;
BEGIN
  -- 1. Determine product type and amounts
  CASE p_product_code
    WHEN 'M1U_PACK_100' THEN v_product_type := 'consumable'; v_m1u_amount := 100;
    WHEN 'M1U_PACK_500' THEN v_product_type := 'consumable'; v_m1u_amount := 500;
    WHEN 'M1U_PACK_1000' THEN v_product_type := 'consumable'; v_m1u_amount := 1000;
    WHEN 'M1U_PACK_2500' THEN v_product_type := 'consumable'; v_m1u_amount := 2500;
    WHEN 'M1U_PACK_5000' THEN v_product_type := 'consumable'; v_m1u_amount := 5000;
    WHEN 'SUB_SILVER' THEN v_product_type := 'subscription'; v_subscription_tier := 'silver';
    WHEN 'SUB_GOLD' THEN v_product_type := 'subscription'; v_subscription_tier := 'gold';
    WHEN 'SUB_BLACK' THEN v_product_type := 'subscription'; v_subscription_tier := 'black';
    WHEN 'SUB_TITANIUM' THEN v_product_type := 'subscription'; v_subscription_tier := 'titanium';
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Unknown product code');
  END CASE;

  -- 2. Check for duplicate transaction
  IF EXISTS (
    SELECT 1 FROM public.iap_transactions 
    WHERE platform = p_platform AND transaction_id = p_transaction_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction already processed');
  END IF;

  -- 3. Insert transaction record
  INSERT INTO public.iap_transactions (
    user_id, platform, product_code, store_product_id, 
    product_type, transaction_id, receipt_hash,
    validation_response, status, validated_at
  ) VALUES (
    p_user_id, p_platform, p_product_code, p_store_product_id,
    v_product_type, p_transaction_id, p_receipt_hash,
    p_validation_response, 'validated', now()
  )
  RETURNING id INTO v_transaction_id;

  -- 4. Process based on product type
  IF v_product_type = 'consumable' THEN
    -- Credit M1U
    SELECT COALESCE(m1_units, 0) INTO v_current_m1u
    FROM public.profiles WHERE id = p_user_id;
    
    v_new_balance := v_current_m1u + v_m1u_amount;
    
    UPDATE public.profiles
    SET m1_units = v_new_balance
    WHERE id = p_user_id;
    
    -- Update transaction
    UPDATE public.iap_transactions
    SET status = 'credited', m1u_credited = v_m1u_amount, credited_at = now()
    WHERE id = v_transaction_id;
    
    -- Log to ledger
    INSERT INTO public.m1u_ledger (user_id, delta, balance_after, reason, ref_transaction_id, ref_type)
    VALUES (p_user_id, v_m1u_amount, v_new_balance, 'IAP Purchase: ' || p_product_code, v_transaction_id, 'iap');
    
    RETURN jsonb_build_object(
      'success', true,
      'type', 'consumable',
      'm1u_credited', v_m1u_amount,
      'new_balance', v_new_balance,
      'transaction_id', v_transaction_id
    );
    
  ELSE
    -- Subscription
    -- Deactivate existing entitlements
    UPDATE public.subscription_entitlements
    SET status = 'expired', updated_at = now()
    WHERE user_id = p_user_id AND status = 'active';
    
    -- Create new entitlement
    INSERT INTO public.subscription_entitlements (
      user_id, tier, source, source_transaction_id,
      starts_at, expires_at, status
    ) VALUES (
      p_user_id, v_subscription_tier, 'iap', v_transaction_id::text,
      now(), now() + INTERVAL '1 month', 'active'
    );
    
    -- Update transaction
    UPDATE public.iap_transactions
    SET status = 'credited', 
        subscription_tier = v_subscription_tier,
        subscription_expires_at = now() + INTERVAL '1 month',
        credited_at = now()
    WHERE id = v_transaction_id;
    
    -- Update profile tier
    UPDATE public.profiles
    SET subscription_tier = v_subscription_tier,
        subscription_expires_at = now() + INTERVAL '1 month'
    WHERE id = p_user_id;
    
    RETURN jsonb_build_object(
      'success', true,
      'type', 'subscription',
      'tier', v_subscription_tier,
      'expires_at', (now() + INTERVAL '1 month')::text,
      'transaction_id', v_transaction_id
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."process_iap_purchase"("p_user_id" "uuid", "p_platform" "text", "p_product_code" "text", "p_store_product_id" "text", "p_transaction_id" "text", "p_receipt_hash" "text", "p_validation_response" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_iap_purchase"("p_user_id" "uuid", "p_platform" "text", "p_product_code" "text", "p_store_product_id" "text", "p_transaction_id" "text", "p_receipt_hash" "text", "p_validation_response" "jsonb") IS 'Validate and credit IAP purchases. Called from edge function only.';



CREATE OR REPLACE FUNCTION "public"."process_stripe_webhook_completed"("p_session_id" "text", "p_stripe_customer_id" "text", "p_payment_status" "text", "p_amount_total" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  session_record RECORD;
  subscription_id UUID;
BEGIN
  -- Trova la sessione checkout
  SELECT * INTO session_record
  FROM public.checkout_sessions
  WHERE session_id = p_session_id;
  
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  
  -- Aggiorna stato sessione
  UPDATE public.checkout_sessions
  SET 
    status = 'completed',
    payment_status = p_payment_status,
    stripe_customer_id = p_stripe_customer_id,
    amount_total = p_amount_total,
    completed_at = now(),
    updated_at = now()
  WHERE session_id = p_session_id;
  
  -- Crea o aggiorna subscription
  INSERT INTO public.subscriptions (
    user_id,
    tier,
    stripe_customer_id,
    stripe_subscription_id,
    status,
    current_period_start,
    current_period_end,
    cancel_at_period_end
  ) VALUES (
    session_record.user_id,
    session_record.tier,
    p_stripe_customer_id,
    p_session_id, -- Usiamo session_id come fallback
    'active',
    now(),
    now() + INTERVAL '1 month',
    false
  )
  ON CONFLICT (user_id) DO UPDATE SET
    tier = session_record.tier,
    stripe_customer_id = p_stripe_customer_id,
    status = 'active',
    current_period_start = now(),
    current_period_end = now() + INTERVAL '1 month',
    cancel_at_period_end = false,
    updated_at = now();
  
  -- Aggiorna profilo utente
  UPDATE public.profiles
  SET 
    subscription_tier = session_record.tier,
    tier = session_record.tier,
    updated_at = now()
  WHERE id = session_record.user_id;
  
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."process_stripe_webhook_completed"("p_session_id" "text", "p_stripe_customer_id" "text", "p_payment_status" "text", "p_amount_total" integer) OWNER TO "postgres";


