CREATE OR REPLACE FUNCTION "public"."purchase_battle_item"("p_item_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_item RECORD;
  v_current_balance INTEGER;
  v_total_cost INTEGER;
  v_current_quantity INTEGER;
  v_new_quantity INTEGER;
  v_rows_updated INTEGER;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_item FROM public.battle_items WHERE id = p_item_id AND is_active = true;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item not found');
  END IF;

  v_total_cost := v_item.base_price_m1u * p_quantity;

  SELECT COALESCE(m1_units, 0) INTO v_current_balance
  FROM public.profiles WHERE id = v_user_id;

  IF v_current_balance < v_total_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient M1U');
  END IF;

  SELECT COALESCE(quantity, 0) INTO v_current_quantity
  FROM public.user_battle_items WHERE user_id = v_user_id AND item_id = p_item_id;
  
  v_new_quantity := COALESCE(v_current_quantity, 0) + p_quantity;

  IF v_new_quantity > v_item.max_stack THEN
    RETURN jsonb_build_object('success', false, 'error', 'Max stack reached');
  END IF;

  -- DEDUCT M1U
  UPDATE public.profiles
  SET m1_units = m1_units - v_total_cost, updated_at = NOW()
  WHERE id = v_user_id AND m1_units >= v_total_cost;
  
  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  
  IF v_rows_updated = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Failed to deduct M1U');
  END IF;

  INSERT INTO public.user_battle_items (user_id, item_id, quantity, purchased_at)
  VALUES (v_user_id, p_item_id, p_quantity, NOW())
  ON CONFLICT (user_id, item_id) DO UPDATE SET 
    quantity = user_battle_items.quantity + p_quantity, purchased_at = NOW();

  RETURN jsonb_build_object(
    'success', true,
    'item_code', v_item.code,
    'total_cost', v_total_cost,
    'new_balance', v_current_balance - v_total_cost
  );
END;
$$;


ALTER FUNCTION "public"."purchase_battle_item"("p_item_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_scratch_ticket"("p_tier" integer, "p_client_nonce" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_current_m1u NUMERIC;
  v_purchase_id UUID;
  v_existing_purchase UUID;
  v_daily_count INT;
BEGIN
  -- 1. Verifica autenticazione
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'User not authenticated');
  END IF;
  
  -- 2. Verifica tier valido
  IF p_tier NOT IN (10, 30, 50) THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invalid tier');
  END IF;
  
  -- 3. Idempotency check
  SELECT id INTO v_existing_purchase 
  FROM public.user_scratch_purchases 
  WHERE user_id = v_user_id AND client_nonce = p_client_nonce;
  
  IF v_existing_purchase IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'already_purchased', 
      'purchase_id', v_existing_purchase,
      'message', 'Purchase already exists for this nonce'
    );
  END IF;
  
  -- 4. Rate limit: max 10 acquisti al giorno PER TIER
  SELECT COUNT(*) INTO v_daily_count
  FROM public.user_scratch_purchases
  WHERE user_id = v_user_id 
    AND tier = p_tier
    AND created_at > now() - interval '24 hours';
  
  IF v_daily_count >= 10 THEN
    INSERT INTO public.scratch_abuse_logs (user_id, event_type, details)
    VALUES (v_user_id, 'rate_limit_exceeded', jsonb_build_object('daily_count', v_daily_count, 'tier', p_tier));
    
    RETURN jsonb_build_object('status', 'error', 'message', 'Daily limit reached for this tier (max 10)');
  END IF;
  
  -- 5. Verifica saldo M1U
  SELECT m1_units INTO v_current_m1u FROM public.profiles WHERE id = v_user_id;
  
  IF v_current_m1u IS NULL OR v_current_m1u < p_tier THEN
    RETURN jsonb_build_object(
      'status', 'insufficient_balance', 
      'current_balance', COALESCE(v_current_m1u, 0),
      'required', p_tier
    );
  END IF;
  
  -- 6. Verifica disponibilità ticket nel pool
  IF NOT EXISTS (
    SELECT 1 FROM public.scratch_tickets 
    WHERE tier = p_tier AND is_claimed = false
  ) THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'No tickets available for this tier');
  END IF;
  
  -- 7. Scala M1U
  UPDATE public.profiles 
  SET m1_units = m1_units - p_tier,
      updated_at = now()
  WHERE id = v_user_id AND m1_units >= p_tier;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Failed to deduct M1U');
  END IF;
  
  -- 8. Crea record purchase
  INSERT INTO public.user_scratch_purchases (user_id, tier, client_nonce, status)
  VALUES (v_user_id, p_tier, p_client_nonce, 'purchased')
  RETURNING id INTO v_purchase_id;
  
  -- 9. ⭐ NUOVO: Contribuisci al jackpot fund
  PERFORM public.contribute_to_jackpot_fund(p_tier, p_tier, v_user_id);
  
  -- 10. Log analytics
  INSERT INTO public.analytics_events (event_name, user_id, session_id, platform, props, event_version)
  VALUES (
    'scratch_ticket_purchased',
    v_user_id,
    'server',
    'web',
    jsonb_build_object('tier', p_tier, 'purchase_id', v_purchase_id, 'cost', p_tier),
    1
  );
  
  RETURN jsonb_build_object(
    'status', 'success',
    'purchase_id', v_purchase_id,
    'tier', p_tier,
    'new_balance', v_current_m1u - p_tier
  );

EXCEPTION
  WHEN unique_violation THEN
    SELECT id INTO v_existing_purchase 
    FROM public.user_scratch_purchases 
    WHERE user_id = v_user_id AND client_nonce = p_client_nonce;
    
    RETURN jsonb_build_object(
      'status', 'already_purchased', 
      'purchase_id', v_existing_purchase
    );
  WHEN OTHERS THEN
    RAISE LOG 'Error in purchase_scratch_ticket: %', SQLERRM;
    RETURN jsonb_build_object('status', 'error', 'message', 'Internal server error');
END;
$$;


ALTER FUNCTION "public"."purchase_scratch_ticket"("p_tier" integer, "p_client_nonce" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qr_admin_upsert"("p_code" "text", "p_title" "text", "p_reward_type" "text", "p_reward_value" integer, "p_days_valid" integer DEFAULT 30, "p_max_total" integer DEFAULT 100, "p_max_per_user" integer DEFAULT 1, "p_center_lat" double precision DEFAULT NULL::double precision, "p_center_lon" double precision DEFAULT NULL::double precision, "p_radius_m" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_admin boolean;
  v_id uuid;
begin
  -- Consenti solo a service_role oppure a utenti con user_profiles.is_admin = true
  v_is_admin :=
    coalesce( (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role', false )
    or exists (
      select 1
      from public.user_profiles up
      where up.id = auth.uid()  -- <-- qui usiamo 'id', non 'user_id'
        and up.is_admin = true
    );

  if not v_is_admin then
    return jsonb_build_object('status','error','message','forbidden');
  end if;

  insert into public.qr_codes
    (code, title, is_active, expires_at,
     max_uses_total, max_uses_per_user,
     center_lat, center_lon, radius_m,
     reward_type, reward_value)
  values
    (p_code, p_title, p_is_active, now() + make_interval(days => p_days_valid),
     p_max_total, p_max_per_user,
     p_center_lat, p_center_lon, p_radius_m,
     p_reward_type, p_reward_value)
  on conflict (code) do update set
     title             = excluded.title,
     is_active         = excluded.is_active,
     expires_at        = excluded.expires_at,
     max_uses_total    = excluded.max_uses_total,
     max_uses_per_user = excluded.max_uses_per_user,
     center_lat        = excluded.center_lat,
     center_lon        = excluded.center_lon,
     radius_m          = excluded.radius_m,
     reward_type       = excluded.reward_type,
     reward_value      = excluded.reward_value
  returning id into v_id;

  return jsonb_build_object('status','ok','id',v_id,'code',p_code);
end;
$$;


ALTER FUNCTION "public"."qr_admin_upsert"("p_code" "text", "p_title" "text", "p_reward_type" "text", "p_reward_value" integer, "p_days_valid" integer, "p_max_total" integer, "p_max_per_user" integer, "p_center_lat" double precision, "p_center_lon" double precision, "p_radius_m" integer, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qr_redeem"("p_code" "text", "p_lat" double precision DEFAULT NULL::double precision, "p_lon" double precision DEFAULT NULL::double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_row  public.qr_codes%rowtype;
  v_total_used int;
  v_user_used  int;
  v_distance_m double precision;
  v_balance_after int;
begin
  -- 1) Autenticazione
  if v_user is null then
    return jsonb_build_object('status','error','error','not_authenticated');
  end if;

  -- 2) Carico QR
  select * into v_row
  from public.qr_codes
  where code = p_code;

  if not found then
    return jsonb_build_object('status','error','error','code_not_found','code',p_code);
  end if;

  -- 3) Stato e scadenza
  if not coalesce(v_row.is_active, false) then
    return jsonb_build_object('status','error','error','inactive_code','code',p_code);
  end if;

  if v_row.expires_at is not null and now() > v_row.expires_at then
    return jsonb_build_object('status','error','error','expired','code',p_code,'expires_at',v_row.expires_at);
  end if;

  -- 4) Geofence (se il QR ha centro e raggio e se client ha passato lat/lon)
  if v_row.center_lat is not null and v_row.center_lon is not null and v_row.radius_m is not null
     and p_lat is not null and p_lon is not null then
    v_distance_m := public.haversine_m(p_lat, p_lon, v_row.center_lat, v_row.center_lon);
    if v_distance_m > v_row.radius_m then
      return jsonb_build_object('status','error','error','outside_geofence',
                                'distance_m', round(v_distance_m)::int,
                                'radius_m', v_row.radius_m);
    end if;
  end if;

  -- 5) Conteggi usi
  select count(*) into v_total_used
  from public.qr_redemptions
  where code = p_code;

  select count(*) into v_user_used
  from public.qr_redemptions
  where code = p_code and user_id = v_user;

  if v_row.max_uses_total is not null and v_total_used >= v_row.max_uses_total then
    return jsonb_build_object('status','error','error','max_total_reached',
                              'used',v_total_used,'max',v_row.max_uses_total);
  end if;

  if v_row.max_uses_per_user is not null and v_user_used >= v_row.max_uses_per_user then
    return jsonb_build_object('status','error','error','max_per_user_reached',
                              'used_by_user',v_user_used,'max',v_row.max_uses_per_user);
  end if;

  -- 6) Applico il premio (in base al reward_type consentito dal CHECK)
  v_balance_after := null;

  case v_row.reward_type
    when 'buzz_credit' then
      insert into public.user_balances as ub (user_id, buzz_credit)
      values (v_user, v_row.reward_value)
      on conflict (user_id) do update
        set buzz_credit = ub.buzz_credit + excluded.buzz_credit
      returning buzz_credit into v_balance_after;

    when 'buzz_map_credit' then
      insert into public.user_balances as ub (user_id, buzz_map_credit)
      values (v_user, v_row.reward_value)
      on conflict (user_id) do update
        set buzz_map_credit = ub.buzz_map_credit + excluded.buzz_map_credit
      returning buzz_map_credit into v_balance_after;

    when 'custom' then
      -- Log per gestione personalizzata lato app/backoffice
      insert into public.user_custom_rewards(user_id, code, title, reward_value)
      values (v_user, v_row.code, v_row.title, v_row.reward_value);
    else
      -- Nel caso in futuro si aggiunga un nuovo valore nel CHECK,
      -- lo trattiamo come "custom" di default ma NON falliamo.
      insert into public.user_custom_rewards(user_id, code, title, reward_value)
      values (v_user, v_row.code, v_row.title, v_row.reward_value);
  end case;

  -- 7) Log redemption
  insert into public.qr_redemptions(user_id, code, lat, lon, reward_type, reward_value)
  values (v_user, v_row.code, p_lat, p_lon, v_row.reward_type, v_row.reward_value);

  -- 8) Ritorno JSON ricco
  return jsonb_build_object(
    'status','ok',
    'code', v_row.code,
    'title', v_row.title,
    'reward_type', v_row.reward_type,
    'reward_value', v_row.reward_value,
    'balance_after', v_balance_after,
    'uses', jsonb_build_object(
      'total_used', v_total_used + 1,
      'max_total', v_row.max_uses_total,
      'user_used',  v_user_used + 1,
      'max_per_user', v_row.max_uses_per_user
    )
  );

exception
  when others then
    return jsonb_build_object('status','error','error',sqlstate,'message',sqlerrm);
end;
$$;


ALTER FUNCTION "public"."qr_redeem"("p_code" "text", "p_lat" double precision, "p_lon" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_rank"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_pe numeric;
  v_target_rank_id uuid;
  v_is_mcp boolean;
BEGIN
  -- Check if user is in MCP whitelist
  SELECT EXISTS (
    SELECT 1 FROM mcp_whitelist WHERE user_id = p_user_id
  ) INTO v_is_mcp;

  -- If MCP, force SRC-∞ rank
  IF v_is_mcp THEN
    SELECT id INTO v_target_rank_id 
    FROM agent_ranks 
    WHERE code = 'SRC-∞';
    
    UPDATE profiles
    SET rank_id = v_target_rank_id,
        rank_updated_at = NOW()
    WHERE id = p_user_id
      AND rank_id IS DISTINCT FROM v_target_rank_id;
    
    RETURN;
  END IF;

  -- Standard rank calculation for non-MCP users
  SELECT pulse_energy INTO v_current_pe
  FROM profiles
  WHERE id = p_user_id;

  IF v_current_pe IS NULL THEN
    RETURN;
  END IF;

  -- Find appropriate rank based on PE thresholds
  SELECT id INTO v_target_rank_id
  FROM agent_ranks
  WHERE pe_min <= v_current_pe
    AND (pe_max IS NULL OR pe_max > v_current_pe)
    AND code != 'SRC-∞'  -- Exclude MCP from standard calculation
  ORDER BY pe_min DESC
  LIMIT 1;

  -- Update rank if changed
  IF v_target_rank_id IS NOT NULL THEN
    UPDATE profiles
    SET rank_id = v_target_rank_id,
        rank_updated_at = NOW()
    WHERE id = p_user_id
      AND rank_id IS DISTINCT FROM v_target_rank_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."recompute_rank"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recompute_rank"("p_user_id" "uuid") IS 'Recompute user rank based on PE - respects MCP whitelist';



