CREATE OR REPLACE FUNCTION "public"."reset_user_mission"("user_id_input" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Inserisci o aggiorna lo stato della missione per l'utente
  INSERT INTO public.user_mission_status (
    user_id,
    clues_found,
    mission_progress_percent,
    mission_started_at,
    mission_days_remaining,
    buzz_counter,
    map_radius_km,
    map_area_generated,
    updated_at
  ) VALUES (
    user_id_input,
    0,
    0,
    NOW(),
    30,
    0,
    NULL,
    FALSE,
    NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    clues_found = 0,
    mission_progress_percent = 0,
    mission_started_at = NOW(),
    mission_days_remaining = 30,
    buzz_counter = 0,
    map_radius_km = NULL,
    map_area_generated = FALSE,
    updated_at = NOW();
END;
$$;


