CREATE OR REPLACE FUNCTION "public"."reset_user_mission_full"("user_id_input" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  reset_date TIMESTAMP WITH TIME ZONE := NOW();
  result jsonb;
BEGIN
  -- 1. Reset base mission (counters, radius, etc.) with NEW START DATE
  INSERT INTO public.user_mission_status (
    user_id,
    clues_found,
    mission_progress_percent,
    mission_started_at,
    mission_days_remaining,
    buzz_counter,
    map_radius_km,
    map_area_generated,
    updated_at
  ) VALUES (
    user_id_input,
    0,
    0,
    reset_date, -- 🔥 CRITICAL: Set to current date for proper countdown
    30,
    0,
    NULL,
    FALSE,
    reset_date
  )
  ON CONFLICT (user_id) DO UPDATE SET
    clues_found = 0,
    mission_progress_percent = 0,
    mission_started_at = reset_date, -- 🔥 CRITICAL: Update to current date
    mission_days_remaining = 30,
    buzz_counter = 0,
    map_radius_km = NULL,
    map_area_generated = FALSE,
    updated_at = reset_date;
  
  -- 2. Delete all user clues found
  DELETE FROM public.user_clues WHERE user_id = user_id_input;
  
  -- 3. Delete all user map areas generated
  DELETE FROM public.user_map_areas WHERE user_id = user_id_input;
  
  -- 4. Delete all BUZZ counters (daily and map)
  DELETE FROM public.user_buzz_counter WHERE user_id = user_id_input;
  DELETE FROM public.user_buzz_map_counter WHERE user_id = user_id_input;
  
  -- 5. Delete all notifications
  DELETE FROM public.user_notifications WHERE user_id = user_id_input;
  
  -- 6. Delete all final shot attempts
  DELETE FROM public.final_shots WHERE user_id = user_id_input;
  DELETE FROM public.daily_final_shot_limits WHERE user_id = user_id_input;
  
  -- 7. Delete all geo radar coordinates
  DELETE FROM public.geo_radar_coordinates WHERE user_id = user_id_input;
  
  -- 8. Delete all map click events
  DELETE FROM public.map_click_events WHERE user_id = user_id_input;
  
  -- 9. Delete all map points
  DELETE FROM public.map_points WHERE user_id = user_id_input;
  
  -- 10. Delete all intelligence tool usage
  DELETE FROM public.intelligence_tool_usage WHERE user_id = user_id_input;
  
  -- 11. Delete all buzz map actions
  DELETE FROM public.buzz_map_actions WHERE user_id = user_id_input;
  
  -- 12. Reset weekly buzz allowances (if exists)
  DELETE FROM public.weekly_buzz_allowances WHERE user_id = user_id_input;
  
  -- 13. Reset live activity state
  DELETE FROM public.live_activity_state WHERE user_id = user_id_input;
  
  -- Build success result
  result := jsonb_build_object(
    'success', true,
    'reset_date', reset_date,
    'mission_days_remaining', 30,
    'tables_reset', jsonb_build_array(
      'user_mission_status',
      'user_clues',
      'user_map_areas', 
      'user_buzz_counter',
      'user_buzz_map_counter',
      'user_notifications',
      'final_shots',
      'daily_final_shot_limits',
      'geo_radar_coordinates',
      'map_click_events',
      'map_points',
      'intelligence_tool_usage',
      'buzz_map_actions',
      'weekly_buzz_allowances',
      'live_activity_state'
    )
  );
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."reset_user_mission_full"("user_id_input" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reveal_scratch_progress"("p_purchase_id" "uuid", "p_client_nonce" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_purchase RECORD;
  v_progress RECORD;
  v_tier INT;
  v_progress_gain INT;
  v_milestone_reached BOOLEAN := false;
  v_milestone_level INT;
  v_reward_value INT := 0;
  v_current_m1u INT;
  
  -- Deterministic progress based on tier
  c_tier_10_base CONSTANT INT := 5;
  c_tier_30_base CONSTANT INT := 15;
  c_tier_50_base CONSTANT INT := 30;
  c_milestone_threshold CONSTANT INT := 100;
BEGIN
  -- 1. VERIFY AUTHENTICATION
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'User not authenticated');
  END IF;

  -- 2. VERIFY PURCHASE EXISTS AND BELONGS TO USER
  SELECT * INTO v_purchase
  FROM public.user_scratch_purchases
  WHERE id = p_purchase_id AND user_id = v_user_id
  FOR UPDATE;
  
  IF v_purchase IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Purchase not found');
  END IF;
  
  IF v_purchase.status = 'revealed' OR v_purchase.status = 'credited' THEN
    RETURN jsonb_build_object(
      'status', 'already_revealed',
      'message', 'Questo gratta già è stato rivelato',
      'reward_type', v_purchase.reward_type,
      'reward_value', v_purchase.reward_value
    );
  END IF;
  
  v_tier := v_purchase.tier;

  -- 3. CALCULATE DETERMINISTIC PROGRESS (NO RNG)
  -- Progress is determined by tier, not randomness
  v_progress_gain := CASE v_tier
    WHEN 10 THEN c_tier_10_base
    WHEN 30 THEN c_tier_30_base
    WHEN 50 THEN c_tier_50_base
    ELSE c_tier_10_base
  END;

  -- 4. GET OR CREATE USER PROGRESS METER
  SELECT * INTO v_progress
  FROM public.user_progress_meters
  WHERE user_id = v_user_id AND meter_type = 'scratch';
  
  IF v_progress IS NULL THEN
    v_milestone_level := 0;
  ELSE
    v_milestone_level := v_progress.milestone_level;
  END IF;

  -- 5. CHECK FOR MILESTONE (deterministic threshold)
  IF v_progress IS NOT NULL THEN
    IF (v_progress.progress_points + v_progress_gain) >= ((v_milestone_level + 1) * c_milestone_threshold) THEN
      v_milestone_reached := true;
      v_milestone_level := v_milestone_level + 1;
      v_reward_value := v_tier * v_milestone_level; -- Tier-scaled milestone reward
    END IF;
  END IF;

  -- 6. UPSERT PROGRESS METER
  INSERT INTO public.user_progress_meters (
    user_id, meter_type, progress_points, milestone_level, 
    last_interaction_date, total_interactions, updated_at
  ) VALUES (
    v_user_id, 'scratch',
    v_progress_gain,
    v_milestone_level,
    CURRENT_DATE,
    1,
    now()
  )
  ON CONFLICT (user_id, meter_type) 
  DO UPDATE SET
    progress_points = user_progress_meters.progress_points + v_progress_gain,
    milestone_level = v_milestone_level,
    last_interaction_date = CURRENT_DATE,
    total_interactions = user_progress_meters.total_interactions + 1,
    updated_at = now();

  -- 7. UPDATE PURCHASE RECORD
  UPDATE public.user_scratch_purchases
  SET 
    status = 'revealed',
    reward_type = CASE WHEN v_milestone_reached THEN 'm1u' ELSE 'progress' END,
    reward_value = CASE WHEN v_milestone_reached THEN v_reward_value ELSE v_progress_gain END,
    revealed_at = now()
  WHERE id = p_purchase_id;

  -- 8. AWARD M1U IF MILESTONE REACHED
  IF v_milestone_reached AND v_reward_value > 0 THEN
    SELECT COALESCE(m1_units, 0) INTO v_current_m1u
    FROM public.profiles WHERE id = v_user_id;
    
    UPDATE public.profiles
    SET m1_units = COALESCE(m1_units, 0) + v_reward_value
    WHERE id = v_user_id;
    
    -- Mark as credited
    UPDATE public.user_scratch_purchases
    SET status = 'credited', credited_at = now()
    WHERE id = p_purchase_id;
    
    -- Log award
    INSERT INTO public.prize_awards (
      award_type, prize_id, user_id, source, evidence, status
    ) VALUES (
      'progress_milestone',
      'scratch_milestone_' || v_milestone_level,
      v_user_id,
      'scratch_progress',
      jsonb_build_object(
        'purchase_id', p_purchase_id,
        'tier', v_tier,
        'milestone_level', v_milestone_level,
        'reward_value', v_reward_value
      ),
      'confirmed'
    );
  END IF;

  -- 9. RETURN PROGRESS RESULT (NO WIN/LOSE LANGUAGE)
  RETURN jsonb_build_object(
    'status', 'success',
    'purchase_id', p_purchase_id,
    'tier', v_tier,
    'progress_gain', v_progress_gain,
    'total_progress', COALESCE(v_progress.progress_points, 0) + v_progress_gain,
    'milestone_reached', v_milestone_reached,
    'milestone_level', v_milestone_level,
    'reward_type', CASE WHEN v_milestone_reached THEN 'm1u' ELSE 'progress' END,
    'reward_value', CASE WHEN v_milestone_reached THEN v_reward_value ELSE v_progress_gain END,
    'message', CASE 
      WHEN v_milestone_reached THEN 'Milestone ' || v_milestone_level || ' raggiunta! +' || v_reward_value || ' M1U'
      ELSE 'Rivelazione completata! +' || v_progress_gain || ' punti progressione'
    END
  );
END;
$$;


ALTER FUNCTION "public"."reveal_scratch_progress"("p_purchase_id" "uuid", "p_client_nonce" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reveal_scratch_progress"("p_purchase_id" "uuid", "p_client_nonce" "text") IS 'STORE COMPLIANT: Deterministic scratch reveal. No random(), no win/lose.';



CREATE OR REPLACE FUNCTION "public"."reveal_scratch_ticket"("p_purchase_id" "uuid", "p_client_nonce" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_purchase RECORD;
  v_ticket RECORD;
  v_clue_text TEXT;
  v_actual_payout NUMERIC;
  v_random_clues TEXT[] := ARRAY[
    'Il premio finale si trova in un luogo dove l''acqua incontra la terra.',
    'Cerca dove il sole tramonta sull''orizzonte europeo.',
    'La risposta è nascosta dove le montagne toccano il cielo.',
    'Un antico porto custodisce il segreto che cerchi.',
    'Segui la via delle stelle verso nord-ovest.',
    'Il tesoro riposa dove la storia incontra il presente.',
    'Cerca nell''ombra della torre più famosa.',
    'La chiave si trova dove i fiumi si incontrano.',
    'Un giardino nascosto contiene la verità.',
    'La risposta è scritta nelle pietre millenarie.'
  ];
BEGIN
  -- 1. Verifica autenticazione
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'User not authenticated');
  END IF;
  
  -- 2. Recupera e valida purchase
  SELECT * INTO v_purchase 
  FROM public.user_scratch_purchases 
  WHERE id = p_purchase_id AND user_id = v_user_id
  FOR UPDATE;
  
  IF v_purchase IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Purchase not found or not owned by user');
  END IF;
  
  -- 3. Idempotency: se già rivelato, ritorna risultato esistente
  IF v_purchase.status IN ('revealed', 'credited') THEN
    RETURN jsonb_build_object(
      'status', 'already_revealed',
      'purchase_id', v_purchase.id,
      'reward_type', v_purchase.reward_type,
      'reward_value', v_purchase.reward_value,
      'is_jackpot', (v_purchase.reward_value >= 1000)
    );
  END IF;
  
  -- 4. Verifica nonce
  IF v_purchase.client_nonce != p_client_nonce THEN
    INSERT INTO public.scratch_abuse_logs (user_id, event_type, details)
    VALUES (v_user_id, 'nonce_mismatch', jsonb_build_object(
      'purchase_id', p_purchase_id, 
      'expected_nonce', v_purchase.client_nonce,
      'provided_nonce', p_client_nonce
    ));
    
    RETURN jsonb_build_object('status', 'error', 'message', 'Invalid nonce');
  END IF;
  
  -- 5. Seleziona ticket disponibile
  SELECT * INTO v_ticket
  FROM public.scratch_tickets
  WHERE tier = v_purchase.tier 
    AND is_claimed = false
  ORDER BY 
    is_jackpot ASC, -- Jackpot alla fine
    random()
  LIMIT 1
  FOR UPDATE SKIP LOCKED;
  
  IF v_ticket IS NULL THEN
    UPDATE public.profiles SET m1_units = m1_units + v_purchase.tier WHERE id = v_user_id;
    UPDATE public.user_scratch_purchases SET status = 'failed' WHERE id = p_purchase_id;
    RETURN jsonb_build_object('status', 'error', 'message', 'No tickets available - refunded');
  END IF;
  
  -- 6. Assegna ticket
  UPDATE public.scratch_tickets
  SET is_claimed = true, claimed_by_user = v_user_id, claimed_at = now()
  WHERE id = v_ticket.id;
  
  -- 7. Aggiorna pool
  UPDATE public.scratch_ticket_pools
  SET claimed_tickets = claimed_tickets + 1,
      jackpot_claimed = CASE WHEN v_ticket.is_jackpot THEN true ELSE jackpot_claimed END,
      updated_at = now()
  WHERE id = v_ticket.pool_id;
  
  -- 8. ⭐ CALCOLA PAYOUT (FUNDED JACKPOT)
  IF v_ticket.is_jackpot THEN
    -- Jackpot: usa il funded payout
    v_actual_payout := public.get_funded_jackpot_payout(
      v_purchase.tier, v_user_id, v_ticket.id, p_purchase_id
    );
  ELSE
    -- Non jackpot: payout normale
    v_actual_payout := v_ticket.reward_value;
  END IF;
  
  -- 9. Accredita M1U se > 0
  IF v_ticket.reward_type = 'm1u' AND v_actual_payout > 0 THEN
    UPDATE public.profiles 
    SET m1_units = m1_units + v_actual_payout, updated_at = now()
    WHERE id = v_user_id;
    
    INSERT INTO public.prize_awards (award_type, prize_id, user_id, source, evidence)
    VALUES (
      'scratch',
      'scratch_' || v_ticket.id::text,
      v_user_id,
      'scratch_win_tier_' || v_purchase.tier,
      jsonb_build_object(
        'ticket_id', v_ticket.id,
        'purchase_id', p_purchase_id,
        'tier', v_purchase.tier,
        'original_value', v_ticket.reward_value,
        'actual_payout', v_actual_payout,
        'is_jackpot', v_ticket.is_jackpot,
        'was_funded', v_ticket.is_jackpot
      )
    );
  END IF;
  
  -- 10. CLUE
  IF v_ticket.reward_type = 'clue' THEN
    v_clue_text := v_random_clues[1 + floor(random() * array_length(v_random_clues, 1))::int];
  END IF;
  
  -- 11. Aggiorna purchase
  UPDATE public.user_scratch_purchases
  SET status = 'credited',
      ticket_id = v_ticket.id,
      reward_type = v_ticket.reward_type,
      reward_value = v_actual_payout, -- Usa payout effettivo
      revealed_at = now(),
      credited_at = now()
  WHERE id = p_purchase_id;
  
  -- 12. Analytics
  INSERT INTO public.analytics_events (event_name, user_id, session_id, platform, props, event_version)
  VALUES (
    'scratch_ticket_revealed',
    v_user_id,
    'server',
    'web',
    jsonb_build_object(
      'tier', v_purchase.tier,
      'purchase_id', p_purchase_id,
      'ticket_id', v_ticket.id,
      'reward_type', v_ticket.reward_type,
      'original_value', v_ticket.reward_value,
      'actual_payout', v_actual_payout,
      'is_jackpot', v_ticket.is_jackpot
    ),
    1
  );
  
  RETURN jsonb_build_object(
    'status', 'success',
    'purchase_id', p_purchase_id,
    'ticket_id', v_ticket.id,
    'reward_type', v_ticket.reward_type,
    'reward_value', v_actual_payout, -- Payout effettivo (funded)
    'is_jackpot', v_ticket.is_jackpot,
    'clue_text', v_clue_text
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG 'Error in reveal_scratch_ticket: %', SQLERRM;
    RETURN jsonb_build_object('status', 'error', 'message', 'Internal server error');
END;
$$;


ALTER FUNCTION "public"."reveal_scratch_ticket"("p_purchase_id" "uuid", "p_client_nonce" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_subscription_entitlement"("p_user_id" "uuid", "p_reason" "text" DEFAULT 'expired'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Update entitlements
    UPDATE user_entitlements
    SET 
        sub_status = CASE 
            WHEN p_reason = 'canceled' THEN 'canceled'
            WHEN p_reason = 'refunded' THEN 'canceled'
            ELSE 'expired'
        END,
        updated_at = now()
    WHERE user_id = p_user_id;
    
    -- Update profiles to Base
    UPDATE profiles
    SET 
        subscription_tier = 'Base',
        updated_at = now()
    WHERE id = p_user_id;
    
    -- Log the revocation
    PERFORM log_iap_audit(
        p_user_id,
        'SUBSCRIPTION_REVOKED',
        NULL,
        jsonb_build_object('reason', p_reason)
    );
END;
$$;


