CREATE OR REPLACE FUNCTION "public"."rpc_pulse_decay_tick"("p_decay_percent" numeric DEFAULT 0.5) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current NUMERIC(5,2);
  v_new NUMERIC(5,2);
  v_delta NUMERIC(5,2);
BEGIN
  SELECT value INTO v_current FROM public.pulse_state WHERE id = 1 FOR UPDATE;
  v_new := GREATEST(0, v_current - p_decay_percent);
  v_delta := v_new - v_current;
  
  IF ABS(v_delta) >= 0.2 THEN
    UPDATE public.pulse_state SET value = v_new, updated_at = now() WHERE id = 1;
    PERFORM pg_notify('pulse_channel', json_build_object('value', v_new, 'delta', v_delta, 'threshold', NULL, 'type', 'decay')::text);
  END IF;
  
  RETURN json_build_object('previous_value', v_current, 'new_value', v_new, 'delta', v_delta, 'applied', ABS(v_delta) >= 0.2);
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_decay_tick"("p_decay_percent" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pulse_event_record"("p_user_id" "uuid", "p_type" "text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config RECORD;
  v_weight NUMERIC(6,2);
  v_current NUMERIC(5,2);
  v_new NUMERIC(5,2);
  v_threshold INTEGER := NULL;
  v_device TEXT;
  v_window TIMESTAMPTZ;
  v_abuse_cnt INTEGER;
  v_daily_cnt INTEGER;
  v_last TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_config FROM public.pulse_config_weights WHERE type = p_type AND enabled = true;
  IF NOT FOUND THEN
    RETURN json_build_object('accepted', false, 'error', 'Invalid type');
  END IF;
  
  v_device := p_meta->>'device_hash';
  
  -- Cooldown check
  IF v_config.cooldown_sec > 0 THEN
    SELECT created_at INTO v_last FROM public.pulse_events
    WHERE user_id = p_user_id AND type = p_type ORDER BY created_at DESC LIMIT 1;
    
    IF v_last IS NOT NULL AND EXTRACT(EPOCH FROM (now() - v_last)) < v_config.cooldown_sec THEN
      RETURN json_build_object('accepted', false, 'error', 'Cooldown active');
    END IF;
  END IF;
  
  -- Daily cap check
  IF v_config.per_user_cap_day > 0 THEN
    SELECT COUNT(*) INTO v_daily_cnt FROM public.pulse_events
    WHERE user_id = p_user_id AND type = p_type AND created_at >= CURRENT_DATE;
    
    IF v_daily_cnt >= v_config.per_user_cap_day THEN
      RETURN json_build_object('accepted', false, 'error', 'Daily cap reached');
    END IF;
  END IF;
  
  -- Rate limit check
  v_window := date_trunc('hour', now());
  INSERT INTO public.pulse_abuse_counters (user_id, type, window_start, count)
  VALUES (p_user_id, p_type, v_window, 1)
  ON CONFLICT (user_id, type, window_start) DO UPDATE SET count = pulse_abuse_counters.count + 1
  RETURNING count INTO v_abuse_cnt;
  
  IF v_abuse_cnt > 50 THEN
    RETURN json_build_object('accepted', false, 'error', 'Rate limit exceeded');
  END IF;
  
  -- Dedup check
  IF v_device IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.pulse_events WHERE user_id = p_user_id AND type = p_type AND device_hash = v_device AND created_at > (now() - INTERVAL '5 minutes')) THEN
      RETURN json_build_object('accepted', false, 'error', 'Duplicate event');
    END IF;
  END IF;
  
  v_weight := v_config.weight;
  
  INSERT INTO public.pulse_events (user_id, type, weight, meta, device_hash)
  VALUES (p_user_id, p_type, v_weight, p_meta, v_device);
  
  SELECT value INTO v_current FROM public.pulse_state WHERE id = 1 FOR UPDATE;
  v_new := LEAST(100, v_current + (v_weight * 0.1));
  
  UPDATE public.pulse_state SET value = v_new, updated_at = now() WHERE id = 1;
  
  -- Check thresholds
  FOR v_threshold IN SELECT unnest(ARRAY[25, 50, 75, 100]) LOOP
    IF v_current < v_threshold AND v_new >= v_threshold THEN
      INSERT INTO public.pulse_thresholds_log (threshold, value_snapshot) VALUES (v_threshold, v_new);
      PERFORM pg_notify('pulse_channel', json_build_object('value', v_new, 'delta', (v_new - v_current), 'threshold', v_threshold)::text);
      UPDATE public.pulse_state SET last_threshold = v_threshold WHERE id = 1;
      EXIT;
    END IF;
  END LOOP;
  
  IF v_threshold IS NULL THEN
    PERFORM pg_notify('pulse_channel', json_build_object('value', v_new, 'delta', (v_new - v_current), 'threshold', NULL)::text);
  END IF;
  
  RETURN json_build_object('accepted', true, 'new_value', v_new, 'delta', (v_new - v_current), 'threshold_triggered', v_threshold);
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_event_record"("p_user_id" "uuid", "p_type" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pulse_ritual_can_start"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_pulse numeric(5,2);
  open_ritual_id bigint;
BEGIN
  -- Get current pulse value
  SELECT COALESCE(value, 0) INTO current_pulse FROM pulse_state LIMIT 1;
  
  -- Check for open ritual
  SELECT id INTO open_ritual_id FROM pulse_rituals 
  WHERE ended_at IS NULL 
  ORDER BY started_at DESC 
  LIMIT 1;
  
  IF current_pulse >= 100 AND open_ritual_id IS NULL THEN
    RETURN jsonb_build_object('can', true, 'ritual_id', null, 'pulse_value', current_pulse);
  ELSE
    RETURN jsonb_build_object('can', false, 'ritual_id', open_ritual_id, 'pulse_value', current_pulse);
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_ritual_can_start"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pulse_ritual_claim"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  active_ritual_id bigint;
  reward_pkg jsonb;
  existing_claim_id bigint;
  recent_attempts int;
BEGIN
  -- Verify user is claiming for themselves
  IF p_user != auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: can only claim for yourself';
  END IF;
  
  -- RATE LIMIT: Check recent claim attempts (max 3 per minute)
  SELECT COUNT(*) INTO recent_attempts
  FROM pulse_ritual_claims
  WHERE user_id = p_user
    AND claimed_at > NOW() - INTERVAL '1 minute';
  
  IF recent_attempts >= 3 THEN
    RAISE EXCEPTION 'Rate limit exceeded: max 3 claims per minute';
  END IF;
  
  -- Get active ritual
  SELECT id, reward_package INTO active_ritual_id, reward_pkg
  FROM pulse_rituals 
  WHERE ended_at IS NULL 
  ORDER BY started_at DESC 
  LIMIT 1;
  
  IF active_ritual_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active ritual');
  END IF;
  
  -- Check if already claimed (idempotent) - use INSERT ... ON CONFLICT
  INSERT INTO pulse_ritual_claims (ritual_id, user_id)
  VALUES (active_ritual_id, p_user)
  ON CONFLICT (ritual_id, user_id) DO NOTHING
  RETURNING id INTO existing_claim_id;
  
  -- If no rows inserted, claim already existed
  IF existing_claim_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_claimed', true,
      'reward_package', reward_pkg
    );
  END IF;
  
  -- Successfully created new claim
  RETURN jsonb_build_object(
    'success', true,
    'already_claimed', false,
    'reward_package', reward_pkg
  );
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_ritual_claim"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pulse_ritual_close"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  active_ritual_id bigint;
  new_pulse_value numeric(5,2);
BEGIN
  -- Only service role can close rituals
  IF (auth.jwt() ->> 'role'::text) != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: service role required';
  END IF;
  
  -- Get active ritual
  SELECT id INTO active_ritual_id
  FROM pulse_rituals 
  WHERE ended_at IS NULL 
  ORDER BY started_at DESC 
  LIMIT 1;
  
  IF active_ritual_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active ritual');
  END IF;
  
  -- Scale pulse down by 35%
  UPDATE pulse_state 
  SET value = GREATEST(0, value - 35)
  RETURNING value INTO new_pulse_value;
  
  -- Close ritual
  UPDATE pulse_rituals 
  SET ended_at = now(), scale_applied = true
  WHERE id = active_ritual_id;
  
  -- Log trigger
  INSERT INTO pulse_global_triggers (type, payload)
  VALUES ('ritual_closed', jsonb_build_object('ritual_id', active_ritual_id, 'new_pulse_value', new_pulse_value));
  
  RETURN jsonb_build_object(
    'success', true,
    'ritual_id', active_ritual_id,
    'new_pulse_value', new_pulse_value
  );
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_ritual_close"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pulse_ritual_start"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  new_ritual_id bigint;
  current_pulse numeric(5,2);
  reward_pkg jsonb;
BEGIN
  -- Only service role can start rituals
  IF (auth.jwt() ->> 'role'::text) != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: service role required';
  END IF;
  
  -- Get current pulse
  SELECT COALESCE(value, 0) INTO current_pulse FROM pulse_state LIMIT 1;
  
  -- Generate reward package (cosmetic/narrative only)
  reward_pkg := jsonb_build_object(
    'tier', CASE 
      WHEN current_pulse >= 100 THEN 'legendary'
      WHEN current_pulse >= 75 THEN 'epic'
      WHEN current_pulse >= 50 THEN 'rare'
      ELSE 'common'
    END,
    'items', jsonb_build_array(
      jsonb_build_object('type', 'echo_clue', 'rarity', 'legendary', 'title', 'The Echo Signal'),
      jsonb_build_object('type', 'sigil', 'rarity', 'epic', 'title', 'Pulse Convergence Sigil')
    ),
    'expires_at', (now() + interval '7 days')::text,
    'copy', 'The world listened. The echo answered.'
  );
  
  -- Create ritual
  INSERT INTO pulse_rituals (snapshot, reward_package)
  VALUES (current_pulse, reward_pkg)
  RETURNING id INTO new_ritual_id;
  
  -- Log trigger
  INSERT INTO pulse_global_triggers (type, payload)
  VALUES ('ritual_started', jsonb_build_object('ritual_id', new_ritual_id, 'pulse_value', current_pulse));
  
  RETURN jsonb_build_object(
    'success', true,
    'ritual_id', new_ritual_id,
    'reward_package', reward_pkg
  );
END;
$$;


ALTER FUNCTION "public"."rpc_pulse_ritual_start"() OWNER TO "postgres";


