CREATE OR REPLACE FUNCTION "public"."rpc_units_credit"("_delta" bigint, "_reason" "text" DEFAULT NULL::"text", "_ref_id" "text" DEFAULT NULL::"text", "_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  uid uuid := auth.uid();
  new_balance bigint;
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  -- se c’è già quel ref_id → idempotente: restituisco saldo attuale
  if _ref_id is not null and exists (
    select 1 from public.m1_units_ledger where user_id=uid and ref_id=_ref_id
  ) then
    select balance into new_balance from public.m1_units_balance where user_id=uid;
    return coalesce(new_balance, 0);
  end if;

  perform public._ensure_balance_row(uid);

  -- aggiorna saldo
  update public.m1_units_balance
     set balance = balance + _delta,
         updated_at = now()
   where user_id = uid
   returning balance into new_balance;

  -- registra ledger
  insert into public.m1_units_ledger(user_id, delta, reason, ref_id, meta)
  values (uid, _delta, _reason, _ref_id, coalesce(_meta,'{}'::jsonb));

  return new_balance;
end$$;


ALTER FUNCTION "public"."rpc_units_credit"("_delta" bigint, "_reason" "text", "_ref_id" "text", "_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_agents_for_battle"("search_term" "text", "exclude_user_id" "uuid" DEFAULT NULL::"uuid", "max_results" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "username" "text", "agent_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id,
    COALESCE(p.nickname, p.full_name, p.username, p.agent_code) as username,
    p.agent_code
  FROM profiles p
  WHERE 
    (exclude_user_id IS NULL OR p.id != exclude_user_id)
    AND (
      -- Search in ALL name fields
      p.full_name ILIKE '%' || search_term || '%'
      OR p.nickname ILIKE '%' || search_term || '%'
      OR p.username ILIKE '%' || search_term || '%'
      OR p.agent_code ILIKE '%' || search_term || '%'
    )
  ORDER BY p.full_name NULLS LAST
  LIMIT max_results;
END;
$$;


