    VALUES (v_pool_50, 50, 'm1u', 5000);
  END LOOP;
  
  -- 5 biglietti da 1000 M1U
  FOR v_i IN 1..5 LOOP
    INSERT INTO scratch_tickets (pool_id, tier, reward_type, reward_value)
    VALUES (v_pool_50, 50, 'm1u', 1000);
  END LOOP;
  
