CREATE OR REPLACE FUNCTION "public"."send_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_message_type" "text" DEFAULT 'text'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_sender_id UUID;
  v_message_id UUID;
  v_is_member BOOLEAN;
BEGIN
  v_sender_id := auth.uid();
  IF v_sender_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  SELECT EXISTS(
    SELECT 1 FROM chat_members 
    WHERE conversation_id = p_conversation_id AND user_id = v_sender_id
  ) INTO v_is_member;
  
  IF NOT v_is_member THEN
    RAISE EXCEPTION 'Not a member of this conversation';
  END IF;
  
  INSERT INTO chat_messages (
    conversation_id, sender_id, content_encrypted, message_type, metadata
  ) VALUES (
    p_conversation_id, v_sender_id, encrypt_chat_message(p_content), p_message_type, p_metadata
  ) RETURNING id INTO v_message_id;
  
  UPDATE chat_conversations SET updated_at = NOW() WHERE id = p_conversation_id;
  UPDATE chat_members SET last_read_at = NOW() 
  WHERE conversation_id = p_conversation_id AND user_id = v_sender_id;
  
  RETURN v_message_id;
END;
$$;


ALTER FUNCTION "public"."send_chat_message"("p_conversation_id" "uuid", "p_content" "text", "p_message_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


