CREATE OR REPLACE FUNCTION "public"."trigger_chat_push_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  request_id BIGINT;
  supabase_url TEXT;
  service_key TEXT;
BEGIN
  -- Ottieni le variabili di ambiente
  supabase_url := current_setting('app.settings.supabase_url', true);
  service_key := current_setting('app.settings.service_role_key', true);
  
  -- Se le variabili non sono impostate, usa i valori hardcoded (sostituisci con i tuoi)
  IF supabase_url IS NULL THEN
    supabase_url := 'https://vkjqjndvjbemsfxof.supabase.co';
  END IF;

  -- Chiama la Edge Function via HTTP POST
  SELECT net.http_post(
    url := supabase_url || '/functions/v1/chat-push-notify',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || COALESCE(service_key, current_setting('supabase.service_role_key', true))
    ),
    body := jsonb_build_object(
      'conversation_id', NEW.conversation_id,
      'sender_id', NEW.sender_id,
      'message_type', NEW.message_type
    )
  ) INTO request_id;
  
  RAISE LOG '[CHAT-PUSH-TRIGGER] Request sent: %', request_id;
  
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Non bloccare l'insert se la notifica fallisce
  RAISE LOG '[CHAT-PUSH-TRIGGER] Error (non-blocking): %', SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_chat_push_notify"() OWNER TO "postgres";


