CREATE OR REPLACE FUNCTION "public"."trigger_log_admin_operation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _action TEXT;
  _record_id UUID;
  _old_data JSONB;
  _new_data JSONB;
  _user_id UUID;
BEGIN
  -- Get current user ID
  _user_id := auth.uid();
  
  -- Skip logging if no user authenticated
  IF _user_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Only log if user has admin or moderator role
  IF NOT (
    public.has_role(_user_id, 'admin') OR 
    public.has_role(_user_id, 'moderator')
  ) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Determine action type
  IF (TG_OP = 'INSERT') THEN
    _action := 'INSERT';
    _record_id := NEW.id;
    _new_data := to_jsonb(NEW);
    _old_data := NULL;
  ELSIF (TG_OP = 'UPDATE') THEN
    _action := 'UPDATE';
    _record_id := NEW.id;
    _old_data := to_jsonb(OLD);
    _new_data := to_jsonb(NEW);
  ELSIF (TG_OP = 'DELETE') THEN
    _action := 'DELETE';
    _record_id := OLD.id;
    _old_data := to_jsonb(OLD);
    _new_data := NULL;
  ELSE
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Insert log entry
  INSERT INTO public.admin_audit_logs (
    admin_id,
    action,
    target_table,
    record_id,
    old_data,
    new_data,
    details,
    ip_address,
    user_agent
  ) VALUES (
    _user_id,
    _action || ' on ' || TG_TABLE_NAME,
    TG_TABLE_NAME,
    _record_id,
    _old_data,
    _new_data,
    jsonb_build_object(
      'operation', TG_OP,
      'table', TG_TABLE_NAME,
      'schema', TG_TABLE_SCHEMA,
      'timestamp', NOW()
    ),
    inet_client_addr(),
    current_setting('request.headers', true)::json->>'user-agent'
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to log admin operation on %.%: %', TG_TABLE_SCHEMA, TG_TABLE_NAME, SQLERRM;
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."trigger_log_admin_operation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_log_admin_operation"() IS 'Universal trigger function that logs all INSERT/UPDATE/DELETE operations by admin/moderator users';



