CREATE OR REPLACE FUNCTION "public"."update_personality_quiz_result"("p_user_id" "uuid", "p_quiz_answers" "jsonb", "p_assigned_type" "text", "p_assigned_description" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result JSONB;
BEGIN
  -- Insert or update quiz result
  INSERT INTO public.personality_quiz_results (
    user_id, quiz_answers, assigned_type, assigned_description
  ) VALUES (
    p_user_id, p_quiz_answers, p_assigned_type, p_assigned_description
