CREATE OR REPLACE FUNCTION "public"."update_user_plan_complete"("p_user_id" "uuid", "p_new_plan" "text", "p_event_type" "text" DEFAULT 'upgrade'::"text", "p_old_plan" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_payment_intent_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  access_start_time TIMESTAMP WITH TIME ZONE;
  result JSONB;
BEGIN
  -- Calcola access_starts_at
  access_start_time := public.calculate_access_start_time(p_new_plan);
  
  -- Aggiorna profilo con nuovo piano e accesso
  UPDATE public.profiles
  SET 
    plan = p_new_plan,
    can_access_app = CASE 
      WHEN p_new_plan = 'base' THEN false 
      ELSE true 
    END,
    access_starts_at = access_start_time,
    last_plan_change = now(),
    updated_at = now()
  WHERE id = p_user_id;
  
  -- Registra evento nella tabella eventi piano
  INSERT INTO public.user_plan_events (
    user_id, 
    plan, 
    event_type, 
    old_plan, 
    amount, 
    stripe_payment_intent_id,
    metadata
  ) VALUES (
    p_user_id,
    p_new_plan,
    p_event_type,
    p_old_plan,
    p_amount,
    p_payment_intent_id,
    jsonb_build_object(
      'access_starts_at', access_start_time,
      'can_access_app', CASE WHEN p_new_plan = 'base' THEN false ELSE true END,
      'processed_at', now()
    )
  );
  
  -- Sincronizza permessi
  PERFORM public.sync_user_permissions(p_user_id);
  
  -- Costruisci risultato
  result := jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'plan', p_new_plan,
    'access_starts_at', access_start_time,
    'event_type', p_event_type,
    'updated_at', now()
  );
  
  RETURN result;
END;
$$;


