    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.ai_docs (title, text, tags, source, url, updated_at)
  values (p_title, p_text, p_tags, p_source, p_url, now())
  on conflict (url) do update
    set title = excluded.title,
        text = excluded.text,
        tags = excluded.tags,
        source = excluded.source,
        updated_at = now()
  returning id into v_id;
  return v_id;
end$$;


