CREATE OR REPLACE FUNCTION "public"."upsert_dna_mind_fractal_session"("p_seed" bigint, "p_moves" integer, "p_time_spent" integer, "p_completion_ratio" double precision) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_clamped_ratio FLOAT;
BEGIN
  -- Clamp completion_ratio to [0, 1]
  v_clamped_ratio := GREATEST(0.0, LEAST(1.0, p_completion_ratio));
  
  -- Validate non-negative values
  IF p_moves < 0 OR p_time_spent < 0 THEN
    RAISE EXCEPTION 'Moves and time_spent must be non-negative';
  END IF;
  
  -- Upsert atomically by (user_id, seed)
  INSERT INTO dna_mind_fractal_sessions (
    user_id, 
    seed, 
    moves, 
    time_spent, 
    completion_ratio
  )
  VALUES (
    auth.uid(), 
    p_seed, 
    p_moves, 
    p_time_spent, 
    v_clamped_ratio
  )
  ON CONFLICT (user_id, seed)
  DO UPDATE SET
    moves = EXCLUDED.moves,
    time_spent = EXCLUDED.time_spent,
    completion_ratio = EXCLUDED.completion_ratio,
    updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."upsert_dna_mind_fractal_session"("p_seed" bigint, "p_moves" integer, "p_time_spent" integer, "p_completion_ratio" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_dna_mind_link"("p_user_id" "uuid", "p_seed" bigint, "p_a" integer, "p_b" integer, "p_theme" "text", "p_intensity" double precision DEFAULT 1.0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_links INTEGER;
  v_theme_links INTEGER;
  v_milestone_added BOOLEAN := false;
  v_milestone_level INTEGER := 0;
BEGIN
  -- Insert the link
  INSERT INTO dna_mind_links (user_id, seed, node_a, node_b, theme, intensity)
  VALUES (p_user_id, p_seed, p_a, p_b, p_theme, p_intensity);

  -- Count total links for this seed
  SELECT COUNT(*) INTO v_total_links
  FROM dna_mind_links
  WHERE user_id = p_user_id AND seed = p_seed;

  -- Count links for this theme
  SELECT COUNT(*) INTO v_theme_links
  FROM dna_mind_links
  WHERE user_id = p_user_id AND seed = p_seed AND theme = p_theme;

  -- Check if milestone reached (every 5 links of same theme)
  IF v_theme_links % 5 = 0 THEN
    v_milestone_level := v_theme_links / 5;
    
    -- Insert or update milestone
    INSERT INTO dna_mind_milestones (user_id, seed, theme, level)
    VALUES (p_user_id, p_seed, p_theme, v_milestone_level)
    ON CONFLICT (user_id, seed, theme, level) DO NOTHING;
    
    v_milestone_added := true;
  END IF;

  -- Return summary
  RETURN jsonb_build_object(
    'total_links', v_total_links,
    'theme_links', v_theme_links,
    'milestone_added', v_milestone_added,
    'milestone_level', v_milestone_level
  );
END;
$$;


ALTER FUNCTION "public"."upsert_dna_mind_link"("p_user_id" "uuid", "p_seed" bigint, "p_a" integer, "p_b" integer, "p_theme" "text", "p_intensity" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_dna_mind_link"("p_user_id" "uuid", "p_seed" bigint, "p_a" integer, "p_b" integer, "p_theme" "text", "p_intensity" double precision) IS 'Insert link and calculate milestones';



CREATE OR REPLACE FUNCTION "public"."upsert_fcm_subscription"("p_user_id" "uuid", "p_token" "text", "p_platform" "text", "p_device_info" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result_record RECORD;
BEGIN
  -- Validazione base - no pattern troppo rigidi
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'user_id è richiesto');
  END IF;
  
  IF p_token IS NULL OR length(trim(p_token)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'token deve essere almeno 10 caratteri');
  END IF;
  
  -- Normalizza platform - accetta più valori
  p_platform := lower(trim(coalesce(p_platform, 'web')));
  IF p_platform NOT IN ('ios', 'android', 'desktop', 'web', 'unknown') THEN
    p_platform := 'web';
  END IF;
  
  -- Upsert semplice senza validazioni pattern
  INSERT INTO public.fcm_subscriptions (user_id, token, platform, device_info, is_active, created_at, updated_at)
  VALUES (p_user_id, p_token, p_platform, COALESCE(p_device_info, '{}'::jsonb), true, now(), now())
  ON CONFLICT (token) 
  DO UPDATE SET
    user_id = EXCLUDED.user_id,
    platform = EXCLUDED.platform,
    device_info = EXCLUDED.device_info,
    is_active = true,
    updated_at = now()
  RETURNING * INTO result_record;
  
  RETURN jsonb_build_object(
    'success', true, 
    'id', result_record.id,
    'token_prefix', left(result_record.token, 30) || '...',
    'platform', result_record.platform,
    'created_at', result_record.created_at,
    'message', 'Token salvato con successo'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false, 
    'error', SQLERRM,
    'sqlstate', SQLSTATE,
    'detail', CASE 
      WHEN SQLSTATE = '23505' THEN 'Token già esistente - aggiornato'
      WHEN SQLSTATE = '23502' THEN 'Campo obbligatorio mancante'
      WHEN SQLSTATE = '23514' THEN 'Errore validazione: ' || SQLERRM
      ELSE 'Errore database: ' || SQLERRM
    END
  );
END;
$$;


ALTER FUNCTION "public"."upsert_fcm_subscription"("p_user_id" "uuid", "p_token" "text", "p_platform" "text", "p_device_info" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_notification_counter"("p_user_id" "uuid", "p_delta" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_count INTEGER;
BEGIN
  INSERT INTO public.notification_counters (user_id, unread_count, updated_at)
  VALUES (p_user_id, GREATEST(0, p_delta), now())
  ON CONFLICT (user_id) 
  DO UPDATE SET 
    unread_count = GREATEST(0, notification_counters.unread_count + p_delta),
    updated_at = now()
  RETURNING unread_count INTO new_count;
  
  RETURN new_count;
END;
$$;


ALTER FUNCTION "public"."upsert_notification_counter"("p_user_id" "uuid", "p_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_prize_category"("cat_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE 
  cid uuid;
BEGIN
  -- Cerca categoria esistente
  SELECT id INTO cid 
  FROM public.prize_categories 
  WHERE lower(name) = lower(cat_name) 
  LIMIT 1;
  
  -- Se non esiste, creala
  IF cid IS NULL THEN
    INSERT INTO public.prize_categories(name, created_by) 
    VALUES (cat_name, auth.uid()) 
    RETURNING id INTO cid;
  END IF;
  
  RETURN cid;
END;
$$;


ALTER FUNCTION "public"."upsert_prize_category"("cat_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_user_position"("uid" "uuid", "lat" double precision, "lng" double precision) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  insert into geo_push.user_positions (user_id, lat, lng, updated_at)
  values (uid, lat, lng, now())
  on conflict (user_id)
  do update set
    lat = excluded.lat,
    lng = excluded.lng,
    updated_at = now();
$$;


