CREATE TABLE IF NOT EXISTS "public"."admin_audit_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "admin_id" "uuid" NOT NULL,
    "action" "text" NOT NULL,
    "target_user_id" "uuid",
    "target_table" "text",
    "record_id" "uuid",
    "old_data" "jsonb",
    "new_data" "jsonb",
    "details" "jsonb" DEFAULT '{}'::"jsonb",
    "ip_address" "inet",
    "user_agent" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."admin_audit_logs" OWNER TO "postgres";


COMMENT ON TABLE "public"."admin_audit_logs" IS 'Audit trail for admin/moderator operations on sensitive tables';



COMMENT ON COLUMN "public"."admin_audit_logs"."admin_id" IS 'User who performed the operation';



COMMENT ON COLUMN "public"."admin_audit_logs"."action" IS 'Operation performed (e.g., INSERT on prizes)';



COMMENT ON COLUMN "public"."admin_audit_logs"."target_table" IS 'Table that was modified';



COMMENT ON COLUMN "public"."admin_audit_logs"."record_id" IS 'UUID of the affected record';



COMMENT ON COLUMN "public"."admin_audit_logs"."old_data" IS 'Previous state of record (UPDATE/DELETE only)';



COMMENT ON COLUMN "public"."admin_audit_logs"."new_data" IS 'New state of record (INSERT/UPDATE only)';



CREATE OR REPLACE VIEW "public"."admin_audit_logs_readable" AS
 SELECT "al"."id",
    "al"."action",
    "al"."target_table",
    "al"."record_id",
    "au"."email" AS "admin_email",
    COALESCE("tu"."email", (("al"."target_user_id")::"text")::character varying) AS "target_email",
    "al"."details",
    "al"."old_data",
    "al"."new_data",
    "al"."ip_address",
    "al"."user_agent",
    "al"."created_at",
        CASE
            WHEN (("al"."old_data" IS NOT NULL) AND ("al"."new_data" IS NOT NULL)) THEN ( SELECT "jsonb_object_agg"("diff"."key", "diff"."value") AS "jsonb_object_agg"
               FROM ( SELECT "jsonb_each"."key",
                        ("al"."new_data" ->> "jsonb_each"."key") AS "value"
                       FROM "jsonb_each"("al"."new_data") "jsonb_each"("key", "value")
                      WHERE (("al"."new_data" ->> "jsonb_each"."key") IS DISTINCT FROM ("al"."old_data" ->> "jsonb_each"."key"))) "diff")
            ELSE NULL::"jsonb"
        END AS "changed_fields"
   FROM (("public"."admin_audit_logs" "al"
     LEFT JOIN "auth"."users" "au" ON (("au"."id" = "al"."admin_id")))
     LEFT JOIN "auth"."users" "tu" ON (("tu"."id" = "al"."target_user_id")))
  ORDER BY "al"."created_at" DESC;


ALTER TABLE "public"."admin_audit_logs_readable" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_audit_logs_readable" IS 'Human-readable view of admin audit logs with email addresses and field diffs';



CREATE OR REPLACE VIEW "public"."admin_audit_logs_stats" AS
 SELECT "date_trunc"('day'::"text", "admin_audit_logs"."created_at") AS "log_date",
    "admin_audit_logs"."target_table",
    "split_part"("admin_audit_logs"."action", ' '::"text", 1) AS "operation",
    "count"(*) AS "operation_count",
    "count"(DISTINCT "admin_audit_logs"."admin_id") AS "unique_admins",
    "min"("admin_audit_logs"."created_at") AS "first_operation",
    "max"("admin_audit_logs"."created_at") AS "last_operation"
   FROM "public"."admin_audit_logs"
  WHERE ("admin_audit_logs"."target_table" IS NOT NULL)
  GROUP BY ("date_trunc"('day'::"text", "admin_audit_logs"."created_at")), "admin_audit_logs"."target_table", ("split_part"("admin_audit_logs"."action", ' '::"text", 1))
  ORDER BY ("date_trunc"('day'::"text", "admin_audit_logs"."created_at")) DESC, ("count"(*)) DESC;


ALTER TABLE "public"."admin_audit_logs_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_audit_logs_stats" IS 'Daily statistics of admin operations by table and operation type';



