CREATE OR REPLACE VIEW "public"."admin_kpi_snapshot" AS
 SELECT ( SELECT "count"(DISTINCT "analytics_events"."user_id") AS "count"
           FROM "public"."analytics_events"
          WHERE ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval))) AS "active_users_24h",
    ( SELECT "count"(DISTINCT "analytics_events"."user_id") AS "count"
           FROM "public"."analytics_events"
          WHERE ("analytics_events"."server_ts" > ("now"() - '7 days'::interval))) AS "active_users_7d",
    ( SELECT "count"(DISTINCT "analytics_events"."anon_id") AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."user_id" IS NULL) AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "anon_users_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events") AS "total_events",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval))) AS "events_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE ("analytics_events"."event_name" = 'final_shot_attempted'::"text")) AS "final_shot_attempts",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE ("analytics_events"."event_name" = 'final_shot_won'::"text")) AS "final_shot_wins",
    ( SELECT "final_shoot_winners"."winner_user_id"
           FROM "public"."final_shoot_winners"
          ORDER BY "final_shoot_winners"."won_at" DESC
         LIMIT 1) AS "last_final_winner_id",
    ( SELECT "final_shoot_winners"."won_at"
           FROM "public"."final_shoot_winners"
          ORDER BY "final_shoot_winners"."won_at" DESC
         LIMIT 1) AS "last_final_win_at",
    ( SELECT "count"(*) AS "count"
           FROM "public"."prize_awards"
          WHERE ("prize_awards"."award_type" = 'secondary'::"text")) AS "secondary_prizes_awarded",
    ( SELECT "count"(*) AS "count"
           FROM "public"."prize_awards"
          WHERE ("prize_awards"."award_type" = 'final'::"text")) AS "final_prizes_awarded",
    ( SELECT "count"(*) AS "count"
           FROM "public"."secondary_prize_claims") AS "secondary_claims_total",
    ( SELECT "count"(*) AS "count"
           FROM "public"."final_prize_claims") AS "final_claims_total",
    ( SELECT "count"(*) AS "count"
           FROM "public"."prize_awards"
          WHERE ("prize_awards"."award_type" = 'marker'::"text")) AS "marker_rewards_claimed",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'login_success'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "logins_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'signup_completed'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "signups_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'screen_viewed'::"text") AND (("analytics_events"."props" ->> 'route'::"text") = ANY (ARRAY['/landing'::"text", '/'::"text"])) AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "landing_views_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'screen_viewed'::"text") AND (("analytics_events"."props" ->> 'route'::"text") = '/spectator'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "spectator_views_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = ANY (ARRAY['daily_streak_started'::"text", 'daily_streak_incremented'::"text"])) AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "streak_checkins_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'daily_streak_broken'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "streak_breaks_24h",
    ( SELECT "count"(DISTINCT "analytics_events"."user_id") AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = ANY (ARRAY['daily_streak_started'::"text", 'daily_streak_incremented'::"text"])) AND ("analytics_events"."server_ts" > ("now"() - '7 days'::interval)))) AS "streak_active_users_7d",
    ( SELECT "count"(*) AS "count"
           FROM "public"."wheel_spins"
          WHERE ("wheel_spins"."created_at" > ("now"() - '24:00:00'::interval))) AS "wheel_spins_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."wheel_spins"
          WHERE (("wheel_spins"."reward_type" = ANY (ARRAY['m1u'::"text", 'pe'::"text", 'clue'::"text"])) AND ("wheel_spins"."reward_value" > 0) AND ("wheel_spins"."created_at" > ("now"() - '24:00:00'::interval)))) AS "wheel_rewards_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."wheel_spins") AS "wheel_spins_total",
    ( SELECT "sum"("wheel_spins"."reward_value") AS "sum"
           FROM "public"."wheel_spins"
          WHERE ("wheel_spins"."reward_type" = 'm1u'::"text")) AS "wheel_m1u_distributed",
    ( SELECT "sum"("wheel_spins"."reward_value") AS "sum"
           FROM "public"."wheel_spins"
          WHERE ("wheel_spins"."reward_type" = 'pe'::"text")) AS "wheel_pe_distributed",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'minigame_started'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "minigame_runs_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'minigame_completed'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "minigame_completions_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."analytics_events"
          WHERE (("analytics_events"."event_name" = 'minigame_abandoned'::"text") AND ("analytics_events"."server_ts" > ("now"() - '24:00:00'::interval)))) AS "minigame_abandons_24h",
    ( SELECT "round"(((( SELECT ("count"(*))::numeric AS "count"
                   FROM "public"."analytics_events"
                  WHERE (("analytics_events"."event_name" = 'minigame_completed'::"text") AND ("analytics_events"."server_ts" > ("now"() - '7 days'::interval)))) / NULLIF(( SELECT ("count"(*))::numeric AS "count"
                   FROM "public"."analytics_events"
                  WHERE (("analytics_events"."event_name" = 'minigame_started'::"text") AND ("analytics_events"."server_ts" > ("now"() - '7 days'::interval)))), (0)::numeric)) * (100)::numeric), 2) AS "round") AS "minigame_completion_rate_7d",
    ( SELECT "max"("analytics_events"."server_ts") AS "max"
           FROM "public"."analytics_events") AS "last_event_ts",
    "now"() AS "snapshot_ts";


ALTER TABLE "public"."admin_kpi_snapshot" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_kpi_snapshot" IS 'M1SSION™ Admin KPI Snapshot v2 - Extended with Streak, Wheel, Minigames metrics (17/01/2026)';



