CREATE MATERIALIZED VIEW "public"."battle_metrics" AS
 SELECT "battle_participants"."user_id",
    "count"(*) AS "total_battles",
    "sum"(
        CASE
            WHEN "battle_participants"."is_winner" THEN 1
            ELSE 0
        END) AS "wins",
    "sum"(
        CASE
            WHEN (NOT "battle_participants"."is_winner") THEN 1
            ELSE 0
        END) AS "losses",
    "round"("avg"("battle_participants"."reaction_ms"), 2) AS "avg_reaction_ms",
    "min"("battle_participants"."reaction_ms") AS "fastest_reaction_ms",
    "max"("battle_participants"."reaction_ms") AS "slowest_reaction_ms",
    "round"(((("sum"(
        CASE
            WHEN "battle_participants"."is_winner" THEN 1
            ELSE 0
        END))::numeric / (GREATEST("count"(*), (1)::bigint))::numeric) * (100)::numeric), 2) AS "win_rate_percentage"
   FROM "public"."battle_participants"
  WHERE ("battle_participants"."reaction_ms" IS NOT NULL)
  GROUP BY "battle_participants"."user_id"
  WITH NO DATA;


