CREATE TABLE IF NOT EXISTS "public"."battles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "arena_name" "text",
    "arena_lat" double precision,
    "arena_lng" double precision,
    "stake_type" "text" DEFAULT 'm1u'::"text" NOT NULL,
    "stake_amount" numeric NOT NULL,
    "stake_percentage" integer NOT NULL,
    "creator_id" "uuid" NOT NULL,
    "opponent_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_at" timestamp with time zone,
    "countdown_start_at" timestamp with time zone,
    "flash_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:05:00'::interval) NOT NULL,
    "winner_id" "uuid",
    "creator_tap_at" timestamp with time zone,
    "opponent_tap_at" timestamp with time zone,
    "creator_reaction_ms" integer,
    "opponent_reaction_ms" integer,
    "creator_ping_ms" integer,
    "opponent_ping_ms" integer,
    "server_compensation_ms" integer,
    "creator_ghost_until" timestamp with time zone,
    "opponent_ghost_until" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "battles_stake_amount_check" CHECK (("stake_amount" >= (0)::numeric)),
    CONSTRAINT "battles_stake_percentage_check" CHECK (("stake_percentage" = ANY (ARRAY[25, 50, 75]))),
    CONSTRAINT "battles_stake_type_check" CHECK (("stake_type" = ANY (ARRAY['m1u'::"text", 'pulse_energy'::"text", 'energy'::"text", 'buzz'::"text", 'clue'::"text"]))),
    CONSTRAINT "battles_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'ready'::"text", 'countdown'::"text", 'active'::"text", 'resolved'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."battles" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."battle_top_agents" AS
 SELECT "p"."id",
    "count"(
        CASE
            WHEN ("b"."winner_id" = "p"."id") THEN 1
            ELSE NULL::integer
        END) AS "wins",
    1000 AS "elo",
    "p"."username",
    "p"."agent_code"
   FROM ("public"."profiles" "p"
     LEFT JOIN "public"."battles" "b" ON (((("b"."creator_id" = "p"."id") OR ("b"."opponent_id" = "p"."id")) AND ("b"."status" = 'completed'::"text"))))
  GROUP BY "p"."id", "p"."username", "p"."agent_code"
  ORDER BY ("count"(
        CASE
            WHEN ("b"."winner_id" = "p"."id") THEN 1
            ELSE NULL::integer
        END)) DESC
 LIMIT 50;


ALTER TABLE "public"."battle_top_agents" OWNER TO "postgres";


