CREATE MATERIALIZED VIEW "public"."current_week_leaderboard" AS
 SELECT "wl"."user_id",
    "wl"."total_xp",
    "wl"."rank",
    "p"."agent_code",
    "p"."avatar_url",
    EXTRACT(week FROM CURRENT_DATE) AS "current_week",
    EXTRACT(year FROM CURRENT_DATE) AS "current_year"
   FROM ("public"."weekly_leaderboard" "wl"
     JOIN "public"."profiles" "p" ON (("p"."id" = "wl"."user_id")))
  WHERE ((("wl"."week_number")::numeric = EXTRACT(week FROM CURRENT_DATE)) AND (("wl"."year")::numeric = EXTRACT(year FROM CURRENT_DATE)))
  ORDER BY "wl"."total_xp" DESC
 LIMIT 100
  WITH NO DATA;


ALTER TABLE "public"."current_week_leaderboard" OWNER TO "postgres";


