    "m"."title",
    "m"."lat",
    "m"."lng"
   FROM "public"."markers" "m"
  WHERE (COALESCE("m"."active", true) = true)
UNION ALL
 SELECT "q"."id",
    COALESCE("q"."location_name", 'QR Marker'::"text") AS "title",
    "q"."lat",
    "q"."lng"
   FROM "public"."qr_buzz_codes" "q"
  WHERE (((COALESCE("q"."is_used", false) = false) AND ("q"."expires_at" IS NULL)) OR ("q"."expires_at" > "now"()));


