CREATE OR REPLACE VIEW "public"."mission_status_v" AS
 SELECT "m"."id",
    "m"."title",
    "m"."description",
    "m"."publication_date",
    "m"."status",
    "m"."created_at",
    "m"."updated_at",
    "m"."prize_id",
    "m"."start_date",
    "m"."end_date",
    "m"."prize_description",
    "m"."prize_value",
    "m"."prize_image_url",
    (("m"."status" = 'published'::"text") OR (("m"."status" = 'scheduled'::"text") AND ("m"."start_date" <= "now"()))) AS "is_live"
   FROM "public"."missions" "m";


