CREATE TABLE IF NOT EXISTS "public"."prize_clues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prize_id" "uuid" NOT NULL,
    "week" integer DEFAULT 1 NOT NULL,
    "clue_type" "text" DEFAULT 'location'::"text" NOT NULL,
    "title_it" "text" NOT NULL,
    "title_en" "text",
    "title_fr" "text",
    "description_it" "text" NOT NULL,
    "description_en" "text",
    "description_fr" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "clue_category" "text" DEFAULT 'location'::"text" NOT NULL,
    "is_fake" boolean DEFAULT false,
    "difficulty_level" integer DEFAULT 1,
    "clue_text" "text" DEFAULT ''::"text" NOT NULL,
    "order_index" integer DEFAULT 0,
    "is_active" boolean DEFAULT true,
    "tier" smallint DEFAULT 1 NOT NULL,
    "is_decoy" boolean DEFAULT false NOT NULL,
    "batch_id" "text",
    "type" "text" DEFAULT 'LOCATION'::"text",
    "difficulty" "text" DEFAULT 'MEDIUM'::"text",
    "cipher_type" "text",
    CONSTRAINT "prize_clues_cipher_type_check" CHECK ((("cipher_type" IS NULL) OR ("cipher_type" = ANY (ARRAY['ANAGRAM'::"text", 'ACROSTIC'::"text", 'CAESAR'::"text", 'SEMANTIC_SHIFT'::"text", 'NUMERIC_CODE'::"text", 'SYMBOLIC'::"text", 'NONE'::"text"])))),
    CONSTRAINT "prize_clues_clue_category_chk" CHECK (("lower"(TRIM(BOTH FROM "clue_category")) = ANY (ARRAY['prize'::"text", 'location'::"text"]))),
    CONSTRAINT "prize_clues_clue_type_chk" CHECK (("lower"(TRIM(BOTH FROM "clue_type")) = ANY (ARRAY['prize'::"text", 'location'::"text"]))),
    CONSTRAINT "prize_clues_clue_type_valid" CHECK ((("clue_type" IS NULL) OR ("clue_type" = ANY (ARRAY['location'::"text", 'prize'::"text"])))),
    CONSTRAINT "prize_clues_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['LOW'::"text", 'MEDIUM'::"text", 'HIGH'::"text", 'INTELLIGENCE'::"text"]))),
    CONSTRAINT "prize_clues_tier_valid" CHECK ((("tier" >= 1) AND ("tier" <= 5))),
    CONSTRAINT "prize_clues_type_check" CHECK (("type" = ANY (ARRAY['LOCATION'::"text", 'PRIZE'::"text"]))),
    CONSTRAINT "prize_clues_week_valid" CHECK ((("week" >= 1) AND ("week" <= 4)))
);


ALTER TABLE "public"."prize_clues" OWNER TO "postgres";


