    "crash_point" numeric(6,2) NOT NULL,
    "cashout_multiplier" numeric(6,2),
    "payout" numeric(10,2) DEFAULT 0,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"(),
    "ended_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "pulse_breaker_rounds_bet_amount_check" CHECK ((("bet_amount" >= (1)::numeric) AND ("bet_amount" <= (100)::numeric))),
    CONSTRAINT "pulse_breaker_rounds_bet_currency_check" CHECK (("bet_currency" = ANY (ARRAY['PE'::"text", 'M1U'::"text"]))),
    CONSTRAINT "pulse_breaker_rounds_crash_point_check" CHECK (("crash_point" >= 1.00)),
    CONSTRAINT "pulse_breaker_rounds_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'cashed_out'::"text", 'crashed'::"text"])))
);


