CREATE OR REPLACE VIEW "public"."pulse_breaker_suspicious_activity" AS
 SELECT "r"."user_id",
    "p"."username",
    "count"(*) AS "total_rounds_last_hour",
    "sum"("r"."payout") AS "total_payout_last_hour",
    "max"("r"."payout") AS "max_single_payout",
    "avg"("r"."cashout_multiplier") AS "avg_cashout_mult"
   FROM ("public"."pulse_breaker_rounds" "r"
     LEFT JOIN "public"."profiles" "p" ON (("r"."user_id" = "p"."id")))
  WHERE ("r"."created_at" > ("now"() - '01:00:00'::interval))
  GROUP BY "r"."user_id", "p"."username"
 HAVING (("count"(*) > 20) OR ("sum"("r"."payout") > (500)::numeric))
  ORDER BY ("sum"("r"."payout")) DESC;


ALTER TABLE "public"."pulse_breaker_suspicious_activity" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pulse_breaker_user_stats" AS
 SELECT "pulse_breaker_rounds"."user_id",
    "count"(*) AS "total_rounds",
    "count"(*) FILTER (WHERE ("pulse_breaker_rounds"."status" = 'cashed_out'::"text")) AS "wins",
    "count"(*) FILTER (WHERE ("pulse_breaker_rounds"."status" = 'crashed'::"text")) AS "losses",
    "sum"("pulse_breaker_rounds"."bet_amount") AS "total_bet",
    "sum"("pulse_breaker_rounds"."payout") AS "total_payout",
    ("sum"("pulse_breaker_rounds"."payout") - "sum"("pulse_breaker_rounds"."bet_amount")) AS "net_profit",
    "max"("pulse_breaker_rounds"."cashout_multiplier") AS "best_multiplier",
    "max"("pulse_breaker_rounds"."crash_point") AS "highest_crash_seen"
   FROM "public"."pulse_breaker_rounds"
  WHERE ("pulse_breaker_rounds"."status" <> 'running'::"text")
  GROUP BY "pulse_breaker_rounds"."user_id";


ALTER TABLE "public"."pulse_breaker_user_stats" OWNER TO "postgres";


