CREATE OR REPLACE VIEW "public"."pulse_leaderboard_daily" AS
 SELECT "p"."full_name",
    "p"."agent_code",
    "count"("pe"."id") AS "event_count",
    "sum"("pe"."weight") AS "total_contribution",
    "max"("pe"."created_at") AS "last_contribution"
   FROM ("public"."pulse_events" "pe"
     JOIN "public"."profiles" "p" ON (("p"."id" = "pe"."user_id")))
  WHERE ("pe"."created_at" >= CURRENT_DATE)
  GROUP BY "p"."id", "p"."full_name", "p"."agent_code"
  ORDER BY ("sum"("pe"."weight")) DESC
 LIMIT 100;


ALTER TABLE "public"."pulse_leaderboard_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pulse_leaderboard_weekly" AS
 SELECT "p"."full_name",
    "p"."agent_code",
    "count"("pe"."id") AS "event_count",
    "sum"("pe"."weight") AS "total_contribution",
    "max"("pe"."created_at") AS "last_contribution"
   FROM ("public"."pulse_events" "pe"
     JOIN "public"."profiles" "p" ON (("p"."id" = "pe"."user_id")))
  WHERE ("pe"."created_at" >= (CURRENT_DATE - '7 days'::interval))
  GROUP BY "p"."id", "p"."full_name", "p"."agent_code"
  ORDER BY ("sum"("pe"."weight")) DESC
 LIMIT 100;


