CREATE OR REPLACE VIEW "public"."v_agent_profile" AS
 SELECT "profiles"."id" AS "user_id",
    COALESCE("profiles"."agent_code", 'AG-UNKNOWN'::"text") AS "agent_code",
    COALESCE("profiles"."full_name", 'Agent'::"text") AS "display_name",
    COALESCE("profiles"."subscription_plan", 'base'::"text") AS "plan_type",
    "profiles"."updated_at"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"());


ALTER TABLE "public"."v_agent_profile" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_agent_profile" IS 'Agent basic profile - READ ONLY';



CREATE OR REPLACE VIEW "public"."v_agent_status" AS
 SELECT "p"."id" AS "user_id",
    COALESCE("p"."agent_code", 'AG-UNKNOWN'::"text") AS "agent_code",
    1 AS "current_week",
    0 AS "progress_ratio"
   FROM "public"."profiles" "p"
  WHERE ("p"."id" = "auth"."uid"());


ALTER TABLE "public"."v_agent_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_agent_status" IS 'Agent status - READ ONLY';



CREATE OR REPLACE VIEW "public"."v_dna_mind_links_recent" WITH ("security_invoker"='on') AS
 SELECT "dna_mind_links"."id",
    "dna_mind_links"."user_id",
    "dna_mind_links"."seed",
    "dna_mind_links"."node_a",
    "dna_mind_links"."node_b",
    "dna_mind_links"."theme",
    "dna_mind_links"."intensity",
    "dna_mind_links"."created_at"
   FROM "public"."dna_mind_links"
  WHERE ("dna_mind_links"."user_id" = "auth"."uid"())
  ORDER BY "dna_mind_links"."created_at" DESC
 LIMIT 50;


ALTER TABLE "public"."v_dna_mind_links_recent" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_online_agents" AS
 SELECT "online_agents"."user_id",
    "online_agents"."lat",
    "online_agents"."lng",
    "online_agents"."updated_at",
    "online_agents"."status",
    "online_agents"."accuracy"
   FROM "public"."online_agents";


ALTER TABLE "public"."v_online_agents" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pref_users" AS
 SELECT DISTINCT "np"."user_id"
   FROM "public"."notification_preferences" "np"
  WHERE (("np"."enabled" = true) AND ("np"."user_id" IS NOT NULL) AND (("np"."user_id")::"text" !~* '^(null)?$'::"text") AND (("np"."user_id")::"text" ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::"text"))
  ORDER BY "np"."user_id";


ALTER TABLE "public"."v_pref_users" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_units_me" AS
 SELECT "b"."user_id",
    "b"."balance",
    "b"."updated_at"
   FROM "public"."m1_units_balance" "b"
  WHERE ("b"."user_id" = "auth"."uid"());


ALTER TABLE "public"."v_units_me" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_user_intel_clues" AS
 SELECT "c"."id",
    "c"."title",
    "c"."description",
    "c"."created_at"
   FROM "public"."clues" "c"
  WHERE (EXISTS ( SELECT 1
           FROM "public"."user_clues" "uc"
          WHERE (("uc"."clue_id" = "c"."id") AND ("uc"."user_id" = "auth"."uid"()))));


ALTER TABLE "public"."v_user_intel_clues" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_user_m1_units" AS
 SELECT "u"."id" AS "user_id",
    COALESCE("m"."balance", (0)::bigint) AS "balance",
    "m"."updated_at"
   FROM ("auth"."users" "u"
     LEFT JOIN "public"."user_m1_units" "m" ON (("m"."user_id" = "u"."id")));


ALTER TABLE "public"."v_user_m1_units" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_user_m1u_summary" AS
 SELECT "u"."id" AS "user_id",
    COALESCE("m"."balance", (0)::bigint) AS "balance",
    (COALESCE("sum"(
        CASE
            WHEN ("e"."delta" > 0) THEN "e"."delta"
            ELSE NULL::bigint
        END), (0)::numeric))::bigint AS "earned",
    (COALESCE("sum"(
        CASE
            WHEN ("e"."delta" < 0) THEN (- "e"."delta")
            ELSE NULL::bigint
        END), (0)::numeric))::bigint AS "spent",
    "max"("m"."updated_at") AS "updated_at"
   FROM (("auth"."users" "u"
     LEFT JOIN "public"."user_m1_units" "m" ON (("m"."user_id" = "u"."id")))
     LEFT JOIN "public"."user_m1_units_events" "e" ON (("e"."user_id" = "u"."id")))
  GROUP BY "u"."id", "m"."balance";


ALTER TABLE "public"."v_user_m1u_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_user_resolved_tags" AS
 WITH "expanded_tags" AS (
         SELECT "p"."user_id",
            "unnest"("m"."tags") AS "tag",
            "p"."enabled"
           FROM ("public"."notification_preferences" "p"
             JOIN "public"."category_tag_map" "m" ON (("m"."category" = "p"."category")))
        )
 SELECT "expanded_tags"."user_id",
    COALESCE("array_agg"(DISTINCT "expanded_tags"."tag") FILTER (WHERE ("expanded_tags"."enabled" = true)), ARRAY[]::"text"[]) AS "resolved_tags",
    "count"(*) FILTER (WHERE ("expanded_tags"."enabled" = true)) AS "active_categories"
   FROM "expanded_tags"
  GROUP BY "expanded_tags"."user_id";


ALTER TABLE "public"."v_user_resolved_tags" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_user_suggest_throttle" AS
 SELECT "suggested_notifications"."user_id",
    "max"("suggested_notifications"."created_at") AS "last_sent_at",
    "count"(*) AS "total_sent"
   FROM "public"."suggested_notifications"
  GROUP BY "suggested_notifications"."user_id";


ALTER TABLE "public"."v_user_suggest_throttle" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_webpush_diag" AS
 SELECT "push_subscriptions"."endpoint",
    "push_subscriptions"."user_id",
    "push_subscriptions"."endpoint_type",
    COALESCE("push_subscriptions"."endpoint_type",
        CASE
            WHEN ("push_subscriptions"."endpoint" ~~ 'https://web.push.apple.com/%'::"text") THEN 'apns'::"text"
            WHEN ("push_subscriptions"."endpoint" ~~ 'https://fcm.googleapis.com/%'::"text") THEN 'fcm'::"text"
            WHEN ("push_subscriptions"."endpoint" ~~ 'https://updates.push.services.mozilla.com/%'::"text") THEN 'mozilla'::"text"
            ELSE 'unknown'::"text"
        END) AS "detected_provider",
    "split_part"("push_subscriptions"."endpoint", '/'::"text", 3) AS "endpoint_host",
    "push_subscriptions"."created_at",
    "push_subscriptions"."platform"
   FROM "public"."push_subscriptions"
  ORDER BY "push_subscriptions"."created_at" DESC;


ALTER TABLE "public"."v_webpush_diag" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."webpush_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "endpoint" "text" NOT NULL,
    "keys" "jsonb" NOT NULL,
    "device_info" "jsonb",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_used_at" timestamp with time zone
);


ALTER TABLE "public"."webpush_subscriptions" OWNER TO "postgres";


COMMENT ON TABLE "public"."webpush_subscriptions" IS 'M1SSION™ Web Push subscriptions storage - keys stored as JSONB';



CREATE OR REPLACE VIEW "public"."webpush_subscriptions_flat" AS
 SELECT "webpush_subscriptions"."id",
    "webpush_subscriptions"."user_id",
    "webpush_subscriptions"."endpoint",
    "webpush_subscriptions"."is_active",
    "webpush_subscriptions"."created_at",
    "webpush_subscriptions"."last_used_at",
    "webpush_subscriptions"."device_info",
    ("webpush_subscriptions"."keys" ->> 'p256dh'::"text") AS "p256dh",
    ("webpush_subscriptions"."keys" ->> 'auth'::"text") AS "auth"
   FROM "public"."webpush_subscriptions";


ALTER TABLE "public"."webpush_subscriptions_flat" OWNER TO "postgres";


COMMENT ON VIEW "public"."webpush_subscriptions_flat" IS 'Flattened view of webpush_subscriptions with extracted p256dh and auth keys';



